ction" onPress={()=>router.push('/admin/audit-log')}/></AdminPanel></View><View style={s.column}><Text style={s.section}>CONTROL PLANE</Text><AdminPanel><AdminRow icon="options-outline" title="Plan entitlements" subtitle="Card limits, Deal Desk, web access, and seats" onPress={()=>router.push('/admin/plans')}/><AdminRow icon="flag-outline" title="Feature flags" subtitle="Release capabilities safely by audience" onPress={()=>router.push('/admin/feature-flags')}/><AdminRow icon="lock-closed-outline" title="Roles & security" subtitle="Owner, admin, support, and analyst access" badge="OWNER" onPress={()=>router.push('/admin/roles')}/></AdminPanel></View></View><View style={s.recentHeader}><Text style={s.section}>RECENT ACCOUNTS</Text>{loading?<ActivityIndicator color={color.primaryBright}/>:null}</View><AdminPanel>{recent.length?recent.map(user=><AdminRow key={user.user_id} icon="person-outline" title={user.display_name||user.email||'Unnamed account'} subtitle={`${user.account_type} · ${user.subscription_status}`} badge={new Date(user.created_at).toLocaleDateString()} onPress={()=>router.push({pathname:'/admin/users',params:{q:user.email??''}})}/>):<View style={s.empty}><Text style={s.emptyTitle}>No account data yet</Text><Text style={s.emptyCopy}>Once the migration is installed, registered Supabase users will appear here.</Text></View>}</AdminPanel></ScrollView>
}
