import { Ionicons } from '@expo/vector-icons';
import { useLocalSearchParams } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Alert, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, useWindowDimensions, View } from 'react-native';
import { AdminPanel, AdminTopBar } from '@/components/admin';
import { color, radius, space, type } from '@/design';
import { listAdminUsers, type AdminUser, updateUserAccess } from '@/services/admin/admin-api';

const accountTypes=['free','collector','seller','store'];
const statuses=['free','trialing','active','past_due','canceled','suspended'];
