import { NextRequest, NextResponse } from "next/server";
import type { DeckCard, ManaColor } from "@/lib/deck-vault/types";

type Entry = { quantity: number; name: string; setCode?: string; collectorNumber?: string; board: "commander" | "main" | "sideboard" | "maybeboard" };

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const entries = Array.isArray(body.entries) ? (body.entries as Entry[]) : [];
    if (!entries.length) return NextResponse.json({ error: "No cards were supplied." }, { status: 400 });

    const cards: DeckCard[] = [];
    const unresolved: Entry[] = [];
    const colors = new Set<ManaColor>();
    let marketValue = 0;

    for (let index = 0; index < entries.length; index += 75) {
      const chunk = entries.slice(index, index + 75);
      const response = await fetch("https://api.scryfall.com/cards/collection", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json", "User-Agent": "TradingDocks-DeckImport/1.0" },
        body: JSON.stringify({ identifiers: chunk.map((entry) => entry.setCode && entry.collectorNumber ? { set: entry.setCode, collector_number: entry.collectorNumber } : { name: entry.name }) }),
        cache: "no-store",
      });
      if (!response.ok) { unresolved.push(...chunk); continue; }
      const payload = await response.json();
      const returned = payload.data ?? [];
      const byName = new Map<string, any>();
      const byPrinting = new Map<string, any>();
      for (const card of returned) {
        byName.set(String(card.name).toLowerCase(), card);
        byPrinting.set(`${String(card.set).toLowerCase()}:${String(card.collector_number).toLowerCase()}`, card);
      }

      chunk.forEach((entry) => {
        const printingKey = entry.setCode && entry.collectorNumber
          ? `${entry.setCode.toLowerCase()}:${entry.collectorNumber.toLowerCase()}`
          : "";
        const card = (printingKey ? byPrinting.get(printingKey) : undefined) ?? byName.get(entry.name.toLowerCase());
        if (!card) { unresolved.push(entry); return; }
        const face = card.card_faces?.find((item: any) => item.image_uris) ?? card;
        const identity = (card.color_identity?.length ? card.color_identity : card.colors?.length ? card.colors : ["C"]) as ManaColor[];
        identity.forEach((color) => colors.add(color));
        const price = Number(card.prices?.usd ?? card.prices?.usd_foil ?? 0);
        marketValue += price * entry.quantity;
        cards.push({
          id: `${card.id}-${entry.board}`,
          name: card.name,
          quantity: entry.quantity,
          manaValue: Number(card.cmc ?? 0),
          colors: identity,
          typeLine: card.type_line ?? "",
          category: inferCategory(card.type_line ?? "", card.oracle_text ?? ""),
          price,
          owned: false,
          image: face.image_uris?.normal ?? face.image_uris?.large ?? "",
          artCrop: face.image_uris?.art_crop ?? "",
          setCode: card.set ?? entry.setCode,
          collectorNumber: card.collector_number ?? entry.collectorNumber,
          gameChanger: Boolean(card.game_changer),
          board: entry.board,
        });
      });
    }

    return NextResponse.json({ cards, unresolved, colors: Array.from(colors), marketValue: Number(marketValue.toFixed(2)) });
  } catch (error) {
    console.error("Deck import resolution failed", error);
    return NextResponse.json({ error: "The imported cards could not be resolved." }, { status: 500 });
  }
}

function inferCategory(typeLine: string, oracleText: string) {
  const type = typeLine.toLowerCase();
  const oracle = oracleText.toLowerCase();
  if (type.includes("land")) return "Land";
  if (/draw (a|two|three|x|\d+) cards?/.test(oracle)) return "Card Draw";
  if (/destroy target|exile target|counter target spell/.test(oracle)) return "Removal";
  if (/destroy all|exile all/.test(oracle)) return "Board Wipe";
  if (/search your library for .* card/.test(oracle)) return "Tutor";
  if (/add \{|treasure token|search your library for .* land/.test(oracle)) return "Ramp";
  if (/hexproof|indestructible|phase out/.test(oracle)) return "Protection";
  if (type.includes("creature")) return "Creature";
  if (type.includes("artifact")) return "Artifact";
  if (type.includes("enchantment")) return "Enchantment";
  if (type.includes("planeswalker")) return "Planeswalker";
  if (type.includes("instant")) return "Instant";
  if (type.includes("sorcery")) return "Sorcery";
  return "Other";
}

import { NextRequest, NextResponse } from "next/server";

export async function POST(request: NextRequest) {
  try {
    const { url } = await request.json();
    const id = extractMoxfieldId(String(url ?? ""));
    if (!id) return NextResponse.json({ error: "Enter a valid public Moxfield deck URL." }, { status: 400 });

    const endpoints = [
      `https://api2.moxfield.com/v3/decks/all/${id}`,
      `https://api2.moxfield.com/v2/decks/all/${id}`,
    ];

    let payload: any = null;
    for (const endpoint of endpoints) {
      const response = await fetch(endpoint, {
        headers: {
          Accept: "application/json",
          "User-Agent": "TradingDocks-DeckVault/1.0 (+deck import)",
          Referer: `https://www.moxfield.com/decks/${id}`,
        },
        cache: "no-store",
      });
      if (response.ok) { payload = await response.json(); break; }
    }

    if (!payload) {
      return NextResponse.json({ error: "Moxfield did not return this deck. Confirm that the deck is public and try again." }, { status: 502 });
    }

    const lines: string[] = [];
    appendBoard(lines, "Commander", payload.commanders ?? payload.commander);
    appendBoard(lines, "Deck", payload.mainboard ?? payload.mainBoard);
    appendBoard(lines, "Sideboard", payload.sideboard ?? payload.sideBoard);
    appendBoard(lines, "Maybeboard", payload.maybeboard ?? payload.maybeBoard);

    const deckList = lines.join("\n").trim();
    const cardCount = countBoard(payload.commanders ?? payload.commander) + countBoard(payload.mainboard ?? payload.mainBoard) + countBoard(payload.sideboard ?? payload.sideBoard) + countBoard(payload.maybeboard ?? payload.maybeBoard);

    return NextResponse.json({
      source: "Moxfield",
      name: payload.name ?? payload.deckName ?? "Imported Moxfield Deck",
      format: payload.format ?? payload.formatName ?? "Commander",
      deckList,
      cardCount,
    });
  } catch (error) {
    console.error("Moxfield import failed", error);
    return NextResponse.json({ error: "The Moxfield deck could not be loaded right now." }, { status: 500 });
  }
}

function extractMoxfieldId(input: string) {
  const direct = input.trim().match(/^[A-Za-z0-9_-]{8,}$/)?.[0];
  if (direct) return direct;
  try {
    const parsed = new URL(input.trim());
    if (!/(^|\.)moxfield\.com$/i.test(parsed.hostname)) return null;
    return parsed.pathname.match(/\/decks\/([A-Za-z0-9_-]+)/)?.[1] ?? null;
  } catch { return null; }
}

function appendBoard(lines: string[], heading: string, board: any) {
  const entries = normalizeBoard(board);
  if (!entries.length) return;
  if (lines.length) lines.push("");
  lines.push(heading);
  for (const entry of entries) {
    const card = entry.card ?? entry;
    const quantity = Number(entry.quantity ?? entry.count ?? card.quantity ?? 1);
    const name = card.name ?? entry.name;
    if (!name) continue;
    const set = card.set ?? card.setCode ?? card.set_code;
    const collector = card.cn ?? card.collectorNumber ?? card.collector_number;
    lines.push(`${quantity} ${name}${set ? ` (${String(set).toUpperCase()})` : ""}${collector ? ` ${collector}` : ""}`);
  }
}

function normalizeBoard(board: any): any[] {
  if (!board) return [];
  if (Array.isArray(board)) return board;
  if (Array.isArray(board.cards)) return board.cards;
  if (typeof board === "object") return Object.values(board);
  return [];
}

function countBoard(board: any) {
  return normalizeBoard(board).reduce((sum, entry) => sum + Number(entry.quantity ?? entry.count ?? entry.card?.quantity ?? 1), 0);
}

import {
  NextRequest,
  NextResponse,
} from "next/server";

type InputCard = {
  id: string;
  name: string;
  quantity: number;
  colors: string[];
  board?: string;
  typeLine?: string;
  setCode?: string;
  collectorNumber?: string;
};

type InventoryItem = {
  inventoryId: string;
  name: string;
  quantity: number;
  location: string;
  locationId?: string;
  locationType?: string;
  binderPage?: number;
  binderSlot?: string;
  condition: string;
  printing?: string;
  platform?: string;
  listingId?: string;
  reservedForDeck?: boolean;
};

const FORMAT_CODE: Record<string, string> = {
  EDH: "commander",
  "Pauper EDH": "paupercommander",
  Standard: "standard",
  Modern: "modern",
  Pioneer: "pioneer",
  Legacy: "legacy",
  Vintage: "vintage",
  Alchemy: "alchemy",
  Premodern: "premodern",
  Pauper: "pauper",
};

export async function POST(
  request: NextRequest,
) {
  try {
    const body = await request.json();
    const cards = Array.isArray(body.cards)
      ? (body.cards as InputCard[])
      : [];
    const format = String(
      body.format ?? "EDH",
    );
    const inventory = Array.isArray(
      body.inventory,
    )
      ? (body.inventory as InventoryItem[])
      : [];

    const enriched = await enrich(cards);
    const formatCode =
      FORMAT_CODE[format] ?? "commander";

    const commanders = enriched.filter(
      (card) =>
        card.board === "commander",
    );
    const commanderFormat =
      format === "EDH" ||
      format === "Pauper EDH";
    const main = enriched.filter(
      (card) =>
        (!commanderFormat ||
          card.board !== "commander") &&
        card.board !== "sideboard" &&
        card.board !== "maybeboard",
    );

    const issues: Array<{
      cardId?: string;
      cardName?: string;
      severity: "error" | "warning";
      code: string;
      message: string;
    }> = [];

    for (const card of enriched) {
      const legality =
        card.legalities?.[formatCode];

      if (
        legality === "banned" ||
        legality === "not_legal" ||
        legality === "restricted"
      ) {
        issues.push({
          cardId: card.id,
          cardName: card.name,
          severity:
            legality === "restricted"
              ? "warning"
              : "error",
          code: legality,
          message:
            legality === "banned"
              ? `This card is banned in ${format}.`
              : legality === "restricted"
                ? `This card is restricted in ${format}.`
                : `This card is not legal in ${format}.`,
        });
      }
    }

    const singleton = commanderFormat;

    for (const card of main) {
      const basic =
        /\bBasic Land\b/i.test(
          card.typeLine ?? "",
        ) ||
        /^(Plains|Island|Swamp|Mountain|Forest|Wastes)$/i.test(
          card.name,
        );

      if (
        !basic &&
        ((singleton && card.quantity > 1) ||
          (!singleton &&
            format !== "Vintage" &&
            card.quantity > 4) ||
          (format === "Vintage" &&
            card.legalities?.vintage === "restricted" &&
            card.quantity > 1))
      ) {
        issues.push({
          cardId: card.id,
          cardName: card.name,
          severity: "error",
          code: "copy_limit",
          message: singleton
            ? `This card exceeds the singleton limit for ${format}.`
            : format === "Vintage" &&
                card.legalities?.vintage === "restricted"
              ? "Vintage restricted cards are limited to one copy."
            : `This card exceeds the four-copy limit for ${format}.`,
        });
      }
    }

    const commandZoneCheck =
      validateCommandZone(
        commanders,
        format,
      );
    issues.push(...commandZoneCheck);

    const expectedMain =
      commanderFormat ? 98 +
        (commanders.length === 1 ? 1 : 0)
      : null;
    const mainQuantity = main.reduce(
      (sum, card) =>
        sum + card.quantity,
      0,
    );

    if (
      expectedMain &&
      mainQuantity +
        commanders.length !==
        100
    ) {
      issues.push({
        severity: "warning",
        code: "deck_size",
        message: `${format} expects ${
          100
        } total cards. This deck currently has ${
          mainQuantity +
          commanders.length
        }.`,
      });
    }

    const tokenAnalysis =
      await analyzeTokens(enriched);
    const tokens =
      tokenAnalysis.tokens;
    const ownership = buildOwnership(
      enriched,
      inventory,
    );

    return NextResponse.json({
      valid: !issues.some(
        (issue) =>
          issue.severity === "error",
      ),
      issues,
      tokens,
      tokenSupport:
        tokenAnalysis.support,
      ownership,
      cards: enriched.map((card) => {
        const issue = issues.find(
          (entry) =>
            entry.cardId === card.id,
        );
        return {
          id: card.id,
          legalityStatus:
            issue?.code === "banned"
              ? "banned"
              : issue?.code ===
                    "restricted"
                ? "restricted"
                : issue
                  ? "not_legal"
                  : "legal",
          legalityMessage:
            issue?.message ?? "",
        };
      }),
    });
  } catch (error) {
    console.error(
      "Deck intelligence error",
      error,
    );
    return NextResponse.json(
      {
        error:
          "Deck intelligence could not complete the analysis.",
      },
      { status: 500 },
    );
  }
}

async function enrich(
  cards: InputCard[],
) {
  const resolvedByName =
    new Map<string, any>();
  const resolvedByPrinting =
    new Map<string, any>();
  const resolvedByUuid =
    new Map<string, any>();

  for (
    let index = 0;
    index < cards.length;
    index += 75
  ) {
    const chunk = cards.slice(
      index,
      index + 75,
    );

    const identifiers = chunk.map(
      (card) => {
        if (
          card.setCode &&
          card.collectorNumber
        ) {
          return {
            set: card.setCode,
            collector_number:
              card.collectorNumber,
          };
        }

        const scryfallId =
          extractScryfallId(card.id);

        if (scryfallId) {
          return {
            id: scryfallId,
          };
        }

        return {
          name: card.name,
        };
      },
    );

    const response = await fetch(
      "https://api.scryfall.com/cards/collection",
      {
        method: "POST",
        headers: {
          Accept: "application/json",
          "Content-Type":
            "application/json",
          "User-Agent":
            "TradingDocks-DeckIntelligence/2.1",
        },
        body: JSON.stringify({
          identifiers,
        }),
        cache: "no-store",
      },
    );

    if (!response.ok) {
      continue;
    }

    const payload =
      await response.json();

    for (const card of payload.data ?? []) {
      resolvedByName.set(
        String(card.name).toLowerCase(),
        card,
      );

      resolvedByUuid.set(
        String(card.id).toLowerCase(),
        card,
      );

      resolvedByPrinting.set(
        `${String(
          card.set,
        ).toLowerCase()}:${String(
          card.collector_number,
        ).toLowerCase()}`,
        card,
      );
    }
  }

  return cards.map((card) => {
    const printingKey =
      card.setCode &&
      card.collectorNumber
        ? `${card.setCode.toLowerCase()}:${card.collectorNumber.toLowerCase()}`
        : "";

    const scryfallId =
      extractScryfallId(card.id);

    const scryfall =
      (printingKey
        ? resolvedByPrinting.get(
            printingKey,
          )
        : undefined) ??
      (scryfallId
        ? resolvedByUuid.get(
            scryfallId,
          )
        : undefined) ??
      resolvedByName.get(
        card.name.toLowerCase(),
      );

    const faces =
      scryfall?.card_faces ?? [];

    const oracleText = [
      scryfall?.oracle_text,
      ...faces.map(
        (face: any) =>
          face.oracle_text,
      ),
    ]
      .filter(Boolean)
      .join(" // ");

    return {
      ...card,
      typeLine:
        scryfall?.type_line ??
        card.typeLine ??
        "",
      oracleText,
      legalities:
        scryfall?.legalities ?? {},
      keywords:
        scryfall?.keywords ?? [],
      allParts:
        scryfall?.all_parts ?? [],
      image:
        scryfall?.image_uris
          ?.normal ??
        faces[0]?.image_uris
          ?.normal ??
        "",
      colorIdentity:
        scryfall?.color_identity ??
        card.colors ??
        [],
      scryfallResolved:
        Boolean(scryfall),
    };
  });
}

function extractScryfallId(
  rawId: string,
) {
  const match = rawId.match(
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/i,
  );

  return match?.[0]?.toLowerCase() ?? "";
}

function validateCommandZone(
  commanders: any[],
  format: string,
) {
  const issues: Array<{
    cardId?: string;
    cardName?: string;
    severity: "error" | "warning";
    code: string;
    message: string;
  }> = [];

  const supportsCommanders =
    format === "EDH" ||
    format === "Pauper EDH";

  if (!supportsCommanders) {
    return issues;
  }

  if (!commanders.length) {
    issues.push({
      severity: "error",
      code: "missing_commander",
      message:
        "This format requires a commander.",
    });
    return issues;
  }

  if (commanders.length > 2) {
    issues.push({
      severity: "error",
      code: "too_many_commanders",
      message:
        "The command zone supports at most two commanders.",
    });
  }

  if (commanders.length === 2) {
    const [first, second] = commanders;
    const a = String(
      first.oracleText ?? "",
    ).toLowerCase();
    const b = String(
      second.oracleText ?? "",
    ).toLowerCase();

    const legalPair =
      (a.includes("partner") &&
        b.includes("partner")) ||
      (a.includes(
        "friends forever",
      ) &&
        b.includes(
          "friends forever",
        )) ||
      (a.includes(
        "choose a background",
      ) &&
        String(
          second.typeLine ?? "",
        ).includes(
          "Legendary Enchantment — Background",
        )) ||
      (b.includes(
        "choose a background",
      ) &&
        String(
          first.typeLine ?? "",
        ).includes(
          "Legendary Enchantment — Background",
        )) ||
      (a.includes(
        "doctor's companion",
      ) &&
        String(
          second.typeLine ?? "",
        ).includes("Doctor")) ||
      (b.includes(
        "doctor's companion",
      ) &&
        String(
          first.typeLine ?? "",
        ).includes("Doctor"));

    if (!legalPair) {
      issues.push({
        severity: "error",
        code: "illegal_partner_pair",
        message:
          "These two cards are not a legal Partner, Friends Forever, Background, or Doctor's Companion command-zone pair.",
      });
    }
  }

  return issues;
}

async function analyzeTokens(
  cards: any[],
) {
  const tokenMap = new Map<
    string,
    {
      name: string;
      image?: string;
      createdBy: Set<string>;
      score: number;
    }
  >();

  const support: Array<{
    cardName: string;
    role:
      | "multiplier"
      | "payoff"
      | "copier"
      | "consumer";
    explanation: string;
  }> = [];

  const supportKeys = new Set<string>();

  const addSupport = (
    cardName: string,
    role:
      | "multiplier"
      | "payoff"
      | "copier"
      | "consumer",
    explanation: string,
  ) => {
    const key = `${cardName}:${role}`;
    if (supportKeys.has(key)) return;
    supportKeys.add(key);
    support.push({
      cardName,
      role,
      explanation,
    });
  };

  const addToken = (
    rawName: string,
    source: string,
    score = 1,
  ) => {
    const name =
      normalizeRealTokenName(rawName);
    if (!name) return;

    const key = name.toLowerCase();
    const existing =
      tokenMap.get(key) ?? {
        name,
        image: "",
        createdBy:
          new Set<string>(),
        score: 0,
      };

    existing.createdBy.add(source);
    existing.score += score;
    tokenMap.set(key, existing);
  };

  for (const card of cards) {
    const oracleText = String(
      card.oracleText ?? "",
    ).replace(/\n/g, " ");

    // Scryfall related token objects are the most authoritative source.
    for (const part of card.allParts ?? []) {
      const component = String(
        part.component ?? "",
      ).toLowerCase();
      const partType = String(
        part.type_line ?? "",
      ).toLowerCase();

      if (
        component === "token" ||
        partType.includes("token")
      ) {
        addToken(
          part.name,
          card.name,
          10,
        );
      }
    }

    classifyTokenSupport(
      card.name,
      oracleText,
      addSupport,
    );

    // Only parse clauses that explicitly name a token immediately before
    // the word token. This avoids fragments such as "twice of those."
    const explicitPatterns = [
      /(?:create|creates|created|creating)\s+(?:up to\s+)?(?:a|an|one|two|three|four|five|six|seven|eight|nine|ten|x|that many|\d+)?\s*(?:tapped(?: and attacking)?\s+)?(?:legendary\s+)?(?:colorless\s+|white\s+|blue\s+|black\s+|red\s+|green\s+|multicolored\s+)*(?:\d+\/\d+\s+)?([A-Za-z][A-Za-z' -]{0,28}?)\s+(?:artifact\s+|enchantment\s+|creature\s+)*tokens?\b/gi,
      /(?:plus|and)\s+(?:an?|one|two|three|that many|\d+)\s+(?:additional\s+)?(?:\d+\/\d+\s+)?(?:colorless\s+|white\s+|blue\s+|black\s+|red\s+|green\s+)*([A-Za-z][A-Za-z' -]{0,28}?)\s+(?:artifact\s+|creature\s+)*tokens?\b/gi,
      /(?:an?|one|two|three|\d+)\s+additional\s+([A-Za-z][A-Za-z' -]{0,28}?)\s+(?:artifact\s+|creature\s+)*tokens?\b/gi,
      /tokens?\s+named\s+([A-Za-z][A-Za-z' -]{1,35})/gi,
    ];

    for (const pattern of explicitPatterns) {
      for (
        const match of oracleText.matchAll(
          pattern,
        )
      ) {
        const candidate =
          normalizeRealTokenName(
            match[1],
          );

        if (
          candidate &&
          isPlausibleTokenName(
            candidate,
          )
        ) {
          addToken(
            candidate,
            card.name,
            4,
          );
        }
      }
    }

    // Known token nouns are accepted only when the same sentence explicitly
    // says that token is created or is created as an additional token.
    for (const tokenName of KNOWN_TOKEN_NAMES) {
      const escaped =
        escapeRegExp(tokenName);
      const explicitCreation =
        new RegExp(
          `(?:create|creates|created|creating|plus|additional)[^.]{0,90}\\b${escaped}\\b[^.]{0,35}\\btokens?\\b`,
          "i",
        );

      if (
        explicitCreation.test(
          oracleText,
        )
      ) {
        addToken(
          tokenName,
          card.name,
          5,
        );
      }
    }

    if (
      /\bemblem with\b/i.test(
        oracleText,
      )
    ) {
      addToken(
        `${card.name} Emblem`,
        card.name,
        5,
      );
    }
  }

  const tokens = Array.from(
    tokenMap.values(),
  )
    .filter((token) =>
      isPlausibleTokenName(
        token.name,
      ),
    )
    .sort(
      (a, b) =>
        b.score - a.score ||
        b.createdBy.size -
          a.createdBy.size ||
        a.name.localeCompare(b.name),
    )
    .slice(0, 40);

  await Promise.all(
    tokens.map(async (token) => {
      const queries = [
        `t:token name:"${token.name}"`,
        `t:token "${token.name}"`,
      ];

      for (const query of queries) {
        try {
          const params =
            new URLSearchParams({
              q: query,
              unique: "prints",
              order: "released",
              dir: "desc",
            });
          const response = await fetch(
            `https://api.scryfall.com/cards/search?${params.toString()}`,
            {
              headers: {
                Accept:
                  "application/json",
                "User-Agent":
                  "TradingDocks-TokenClassifier/1.0",
              },
              next: {
                revalidate: 86400,
              },
            },
          );

          if (!response.ok) continue;
          const payload =
            await response.json();
          token.image =
            payload.data?.[0]
              ?.image_uris?.normal ??
            payload.data?.[0]
              ?.card_faces?.[0]
              ?.image_uris?.normal ??
            "";

          if (token.image) break;
        } catch {}
      }
    }),
  );

  const displayTokens = tokens.filter(
    (token) =>
      Boolean(token.image) ||
      KNOWN_TOKEN_NAMES.some(
        (known) =>
          known.toLowerCase() ===
          token.name.toLowerCase(),
      ) ||
      /\bEmblem$/i.test(token.name),
  );

  return {
    tokens: displayTokens.map((token) => ({
      name: token.name,
      image: token.image,
      createdBy: Array.from(
        token.createdBy,
      ),
      estimatedQuantity:
        "One token card",
    })),
    support: support.sort(
      (a, b) =>
        roleOrder(a.role) -
          roleOrder(b.role) ||
        a.cardName.localeCompare(
          b.cardName,
        ),
    ),
  };
}

const KNOWN_TOKEN_NAMES = [
  "Angel",
  "Army",
  "Beast",
  "Bird",
  "Blood",
  "Clue",
  "Construct",
  "Dragon",
  "Eldrazi Spawn",
  "Eldrazi Scion",
  "Elephant",
  "Faerie",
  "Food",
  "Goblin",
  "Gold",
  "Golem",
  "Human",
  "Insect",
  "Knight",
  "Map",
  "Plant",
  "Powerstone",
  "Rat",
  "Role",
  "Saproling",
  "Servo",
  "Soldier",
  "Spider",
  "Spirit",
  "Squirrel",
  "Thopter",
  "Treasure",
  "Vampire",
  "Warrior",
  "Wolf",
  "Zombie",
];

function classifyTokenSupport(
  cardName: string,
  oracleText: string,
  addSupport: (
    cardName: string,
    role:
      | "multiplier"
      | "payoff"
      | "copier"
      | "consumer",
    explanation: string,
  ) => void,
) {
  if (
    /(?:twice|double)[^.]{0,80}(?:token|tokens)|additional token for each|that many of those tokens/i.test(
      oracleText,
    )
  ) {
    addSupport(
      cardName,
      "multiplier",
      "Increases the number of tokens created but does not define a new token type.",
    );
  }

  if (
    /whenever[^.]{0,100}(?:token|tokens)[^.]{0,80}(?:dies|die|leave|leaves|enters|enter|created)|for each token you control|tokens you control get|creature tokens you control/i.test(
      oracleText,
    )
  ) {
    addSupport(
      cardName,
      "payoff",
      "Rewards, modifies, or triggers from tokens already being created or controlled.",
    );
  }

  if (
    /\bpopulate\b|create a token that's a copy|token that's a copy|copy target token/i.test(
      oracleText,
    )
  ) {
    addSupport(
      cardName,
      "copier",
      "Copies or populates an existing token and does not require a separate new token type.",
    );
  }

  if (
    /sacrifice (?:a|another|one or more) token|remove .* counter from .* token|tap .* tokens you control/i.test(
      oracleText,
    )
  ) {
    addSupport(
      cardName,
      "consumer",
      "Uses tokens as a resource rather than creating a named token.",
    );
  }
}

function normalizeRealTokenName(
  rawName: string,
) {
  const cleaned = rawName
    .replace(/\([^)]*\)/g, " ")
    .replace(/\b\d+\/\d+\b/g, " ")
    .replace(
      /\b(?:a|an|one|two|three|four|five|six|seven|eight|nine|ten|x|that many|twice|additional|tapped|attacking|legendary|colorless|white|blue|black|red|green|multicolored|artifact|enchantment|creature|token|tokens|with|and)\b/gi,
      " ",
    )
    .replace(/\s+/g, " ")
    .trim();

  if (!cleaned) return "";

  return cleaned.replace(
    /\b\w/g,
    (letter) =>
      letter.toUpperCase(),
  );
}

function isPlausibleTokenName(
  name: string,
) {
  if (
    name.length < 2 ||
    name.length > 45
  ) {
    return false;
  }

  const rejected =
    /^(?:of those|twice of those|or more|or sacrifice|additional|additional food|that many|those|one or more|card|creature|artifact|enchantment|copy|token|tokens|that'?s copy of target|a copy of target|copy of target|target token|target creature|target artifact)$/i;

  if (rejected.test(name)) {
    return false;
  }

  if (
    /\b(?:that'?s|target|copy of|of target|or more|or sacrifice|twice of those|of those)\b/i.test(
      name,
    )
  ) {
    return false;
  }

  const words = name.split(/\s+/);
  if (words.length > 5) {
    return false;
  }

  return true;
}

function escapeRegExp(
  value: string,
) {
  return value.replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&",
  );
}

function roleOrder(
  role:
    | "multiplier"
    | "payoff"
    | "copier"
    | "consumer",
) {
  return {
    multiplier: 0,
    copier: 1,
    payoff: 2,
    consumer: 3,
  }[role];
}

function buildOwnership(
  cards: any[],
  inventory: InventoryItem[],
) {
  return cards
    .filter(
      (card) =>
        card.board !== "commander" ||
        card.quantity > 0,
    )
    .map((card) => {
      const normalizedCardName = card.name.trim().toLocaleLowerCase();
      const matches = inventory.filter(
        (item) =>
          item.name.trim().toLocaleLowerCase() === normalizedCardName &&
          Number(item.quantity) > 0,
      );
      const owned = matches.reduce(
        (sum, item) =>
          sum + item.quantity,
        0,
      );

      return {
        cardId: card.id,
        cardName: card.name,
        required: card.quantity,
        owned,
        matches,
      };
    });
}

import { NextResponse } from "next/server";
import { processWorkspaceBacklog } from "@/lib/email/process-inbound";
import { createAdminClient } from "@/lib/supabase/admin";
import { requireApiCapability } from "@/lib/platform/server-access";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST() {
  const capability = await requireApiCapability("orders.manage");
  if (!capability.ok) return capability.response;
  const { supabase } = capability;
  const user = capability.user!;
  const id = capability.access.workspaceId;
  if (!id) return NextResponse.json({ error: "No active workspace." }, { status: 409 });
  try {
    const admin = createAdminClient();
    const result = await processWorkspaceBacklog(admin, id, 250);

    const { data: mailbox } = await admin
      .from("inbound_email_mailboxes")
      .select("status,verified_at,last_received_at,email_provider,marketplace_id")
      .eq("workspace_id", id)
      .maybeSingle();

    const mailboxReady = Boolean(
      mailbox &&
        (mailbox.status === "active" || mailbox.verified_at || mailbox.last_received_at),
    );

    if (mailbox) {
      const { error: connectionError } = await admin
        .from("marketplace_connections")
        .upsert(
          {
            user_id: user.id,
            marketplace_id: mailbox.marketplace_id || "tcgplayer",
            connection_method: "email",
            status: mailboxReady ? "ready" : "setup_required",
            settings: {
              setup_started: true,
              email_provider: mailbox.email_provider,
              permanent_inbound_address: true,
              mailbox_status: mailbox.status,
              verified_at: mailbox.verified_at,
              last_received_at: mailbox.last_received_at,
              last_email_import: new Date().toISOString(),
              imported_messages: result.imported,
              review_messages: result.review,
              failed_messages: result.failed,
            },
            last_sync_at: mailbox.last_received_at ?? new Date().toISOString(),
            updated_at: new Date().toISOString(),
          },
          { onConflict: "user_id,marketplace_id" },
        );

      if (connectionError) throw connectionError;
    }

    return NextResponse.json({
      ...result,
      mailboxStatus: mailbox?.status ?? "pending",
      connectionStatus: mailboxReady ? "ready" : "setup_required",
    });
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : "Email processing failed." }, { status: 500 });
  }
}

import { notFound } from "next/navigation";
import { BookOpen, ChevronLeft, ChevronRight, MessageCircle, Share2 } from "lucide-react";
import { createAdminClient } from "@/lib/supabase/admin";

type DataRow = { data: Record<string, unknown> };

export default async function PublicBinderPage({ params, searchParams }: { params: Promise<{ username: string; binderSlug: string }>; searchParams: Promise<{ page?: string }> }) {
  const [{ username, binderSlug }, query] = await Promise.all([params, searchParams]);
  const admin = createAdminClient();
  const { data: profile } = await admin.from("collector_profiles").select("*").eq("username", username).eq("is_public", true).maybeSingle();
  if (!profile) notFound();
  const { data: binder } = await admin.from("portfolio_binders").select("*").eq("user_id", profile.user_id).eq("slug", binderSlug).eq("visibility", "public").maybeSingle();
  if (!binder) notFound();

  const [{ data: locationRow }, { data: itemRows }] = await Promise.all([
    admin.from("inventory_locations").select("data").eq("user_id", profile.user_id).eq("id", binder.location_id).maybeSingle(),
    admin.from("inventory_items").select("data").eq("user_id", profile.user_id).eq("location_id", binder.location_id),
  ]);
  const location = (locationRow?.data ?? {}) as Record<string, unknown>;
  const cards = ((itemRows ?? []) as DataRow[]).map((row) => row.data);
  const pageCount = typeof location.binderPages === "number" ? location.binderPages : 20;
  const currentPage = Math.min(pageCount, Math.max(1, Number(query.page ?? 1)));
  const leftPage = currentPage % 2 === 0 ? currentPage : currentPage;
  const rightPage = Math.min(pageCount, leftPage + 1);

  return <main className="min-h-screen bg-[radial-gradient(circle_at_top,rgba(139,92,246,.14),transparent_34%),#020911] px-3 py-5 text-white sm:px-6"><div className="mx-auto max-w-[1560px]"><header className="flex flex-col gap-4 rounded-[24px] border border-white/[0.08] bg-[#06131d]/90 p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-[9px] font-bold uppercase tracking-[0.17em] text-cyan-300">@{profile.username} · Collector Portfolio</p><h1 className="mt-2 text-2xl font-semibold text-white">{binder.title}</h1><p className="mt-1 text-[10px] text-slate-600">{binder.description}</p></div><div className="flex gap-2"><button className="inline-flex h-10 items-center gap-2 rounded-xl border border-white/[0.08] px-3 text-[10px] font-semibold text-white"><Share2 className="h-4 w-4" /> Share</button>{binder.is_trade_binder ? <button className="inline-flex h-10 items-center gap-2 rounded-xl bg-emerald-300 px-3 text-[10px] font-bold text-[#052018]"><MessageCircle className="h-4 w-4" /> Interested list</button> : null}</div></header><section className="mt-5 rounded-[30px] border border-violet-300/[0.14] bg-[linear-gradient(145deg,#130d21,#07131d_50%,#120d20)] p-4 shadow-[0_34px_110px_rgba(0,0,0,.48)] sm:p-7"><div className="grid gap-4 lg:grid-cols-2"><BinderPage title={`Page ${leftPage}`} cards={cards.filter((card) => card.binderPage === leftPage)} binder={binder} /><BinderPage title={`Page ${rightPage}`} cards={cards.filter((card) => card.binderPage === rightPage)} binder={binder} /></div><div className="mt-5 flex items-center justify-between"><a href={`?page=${Math.max(1,leftPage-2)}`} className="inline-flex h-10 items-center gap-2 rounded-xl border border-white/[0.08] px-3 text-[10px] font-semibold text-slate-300"><ChevronLeft className="h-4 w-4" /> Previous spread</a><span className="text-[10px] text-slate-600">Pages {leftPage}–{rightPage} of {pageCount}</span><a href={`?page=${Math.min(pageCount,leftPage+2)}`} className="inline-flex h-10 items-center gap-2 rounded-xl border border-white/[0.08] px-3 text-[10px] font-semibold text-slate-300">Next spread <ChevronRight className="h-4 w-4" /></a></div></section></div></main>;
}

function BinderPage({ title, cards, binder }: { title: string; cards: Record<string, unknown>[]; binder: Record<string, unknown> }) {
  return <article className="rounded-[24px] border border-white/[0.10] bg-[radial-gradient(circle_at_top,rgba(139,92,246,.10),transparent_38%),linear-gradient(145deg,#171126,#0b151f)] p-4 shadow-[inset_0_0_70px_rgba(0,0,0,.28),0_20px_55px_rgba(0,0,0,.30)]"><div className="mb-4 flex items-center justify-between"><span className="text-[9px] font-bold uppercase tracking-[0.15em] text-violet-200">{title}</span><BookOpen className="h-4 w-4 text-slate-700" /></div><div className="grid grid-cols-3 gap-3">{Array.from({ length: 9 }, (_, index) => { const card = cards.sort((a,b) => String(a.binderSlot ?? "").localeCompare(String(b.binderSlot ?? "")))[index]; return <div key={String(card?.id ?? index)} className="group relative aspect-[.716] overflow-hidden rounded-xl border border-white/[0.08] bg-black/25 shadow-[0_12px_28px_rgba(0,0,0,.34)]">{typeof card?.imageUrl === "string" ? <img src={card.imageUrl} alt={String(card.name ?? "Card")} className="h-full w-full object-cover transition duration-300 group-hover:scale-105" /> : null}{card && binder.show_values && typeof card.value === "number" ? <span className="absolute bottom-2 right-2 rounded-md bg-black/75 px-1.5 py-1 text-[8px] font-semibold text-emerald-300">${card.value.toFixed(2)}</span> : null}</div>; })}</div></article>;
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { BookOpen, CircleDollarSign, Globe2, Layers3, MessageCircle, Share2, Star } from "lucide-react";
import { createAdminClient } from "@/lib/supabase/admin";

type DataRow = { data: Record<string, unknown> };

export default async function PublicCollectorPage({ params }: { params: Promise<{ username: string }> }) {
  const { username } = await params;
  const admin = createAdminClient();
  const { data: profile } = await admin.from("collector_profiles").select("*").eq("username", username).eq("is_public", true).maybeSingle();
  if (!profile) notFound();

  const { data: binders } = await admin.from("portfolio_binders").select("*").eq("user_id", profile.user_id).eq("visibility", "public").order("portfolio_order");
  const locationIds = (binders ?? []).map((binder) => binder.location_id);
  const [{ data: locationRows }, { data: itemRows }] = await Promise.all([
    admin.from("inventory_locations").select("id,data").eq("user_id", profile.user_id).in("id", locationIds.length ? locationIds : ["__none__"]),
    admin.from("inventory_items").select("data").eq("user_id", profile.user_id).in("location_id", locationIds.length ? locationIds : ["__none__"]),
  ]);

  const items = ((itemRows ?? []) as DataRow[]).map((row) => row.data);
  const views = (binders ?? []).map((binder) => {
    const cards = items.filter((item) => item.locationId === binder.location_id);
    return {
      ...binder,
      cardCount: cards.reduce((sum, card) => sum + (typeof card.quantity === "number" ? card.quantity : 1), 0),
      value: cards.reduce((sum, card) => sum + (typeof card.value === "number" ? card.value : 0), 0),
      preview: cards.filter((card) => typeof card.imageUrl === "string").slice(0, 4),
    };
  });
  const totalCards = views.reduce((sum, binder) => sum + binder.cardCount, 0);
  const totalValue = views.reduce((sum, binder) => sum + binder.value, 0);

  return (
    <main className="min-h-screen bg-[radial-gradient(circle_at_top_right,rgba(139,92,246,.16),transparent_32%),radial-gradient(circle_at_top_left,rgba(34,211,238,.10),transparent_32%),#020911] px-4 py-7 text-white sm:px-8">
      <div className="mx-auto max-w-[1500px]">
        <header className="relative overflow-hidden rounded-[32px] border border-violet-300/[0.17] bg-[linear-gradient(135deg,#0b1e2c,#071522_52%,#160d28)] p-7 shadow-[0_38px_140px_rgba(0,0,0,.48)] sm:p-10">
          <div className="pointer-events-none absolute -right-24 -top-24 h-80 w-80 rounded-full bg-violet-500/[0.18] blur-[120px]" />
          <div className="relative flex flex-col gap-7 lg:flex-row lg:items-end lg:justify-between">
            <div>
              <span className="inline-flex items-center gap-2 rounded-full border border-cyan-300/[0.17] bg-cyan-300/[0.055] px-3 py-2 text-[10px] font-semibold text-cyan-100"><Globe2 className="h-4 w-4" /> Trading Docks Collector Portfolio</span>
              <h1 className="mt-5 text-4xl font-semibold tracking-[-0.055em] sm:text-6xl">{profile.display_name}</h1>
              <p className="mt-2 text-sm font-semibold text-violet-200">@{profile.username}</p>
              {profile.bio ? <p className="mt-4 max-w-2xl text-sm leading-7 text-slate-400">{profile.bio}</p> : null}
              {profile.show_location && profile.location ? <p className="mt-3 text-[11px] text-slate-600">{profile.location}</p> : null}
            </div>
            <div className="grid grid-cols-3 gap-2">
              <Stat icon={Layers3} label="Cards" value={String(totalCards)} />
              <Stat icon={BookOpen} label="Binders" value={String(views.length)} />
              <Stat icon={CircleDollarSign} label="Value" value={profile.show_collection_value ? money(totalValue) : "Private"} />
            </div>
          </div>
        </header>

        <section className="mt-6">
          <div className="flex items-end justify-between"><div><p className="text-[9px] font-bold uppercase tracking-[0.18em] text-cyan-300">Public bookshelf</p><h2 className="mt-2 text-2xl font-semibold text-white">Featured collections</h2></div><button className="inline-flex h-10 items-center gap-2 rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 text-[10px] font-semibold text-white"><Share2 className="h-4 w-4" /> Share profile</button></div>
          {views.length ? <div className="mt-6 grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{views.map((binder) => <Link key={binder.id} href={`/collectors/${profile.username}/${binder.slug}`} className="group"><div className="relative aspect-[.76] overflow-hidden rounded-[24px] border border-white/[0.13] shadow-[0_26px_68px_rgba(0,0,0,.42)] transition duration-300 group-hover:-translate-y-1.5" style={{ background: `radial-gradient(circle at 70% 10%,${binder.accent_color}33,transparent 34%),linear-gradient(145deg,${binder.cover_color},#020617)` }}><div className="absolute inset-y-0 left-0 w-5 bg-black/25" /><div className="absolute inset-0 flex flex-col justify-between p-5"><div className="flex justify-between"><span className="rounded-full border border-white/[0.13] bg-black/20 px-2.5 py-1 text-[8px] font-bold uppercase tracking-[0.14em] text-white/70">{binder.is_trade_binder ? "Trade Binder" : "Collector Vault"}</span>{binder.is_featured ? <Star className="h-4 w-4 fill-amber-300 text-amber-300" /> : null}</div><div><p className="text-xl font-semibold leading-tight text-white">{binder.title}</p><p className="mt-2 text-[9px] uppercase tracking-[0.14em] text-white/45">{binder.cardCount} cards · {profile.show_collection_value && binder.show_values ? money(binder.value) : "Value private"}</p></div></div></div><div className="mt-3 flex items-start justify-between"><div><p className="text-sm font-semibold text-white">{binder.title}</p><p className="mt-1 text-[10px] text-slate-600">{binder.description || "Open the collection"}</p></div>{binder.is_trade_binder ? <MessageCircle className="h-4 w-4 text-emerald-300" /> : null}</div></Link>)}</div> : <div className="mt-6 rounded-[26px] border border-dashed border-white/[0.10] p-12 text-center text-slate-600">No public binders yet.</div>}
        </section>
      </div>
    </main>
  );
}

function Stat({ icon: Icon, label, value }: { icon: typeof Layers3; label: string; value: string }) { return <div className="min-w-[108px] rounded-2xl border border-white/[0.08] bg-black/20 p-3"><Icon className="h-4 w-4 text-cyan-300" /><p className="mt-3 text-[8px] font-bold uppercase tracking-[0.14em] text-slate-600">{label}</p><p className="mt-1 text-sm font-semibold text-white">{value}</p></div>; }
function money(value: number) { return value.toLocaleString("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }); }

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import {
  BookOpen,
  CircleDollarSign,
  Layers3,
  LockKeyhole,
  Repeat2,
  ShieldCheck,
  UserPlus,
} from "lucide-react";

import {
  buildAccountReturnPath,
  isValidShareToken,
  sanitizeLegacyBinderPayload,
  safeText,
  shareHasExpired,
} from "@/lib/public-share-security";
import { createAdminClient } from "@/lib/supabase/admin";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  robots: {
    index: false,
    follow: false,
    nocache: true,
  },
  referrer: "no-referrer",
};

export default async function SharedBinderPage({
  params,
}: {
  params: Promise<{ token: string }>;
}) {
  const { token } = await params;
  if (!isValidShareToken(token)) notFound();

  const admin = createAdminClient();
  const { data } = await admin
    .from("binder_shares")
    .select(
      "id,title,mode,payload,created_at,expires_at,is_active,revoked_at,view_count,allow_interested_lists,require_account_for_actions",
    )
    .eq("token", token)
    .maybeSingle();

  if (
    !data ||
    data.is_active !== true ||
    data.revoked_at ||
    shareHasExpired(data.expires_at)
  ) {
    notFound();
  }

  const payload = sanitizeLegacyBinderPayload(data.payload);
  const cards = payload.cards;
  const isTrade = data.mode === "trade";
  const title = safeText(data.title, 120) || "Shared Binder";
  const sharePath = `/share/binder/${token}`;

  // Best-effort view count. No private data is returned to the visitor.
  await admin
    .from("binder_shares")
    .update({ view_count: Number(data.view_count ?? 0) + 1 })
    .eq("id", data.id)
    .eq("is_active", true);

  const signupUrl = buildAccountReturnPath(
    sharePath,
    isTrade ? "trade-binder" : "collection-showcase",
  );

  return (
    <main className="min-h-screen bg-[radial-gradient(circle_at_top_right,rgba(139,92,246,.16),transparent_32%),radial-gradient(circle_at_top_left,rgba(34,211,238,.10),transparent_32%),#020911] px-4 py-8 text-white sm:px-8">
      <div className="mx-auto max-w-[1420px]">
        <div className="mb-4 flex items-center justify-between rounded-2xl border border-emerald-300/[0.12] bg-emerald-300/[0.035] px-4 py-3">
          <span className="inline-flex items-center gap-2 text-[10px] font-semibold text-emerald-200">
            <ShieldCheck className="h-4 w-4" />
            Safe read-only share
          </span>
          <span className="hidden items-center gap-2 text-[9px] text-slate-600 sm:inline-flex">
            <LockKeyhole className="h-3.5 w-3.5" />
            No dashboard or inventory access
          </span>
        </div>

        <header className="overflow-hidden rounded-[30px] border border-violet-300/[0.16] bg-[linear-gradient(135deg,#0b1d2b,#071522_55%,#140b23)] p-6 shadow-[0_36px_130px_rgba(0,0,0,.46)] sm:p-9">
          <div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between">
            <div>
              <span className="inline-flex items-center gap-2 rounded-full border border-cyan-300/[0.16] bg-cyan-300/[0.055] px-3 py-2 text-[10px] font-semibold text-cyan-100">
                <BookOpen className="h-4 w-4" />
                Trading Docks Collector Vault
              </span>
              <h1 className="mt-5 text-4xl font-semibold tracking-[-0.055em] sm:text-6xl">
                {title}
              </h1>
              <p className="mt-3 text-sm font-semibold uppercase tracking-[0.16em] text-violet-200">
                {isTrade ? "Public trade binder" : "Collection showcase"}
              </p>
            </div>
            <div className="grid grid-cols-3 gap-2">
              <Stat
                icon={Layers3}
                label="Cards"
                value={String(payload.totalCards || cards.length)}
              />
              <Stat
                icon={CircleDollarSign}
                label="Value"
                value={`$${payload.totalValue.toLocaleString("en-US", {
                  maximumFractionDigits: 0,
                })}`}
              />
              <Stat
                icon={Repeat2}
                label="Pockets"
                value={String(payload.occupied || cards.length)}
              />
            </div>
          </div>
        </header>

        <section className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-5">
          {cards.map((card, index) => (
            <article
              key={`${card.name}-${card.page}-${card.slot}-${index}`}
              className="group overflow-hidden rounded-[22px] border border-white/[0.085] bg-[#07131d] p-2 shadow-[0_18px_48px_rgba(0,0,0,.30)] transition duration-300 hover:-translate-y-1 hover:border-violet-300/30"
            >
              <div className="relative aspect-[.716] overflow-hidden rounded-[16px] bg-black/25">
                {card.imageUrl ? (
                  <img
                    src={card.imageUrl}
                    alt={card.name}
                    className="h-full w-full object-cover transition duration-500 group-hover:scale-105"
                  />
                ) : (
                  <div className="flex h-full items-center justify-center text-slate-700">
                    <BookOpen className="h-9 w-9" />
                  </div>
                )}
                {card.page || card.slot ? (
                  <span className="absolute left-3 top-3 rounded-lg border border-white/[0.12] bg-black/75 px-2 py-1 text-[9px] font-bold text-cyan-200 backdrop-blur">
                    P{card.page ?? "-"} / {card.slot ?? "-"}
                  </span>
                ) : null}
              </div>
              <div className="p-3">
                <h2 className="truncate text-sm font-semibold text-slate-100">
                  {card.name}
                </h2>
                <p className="mt-1 truncate text-[10px] text-slate-600">
                  {[card.set, card.condition, card.finish]
                    .filter(Boolean)
                    .join(" / ") || "Collector card"}
                </p>
                <div className="mt-3 flex items-center justify-between">
                  <span className="text-[10px] font-semibold text-emerald-300">
                    {card.value === null ? "Value hidden" : `$${card.value.toFixed(2)}`}
                  </span>
                  <span className="text-[9px] text-slate-600">
                    Qty {card.quantity}
                  </span>
                </div>
              </div>
            </article>
          ))}
        </section>

        <section className="mt-8 overflow-hidden rounded-[26px] border border-cyan-300/[0.13] bg-[linear-gradient(135deg,rgba(34,211,238,.06),rgba(139,92,246,.07))] p-5 sm:p-7">
          <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <p className="text-[9px] font-bold uppercase tracking-[0.18em] text-cyan-300">
                {isTrade ? "Interested in these cards?" : "Like this collection?"}
              </p>
              <h2 className="mt-2 text-2xl font-semibold text-white">
                {isTrade
                  ? "Create a free account to send an Interested List."
                  : "Build and share your own binder free."}
              </h2>
              <p className="mt-2 max-w-2xl text-[11px] leading-6 text-slate-500">
                Browsing this link does not provide access to the collector's
                dashboard, inventory, account, or other private binders.
              </p>
            </div>
            <div className="flex flex-wrap gap-2">
              <Link
                href={signupUrl}
                className="inline-flex h-11 items-center gap-2 rounded-xl bg-cyan-300 px-4 text-[10px] font-bold text-[#031319]"
              >
                <UserPlus className="h-4 w-4" />
                Create Free Account
              </Link>
              <Link
                href={`/sign-in?next=${encodeURIComponent(sharePath)}`}
                className="inline-flex h-11 items-center gap-2 rounded-xl border border-white/[0.10] bg-black/15 px-4 text-[10px] font-semibold text-white"
              >
                Sign In
              </Link>
            </div>
          </div>
        </section>

        <footer className="mt-6 flex flex-col gap-3 rounded-2xl border border-white/[0.07] bg-white/[0.025] px-5 py-4 text-[11px] text-slate-500 sm:flex-row sm:items-center sm:justify-between">
          <span>Organized and shared with Trading Docks.</span>
          <span>
            {isTrade
              ? "An account is required before any trade interaction."
              : "This page is a read-only collection snapshot."}
          </span>
        </footer>
      </div>
    </main>
  );
}

function Stat({
  icon: Icon,
  label,
  value,
}: {
  icon: typeof Layers3;
  label: string;
  value: string;
}) {
  return (
    <div className="min-w-[108px] rounded-2xl border border-white/[0.08] bg-black/20 p-3">
      <Icon className="h-4 w-4 text-cyan-300" />
      <p className="mt-3 text-[8px] font-bold uppercase tracking-[0.14em] text-slate-600">
        {label}
      </p>
      <p className="mt-1 text-sm font-semibold text-white">{value}</p>
    </div>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { BookOpen, Layers3, Share2 } from "lucide-react";
import {
  buildAccountReturnPath,
  isValidShareToken,
  shareHasExpired,
} from "@/lib/public-share-security";
import { createAdminClient } from "@/lib/supabase/admin";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  robots: { index: false, follow: false, nocache: true },
  referrer: "no-referrer",
};

export default async function PortfolioSharePage({ params }: { params: Promise<{ token: string }> }) {
  const { token } = await params;
  if (!isValidShareToken(token)) notFound();
  const admin = createAdminClient();
  const { data: share } = await admin.from("portfolio_shares")
    .select("id,share_type,payload,expires_at,view_count,is_active,revoked_at,visibility")
    .eq("token", token)
    .maybeSingle();
  if (
    !share ||
    share.is_active !== true ||
