        <div className="td-entrance__copy">
          <p>TRADING DOCKS</p>
          <span>Workspace ready</span>
        </div>

        <div aria-hidden="true" className="td-entrance__signal">
          <span />
        </div>
      </div>

      <style jsx>{`
        .td-entrance {
          position: fixed;
          inset: 0;
          z-index: 9999;
          display: grid;
          place-items: center;
          overflow: hidden;
          background:
            radial-gradient(circle at 50% 46%, rgba(16, 185, 210, 0.1), transparent 29rem),
            rgba(2, 9, 14, 0.985);
          opacity: 1;
          transition:
            opacity 360ms cubic-bezier(0.22, 1, 0.36, 1),
            backdrop-filter 360ms cubic-bezier(0.22, 1, 0.36, 1);
        }

        .td-entrance--leaving {
          opacity: 0;
          pointer-events: none;
          backdrop-filter: blur(0);
        }

        .td-entrance__aurora {
          position: absolute;
          width: min(70vw, 48rem);
          aspect-ratio: 1.8;
          border-radius: 50%;
          background: rgba(28, 211, 239, 0.08);
          filter: blur(90px);
          opacity: 0;
          animation: td-aurora 900ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
        }

        .td-entrance__content {
          position: relative;
          display: flex;
          width: 15rem;
          flex-direction: column;
          align-items: center;
        }

        .td-entrance__cards {
          position: relative;
          width: 5.7rem;
          height: 6.5rem;
          perspective: 700px;
        }

        .td-entrance__card {
          position: absolute;
          left: 50%;
          top: 50%;
          display: grid;
          width: 3.75rem;
          height: 5.25rem;
          place-items: center;
          border: 1px solid rgba(103, 232, 249, 0.2);
          border-radius: 0.72rem;
          background: linear-gradient(145deg, rgba(13, 32, 42, 0.95), rgba(4, 13, 20, 0.98));
