"use client";

import { useEffect, useMemo, useState } from "react";
import {
  CalendarDays,
  ChevronLeft,
  ChevronRight,
  Clock3,
  CreditCard,
  PackageCheck,
  Plus,
  Repeat2,
  Truck,
  Users,
  X,
} from "lucide-react";

import { PageHeader } from "../common/PageHeader";
import { WorkspaceFrame } from "../common/WorkspaceFrame";
import styles from "../styles.module.css";

type EventType = "order" | "delivery" | "event" | "shift" | "payroll";

type CalendarEvent = {
  id: string;
  title: string;
  date: string;
  startTime: string;
  endTime?: string;
  type: EventType;
  assignee?: string;
  notes?: string;
  recurring?: boolean;
};

const STORAGE_KEY = "trading-docks-business-calendar-v2";

const TYPE_CONFIG = {
  order: { label: "Supply order", icon: PackageCheck, className: "border-cyan-300/15 bg-cyan-400/[0.055] text-cyan-200" },
  delivery: { label: "Delivery", icon: Truck, className: "border-blue-300/15 bg-blue-400/[0.055] text-blue-200" },
  event: { label: "Event", icon: CalendarDays, className: "border-violet-300/15 bg-violet-400/[0.055] text-violet-200" },
  shift: { label: "Employee shift", icon: Users, className: "border-emerald-300/15 bg-emerald-400/[0.055] text-emerald-200" },
  payroll: { label: "Payroll", icon: CreditCard, className: "border-amber-300/15 bg-amber-400/[0.055] text-amber-200" },
} satisfies Record<EventType, { label: string; icon: typeof CalendarDays; className: string }>;

const SEED_EVENTS: CalendarEvent[] = [
  { id: "1", title: "Reorder bubble mailers", date: "2026-07-03", startTime: "09:00", type: "order", recurring: true },
  { id: "2", title: "USPS supplies delivery", date: "2026-07-07", startTime: "13:30", type: "delivery" },
  { id: "3", title: "Friday Night Magic", date: "2026-07-10", startTime: "18:00", endTime: "22:00", type: "event", assignee: "Tournament team" },
  { id: "4", title: "Alex fulfillment shift", date: "2026-07-14", startTime: "08:00", endTime: "16:00", type: "shift", assignee: "Alex" },
  { id: "5", title: "Payroll approval", date: "2026-07-17", startTime: "10:00", type: "payroll", assignee: "Jeremy" },
];

export function CalendarWorkspace() {
  const [viewDate, setViewDate] = useState(new Date(2026, 6, 1));
  const [events, setEvents] = useState<CalendarEvent[]>(SEED_EVENTS);
  const [selectedDate, setSelectedDate] = useState("2026-07-01");
  const [modalOpen, setModalOpen] = useState(false);
  const [filter, setFilter] = useState<EventType | "all">("all");

  useEffect(() => {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (!stored) return;
    try {
      setEvents(JSON.parse(stored));
    } catch {
      window.localStorage.removeItem(STORAGE_KEY);
    }
  }, []);

  useEffect(() => {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  }, [events]);

  const monthGrid = useMemo(() => buildMonthGrid(viewDate), [viewDate]);
  const visibleEvents = events.filter((event) => filter === "all" || event.type === filter);
  const selectedEvents = visibleEvents.filter((event) => event.date === selectedDate);

  return (
    <WorkspaceFrame>
      <PageHeader
        eyebrow="Business operations calendar"
        title="Schedule the work that keeps your business moving."
        description="Plan supply reorders, deliveries, events, employee shifts, time-card reviews, and payroll deadlines."
        icon={CalendarDays}
        actionLabel="Schedule activity"
        onAction={() => setModalOpen(true)}
      />

      <div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_0.65fr]">
        <section className={`${styles.glassPanel} rounded-[26px] p-5`}>
          <div className="flex items-center justify-between gap-4">
            <button type="button" onClick={() => setViewDate((current) => new Date(current.getFullYear(), current.getMonth() - 1, 1))} className="calendar-nav">
              <ChevronLeft className="h-4 w-4" />
            </button>

            <div className="text-center">
              <p className="text-lg font-semibold text-white">
                {viewDate.toLocaleString("en-US", { month: "long", year: "numeric" })}
              </p>
              <p className="mt-1 text-[9px] text-slate-600">Click a date to review or add activities</p>
            </div>

            <button type="button" onClick={() => setViewDate((current) => new Date(current.getFullYear(), current.getMonth() + 1, 1))} className="calendar-nav">
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>

          <div className="mt-5 flex flex-wrap gap-2">
            <FilterButton active={filter === "all"} onClick={() => setFilter("all")}>All</FilterButton>
            {(Object.keys(TYPE_CONFIG) as EventType[]).map((type) => (
              <FilterButton key={type} active={filter === type} onClick={() => setFilter(type)}>
                {TYPE_CONFIG[type].label}
              </FilterButton>
            ))}
          </div>

          <div className="mt-4 grid grid-cols-7 gap-2">
            {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => (
              <div key={day} className="py-2 text-center text-[8px] font-semibold uppercase tracking-[0.12em] text-slate-700">
                {day}
              </div>
            ))}

            {monthGrid.map((day) => {
              const key = toDateKey(day.date);
              const dayEvents = visibleEvents.filter((event) => event.date === key);
              const selected = key === selectedDate;

              return (
                <button
                  key={key}
                  type="button"
                  onClick={() => setSelectedDate(key)}
                  className={[
                    "min-h-[108px] rounded-xl border p-2 text-left transition",
                    day.inCurrentMonth
                      ? "border-white/[0.055] bg-black/[0.08] hover:border-cyan-300/[0.14] hover:bg-cyan-400/[0.025]"
                      : "border-transparent bg-black/[0.025] opacity-30",
                    selected ? "border-cyan-300/[0.2] bg-cyan-400/[0.05]" : "",
                  ].join(" ")}
                >
                  <span className="text-[9px] font-semibold text-slate-600">{day.date.getDate()}</span>
                  <span className="mt-1.5 block space-y-1">
                    {dayEvents.slice(0, 3).map((event) => (
