      <button
        type="button"
        onClick={onClose}
        className="mt-5 h-10 w-full rounded-xl bg-gradient-to-b from-cyan-300 via-cyan-400 to-sky-500 text-[9px] font-semibold text-[#001018]"
      >
        Apply buying rules
