function capitalize(value: string) {
  return value.charAt(0).toUpperCase() + value.slice(1);
}

function currency(value: number) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 2,
  }).format(Number.isFinite(value) ? value : 0);
}

function exportCsv(
  cards: AppraisalCard[],
  settings: BuyingSettings,
  customerName: string,
  cashOffer: number,
) {
  const header = [
    "Card",
    "Set",
    "Collector Number",
    "Quantity",
    "Finish",
    "Condition",
    "Unit Market",
    "Adjusted Market",
    "Suggested Percent",
    "Final Offer",
  ];

  const rows = cards.map((item) => {
    const economics =
      item.status === "ready"
        ? estimateCardEconomics(item, settings)
        : null;

    return [
      item.card?.name ?? item.name,
      item.card?.set.toUpperCase() ?? item.setCode ?? "",
      item.card?.collector_number ?? item.collectorNumber ?? "",
      item.quantity,
      item.finish,
      item.condition,
      item.unitMarket.toFixed(2),
      item.lineMarketValue.toFixed(2),
      item.suggestedPercent.toFixed(2),
      economics?.offer.toFixed(2) ?? "0.00",
    ];
  });

  rows.push([
    "TOTAL OFFER",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    cashOffer.toFixed(2),
  ]);

  const csv = [header, ...rows]
    .map((row) =>
      row
        .map((value) => `"${String(value).replaceAll('"', '""')}"`)
        .join(","),
    )
    .join("\\n");

  downloadFile(
    csv,
    `${slug(customerName || "walk-in")}-collection-appraisal.csv`,
    "text/csv;charset=utf-8",
  );
}

function exportJson(payload: unknown) {
  downloadFile(
    JSON.stringify(payload, null, 2),
    "collection-appraisal.json",
    "application/json",
  );
}

function downloadFile(
  contents: string,
  filename: string,
  type: string,
) {
  const blob = new Blob([contents], { type });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
}

function slug(value: string) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

function emptyTotalsShape() {
  return {
    market: 0,
    cashOffer: 0,
    storeCreditOffer: 0,
    fees: 0,
    shipping: 0,
    labor: 0,
    projectedNet: 0,
    projectedProfit: 0,
    averageOfferPercent: 0,
    projectedMargin: 0,
    units: 0,
  };
}

