function edhrecCardUrl(cardName: string) {
  const slug = cardName
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/['’]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

  return `https://edhrec.com/cards/${slug}`;
}

function InspectorAction({
  children,
  tone,
  href,
  onClick,
}: {
  children: ReactNode;
