}) {
  return (
    <div className="flex items-start justify-between gap-4">
      <div>
        <p
          className={[
            "text-[8px] font-semibold uppercase tracking-[0.17em]",
            warning ? "text-amber-300" : "text-cyan-300",
          ].join(" ")}
        >
          {eyebrow}
