          return (
            <Link
              key={item.href}
              href={item.href}
              onClick={onNavigate}
              title={collapsed ? item.label : undefined}
              className={[
                "group relative flex h-10 items-center overflow-hidden rounded-xl border transition duration-300",
                collapsed ? "justify-center px-0" : "gap-3 px-3",
                active
