"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import {
  Bug,
  CheckCircle2,
  FileText,
  Lightbulb,
  Loader2,
  MessageSquareText,
  Paperclip,
  Search,
} from "lucide-react";

import { createClient } from "@/lib/supabase/client";

type Item = {
  id: string;
  user_id: string;
  email: string;
  full_name: string | null;
  submission_type: "feedback" | "bug" | "feature";
  title: string;
  description: string;
  page_url: string | null;
  severity: string | null;
  status: string;
  priority: string;
  admin_notes: string | null;
  admin_response: string | null;
  created_at: string;
  updated_at: string;
  attachment_count: number;
};
type Attachment = { id: string; file_name: string; storage_path: string; mime_type: string | null };

const STATUS_OPTIONS = ["new", "reviewing", "planned", "in_progress", "resolved", "closed"];
const PRIORITY_OPTIONS = ["low", "normal", "high", "urgent"];

export function AdminFeedbackQueue() {
  const supabase = useMemo(() => createClient(), []);
  const [items, setItems] = useState<Item[]>([]);
  const [selectedId, setSelectedId] = useState("");
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState("open");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState("");

  const load = useCallback(async () => {
    const { data } = await supabase.rpc("admin_feedback_queue");
    const next = (data ?? []) as Item[];
    setItems(next);
    setSelectedId((current) => current || next[0]?.id || "");
    setLoading(false);
  }, [supabase]);

  useEffect(() => { void load(); }, [load]);

  const selected = items.find((item) => item.id === selectedId) ?? null;
  useEffect(() => {
    if (!selectedId) { setAttachments([]); return; }
    void (async () => {
      const { data } = await supabase
        .from("feedback_attachments")
        .select("id,file_name,storage_path,mime_type")
        .eq("submission_id", selectedId);
      setAttachments((data ?? []) as Attachment[]);
    })();
  }, [selectedId, supabase]);

  const visible = items.filter((item) => {
    const matchesQuery = `${item.title} ${item.description} ${item.email} ${item.full_name ?? ""}`.toLowerCase().includes(query.toLowerCase());
    const matchesFilter = filter === "all" || (filter === "open" ? !["resolved", "closed"].includes(item.status) : item.submission_type === filter || item.status === filter);
    return matchesQuery && matchesFilter;
  });

  const stats = {
    open: items.filter((item) => !["resolved", "closed"].includes(item.status)).length,
    bugs: items.filter((item) => item.submission_type === "bug" && !["resolved", "closed"].includes(item.status)).length,
    features: items.filter((item) => item.submission_type === "feature" && !["resolved", "closed"].includes(item.status)).length,
    resolved: items.filter((item) => item.status === "resolved").length,
  };

  function patchLocal(patch: Partial<Item>) {
    setItems((current) => current.map((item) => item.id === selectedId ? { ...item, ...patch } : item));
  }

  async function save() {
    if (!selected) return;
    setSaving(true);
    const resolvedAt = selected.status === "resolved" ? new Date().toISOString() : null;
    const { error } = await supabase.from("feedback_submissions").update({
      status: selected.status,
      priority: selected.priority,
      admin_notes: selected.admin_notes,
      admin_response: selected.admin_response,
      resolved_at: resolvedAt,
      updated_at: new Date().toISOString(),
    }).eq("id", selected.id);
    setNotice(error ? `Could not save: ${error.message}` : "Submission updated.");
    window.setTimeout(() => setNotice(""), 3000);
    setSaving(false);
  }

  async function openAttachment(attachment: Attachment) {
    const { data } = await supabase.storage.from("feedback-attachments").createSignedUrl(attachment.storage_path, 300);
    if (data?.signedUrl) window.open(data.signedUrl, "_blank", "noopener,noreferrer");
  }

  return (
    <div className="space-y-5">
      <section className="rounded-[24px] border border-white/[0.07] bg-[#06121b] p-5 sm:p-6">
        <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-cyan-300/65">Product intelligence</p>
        <h2 className="mt-1 text-xl font-semibold text-white">Feedback, Bugs & Feature Requests</h2>
        <p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Review every customer submission with its account, attachments, priority, progress, internal notes, and customer-facing response.</p>
      </section>

      <div className="grid grid-cols-2 gap-3 xl:grid-cols-4">
        <Stat label="Open" value={stats.open} icon={MessageSquareText} />
        <Stat label="Active bugs" value={stats.bugs} icon={Bug} />
        <Stat label="Feature ideas" value={stats.features} icon={Lightbulb} />
        <Stat label="Resolved" value={stats.resolved} icon={CheckCircle2} />
      </div>

      <section className="grid min-h-[620px] overflow-hidden rounded-[24px] border border-white/[0.07] bg-[#06121b] lg:grid-cols-[minmax(290px,.75fr)_minmax(0,1.25fr)]">
        <div className="border-b border-white/[0.07] lg:border-b-0 lg:border-r">
          <div className="space-y-3 border-b border-white/[0.06] p-4">
            <label className="flex h-10 items-center gap-2 rounded-xl border border-white/[0.08] bg-black/15 px-3"><Search className="h-3.5 w-3.5 text-slate-600" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search requests or accounts…" className="min-w-0 flex-1 bg-transparent text-xs text-white outline-none" /></label>
            <div className="flex gap-2 overflow-x-auto pb-1">{["open", "bug", "feature", "resolved", "all"].map((value) => <button key={value} type="button" onClick={() => setFilter(value)} className={`shrink-0 rounded-lg border px-2.5 py-1.5 text-[10px] font-semibold capitalize ${filter === value ? "border-cyan-300/20 bg-cyan-300/[0.07] text-cyan-200" : "border-white/[0.07] text-slate-600"}`}>{value}</button>)}</div>
          </div>
          <div className="max-h-[520px] overflow-y-auto p-2">
            {loading ? <Loader2 className="mx-auto my-16 h-5 w-5 animate-spin text-cyan-300" /> : visible.length ? visible.map((item) => <button key={item.id} type="button" onClick={() => setSelectedId(item.id)} className={`mb-1 w-full rounded-xl border p-3 text-left transition ${selectedId === item.id ? "border-cyan-300/18 bg-cyan-300/[0.055]" : "border-transparent hover:bg-white/[0.025]"}`}><div className="flex items-center justify-between gap-2"><span className="text-[9px] font-bold uppercase tracking-[0.15em] text-cyan-300/55">{item.submission_type}</span><span className="text-[9px] capitalize text-slate-700">{item.status.replace("_", " ")}</span></div><p className="mt-1 truncate text-xs font-semibold text-slate-200">{item.title}</p><p className="mt-1 truncate text-[10px] text-slate-600">{item.email}</p></button>) : <p className="py-16 text-center text-xs text-slate-600">No matching submissions</p>}
          </div>
        </div>

        <div className="min-w-0 p-4 sm:p-6">
          {selected ? (
            <div className="space-y-5">
              <div className="flex flex-wrap items-start justify-between gap-4">
                <div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-300/60">{selected.submission_type}{selected.severity ? ` · ${selected.severity} severity` : ""}</p><h3 className="mt-1 text-xl font-semibold text-white">{selected.title}</h3><p className="mt-2 text-xs text-slate-500">{selected.full_name || "Unnamed account"} · {selected.email} · {new Date(selected.created_at).toLocaleString()}</p></div>
                <div className="flex gap-2"><select value={selected.priority} onChange={(event) => patchLocal({ priority: event.target.value })} className="h-10 rounded-xl border border-white/[0.09] bg-[#07141e] px-3 text-xs capitalize text-white">{PRIORITY_OPTIONS.map((value) => <option key={value}>{value}</option>)}</select><select value={selected.status} onChange={(event) => patchLocal({ status: event.target.value })} className="h-10 rounded-xl border border-white/[0.09] bg-[#07141e] px-3 text-xs capitalize text-white">{STATUS_OPTIONS.map((value) => <option key={value} value={value}>{value.replace("_", " ")}</option>)}</select></div>
              </div>

              <div className="rounded-2xl border border-white/[0.07] bg-black/10 p-4"><p className="whitespace-pre-wrap text-sm leading-6 text-slate-300">{selected.description}</p>{selected.page_url ? <p className="mt-4 break-all text-[10px] text-slate-700">Submitted from: {selected.page_url}</p> : null}</div>

              {attachments.length ? <div><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-slate-600">Attachments</p><div className="mt-2 flex flex-wrap gap-2">{attachments.map((attachment) => <button key={attachment.id} type="button" onClick={() => openAttachment(attachment)} className="flex items-center gap-2 rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-2 text-xs text-slate-300 hover:border-cyan-300/20"><Paperclip className="h-3.5 w-3.5 text-cyan-300/60" /><span className="max-w-56 truncate">{attachment.file_name}</span></button>)}</div></div> : null}

              <div className="grid gap-4 xl:grid-cols-2">
                <label className="grid gap-2"><span className="text-[10px] font-bold uppercase tracking-[0.16em] text-slate-600">Private admin notes</span><textarea rows={6} value={selected.admin_notes ?? ""} onChange={(event) => patchLocal({ admin_notes: event.target.value })} placeholder="Internal investigation, owner, reproduction steps…" className="rounded-xl border border-white/[0.09] bg-black/15 p-3 text-xs leading-5 text-white outline-none focus:border-cyan-300/30" /></label>
                <label className="grid gap-2"><span className="text-[10px] font-bold uppercase tracking-[0.16em] text-slate-600">Response visible to customer</span><textarea rows={6} value={selected.admin_response ?? ""} onChange={(event) => patchLocal({ admin_response: event.target.value })} placeholder="Thank them, share the outcome, or ask for more detail…" className="rounded-xl border border-white/[0.09] bg-black/15 p-3 text-xs leading-5 text-white outline-none focus:border-cyan-300/30" /></label>
              </div>
              <button type="button" disabled={saving} onClick={save} className="flex h-11 items-center justify-center gap-2 rounded-xl bg-cyan-300 px-5 text-xs font-bold text-[#03202a] disabled:opacity-55">{saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <FileText className="h-4 w-4" />} Save review</button>
            </div>
          ) : <div className="flex min-h-[480px] items-center justify-center text-center"><div><MessageSquareText className="mx-auto h-6 w-6 text-slate-700" /><p className="mt-3 text-sm text-slate-500">Select a submission to review</p></div></div>}
        </div>
      </section>
      {notice ? <div role="status" className="fixed bottom-5 right-5 z-[160] rounded-xl border border-cyan-300/15 bg-[#0a1a24] px-4 py-3 text-xs text-cyan-100 shadow-2xl">{notice}</div> : null}
    </div>
  );
}

function Stat({ label, value, icon: Icon }: { label: string; value: number; icon: typeof Bug }) {
  return <div className="rounded-[20px] border border-white/[0.07] bg-[#06121b] p-4"><div className="flex items-center justify-between"><p className="text-[9px] font-bold uppercase tracking-[0.16em] text-slate-600">{label}</p><Icon className="h-4 w-4 text-cyan-300/50" /></div><p className="mt-3 text-xl font-semibold text-white">{value}</p></div>;
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { AlertTriangle, CheckCircle2, Database, FileUp, Loader2, UploadCloud } from "lucide-react";

type CatalogStatus = {
  totalRecords: number;
  uniqueProducts: number;
  sets: number;
  lastImport: {
    status?: string;
    total_rows?: number;
    processed_rows?: number;
    inserted_rows?: number;
    updated_rows?: number;
    rejected_rows?: number;
    filename?: string | null;
    completed_at?: string | null;
    started_at?: string | null;
    error_summary?: unknown;
  } | null;
  defaultStorageImport?: {
    bucket: string;
    prefix: string;
    paths: string[];
  };
};

type ImportSummary = {
  totalRows: number;
  processedRows: number;
  insertedRows: number;
  updatedRows: number;
  rejectedRows: number;
  errors: Array<{ row: number; error: string }>;
};

type StorageImportPart = {
  path: string;
  status: "pending" | "processing" | "completed" | "failed";
  byteOffset?: number;
  totalBytes?: number | null;
  totalRows: number;
  processedRows: number;
  insertedRows: number;
  updatedRows: number;
  rejectedRows: number;
  error?: string;
};

type StorageVerificationPart = {
  path: string;
  exists: boolean;
  size: number | null;
  contentType: string | null;
  error?: string;
};

type ImportResponse = {
  ok?: boolean;
  action?: "validate" | "import" | "storage-list" | "storage-verify" | "storage-start" | "storage-advance" | "storage-import";
  summary?: ImportSummary;
  result?: {
    status: "processing" | "completed" | "failed";
    skippedCompletedImport: boolean;
    parts: StorageImportPart[];
    summary: ImportSummary;
    currentPartIndex: number;
    currentPartPath: string | null;
    batch: {
      attempted: boolean;
      completedRows: number;
      completedBytes: number;
      partCompleted: boolean;
      importCompleted: boolean;
    };
  };
  paths?: string[];
  parts?: StorageVerificationPart[];
  allVerified?: boolean;
  error?: string;
  message?: string;
  code?: string;
  details?: string;
  hint?: string;
  stage?: string;
  part?: string;
  byteOffset?: number;
};

export function TcgplayerCatalogManager() {
  const [status, setStatus] = useState<CatalogStatus | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [working, setWorking] = useState<"validate" | "import" | "storage-list" | "storage-verify" | "storage-start" | "storage-advance" | "storage-import" | null>(null);
  const [result, setResult] = useState<ImportResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [storageBucket, setStorageBucket] = useState("catalog-imports");
  const [storagePrefix, setStoragePrefix] = useState("");
  const [storagePaths, setStoragePaths] = useState([
    "part-001.csv",
    "part-002.csv",
    "part-003.csv",
  ]);
  const [storageVerified, setStorageVerified] = useState(false);
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    void refreshStatus();
  }, []);

  const progress = useMemo(() => {
    const summary = result?.summary;
    if (!summary?.totalRows) return 0;
    const denominator = result?.result ? 799149 : summary.totalRows;
    return Math.min(100, Math.round(((summary.processedRows + summary.rejectedRows) / denominator) * 1000) / 10);
  }, [result]);

  const activeStorageImport = result?.result?.status === "processing" || result?.result?.status === "failed";
  const currentPart = result?.result?.currentPartPath?.split("/").pop() ?? null;
  const currentPartPosition = result?.result ? Math.max(0, result.result.currentPartIndex) + 1 : 0;
  const displayedStatus = useMemo(() => {
    if (working) return working === "storage-verify" ? "Verifying" : "Active";
    if (result?.result?.status) return result.result.status === "completed" ? "Complete" : titleCase(result.result.status);
    if (result?.action === "storage-verify") return result.allVerified ? "Ready" : "Failed";
    const last = status?.lastImport;
    if (last?.status === "completed" && Number(last.total_rows ?? 0) === 0) return "Stale zero-row job";
    return last?.status ? titleCase(last.status) : "Idle";
  }, [result, status?.lastImport, working]);

  async function refreshStatus() {
    const response = await fetch("/api/admin/tcgplayer-catalog");
    const payload = await response.json() as CatalogStatus & { error?: string };
    if (!response.ok) {
      setError(payload.error ?? "Could not load catalog status.");
      return;
    }
    setStatus(payload);
    if (payload.defaultStorageImport) {
      setStorageBucket(payload.defaultStorageImport.bucket);
      setStoragePrefix(payload.defaultStorageImport.prefix);
      setStoragePaths(payload.defaultStorageImport.paths);
      setStorageVerified(false);
    }
    const lastImport = payload.lastImport;
    if (
      !result &&
      lastImport?.status === "processing" &&
      lastImport.error_summary &&
      typeof lastImport.error_summary === "object" &&
      "kind" in lastImport.error_summary &&
      (lastImport.error_summary as { kind?: unknown }).kind === "tcgplayer-storage-multipart"
    ) {
      const metadata = lastImport.error_summary as {
        parts?: StorageImportPart[];
      };
      const parts = metadata.parts ?? [];
      const currentPartIndex = parts.findIndex((part) => part.status !== "completed");
      setResult({
        ok: true,
        action: "storage-start",
        summary: {
          totalRows: Number(lastImport.total_rows ?? 0),
          processedRows: Number(lastImport.processed_rows ?? 0),
          insertedRows: Number(lastImport.inserted_rows ?? 0),
          updatedRows: Number(lastImport.updated_rows ?? 0),
          rejectedRows: Number(lastImport.rejected_rows ?? 0),
          errors: [],
        },
        result: {
          status: "processing",
          skippedCompletedImport: false,
          parts,
          summary: {
            totalRows: Number(lastImport.total_rows ?? 0),
            processedRows: Number(lastImport.processed_rows ?? 0),
            insertedRows: Number(lastImport.inserted_rows ?? 0),
            updatedRows: Number(lastImport.updated_rows ?? 0),
            rejectedRows: Number(lastImport.rejected_rows ?? 0),
            errors: [],
          },
          currentPartIndex,
          currentPartPath: currentPartIndex >= 0 ? parts[currentPartIndex]?.path ?? null : null,
          batch: {
            attempted: false,
            completedRows: 0,
            completedBytes: 0,
            partCompleted: false,
            importCompleted: false,
          },
        },
      });
    }
  }

  async function run(action: "validate" | "import") {
    if (!file) {
      setError("Choose the TCGplayer Magic CSV first.");
      return;
    }

    setWorking(action);
    setError(null);
    setResult(null);
    const form = new FormData();
    form.set("action", action);
    form.set("file", file);

    try {
      const response = await fetch("/api/admin/tcgplayer-catalog", {
        method: "POST",
        body: form,
      });
      const payload = await response.json() as ImportResponse;
      setResult(payload);
      if (!response.ok) setError(importErrorMessage(payload, "TCGplayer catalog import failed."));
      else await refreshStatus();
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : "TCGplayer catalog import failed.");
    } finally {
      setWorking(null);
    }
  }

  async function runStorage(action: "storage-list" | "storage-verify" | "storage-start" | "storage-advance" | "storage-import") {
    setWorking(action);
    setError(null);
    if (action === "storage-list" || action === "storage-start") setResult(null);

    try {
      const response = await fetch("/api/admin/tcgplayer-catalog", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          action,
          bucket: storageBucket,
          prefix: storagePrefix,
          paths: storagePaths,
        }),
      });
      const payload = await response.json() as ImportResponse;
      setResult(payload);
      if (payload.paths) setStoragePaths(payload.paths);
      if (action === "storage-verify") setStorageVerified(response.ok && Boolean(payload.allVerified));
      if (!response.ok) setError(importErrorMessage(payload, "TCGplayer storage catalog import failed."));
      else if (action === "storage-verify" && !payload.allVerified) setError("One or more TCGplayer catalog storage objects could not be verified.");
      else if (action === "storage-verify") return;
      else await refreshStatus();
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : "TCGplayer storage catalog import failed.");
    } finally {
      setWorking(null);
    }
  }

  useEffect(() => {
    if (paused || working !== null || !result?.result || result.result.status !== "processing") return;
    if (result.result.batch.importCompleted) return;
    const timer = window.setTimeout(() => void runStorage("storage-advance"), 350);
    return () => window.clearTimeout(timer);
  }, [paused, result, working]);

  return (
    <main className="min-h-screen bg-[#02070d] px-4 py-6 text-slate-100 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-6xl">
        <div className="rounded-[28px] border border-white/[0.08] bg-[linear-gradient(145deg,rgba(8,22,33,.96),rgba(3,9,15,.98))] p-5 shadow-[0_24px_90px_rgba(0,0,0,.28)] sm:p-7">
          <div className="flex flex-col gap-5 lg:flex-row lg:items-start lg:justify-between">
            <div>
              <div className="inline-flex items-center gap-2 rounded-full border border-cyan-300/[0.14] bg-cyan-400/[0.05] px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-200">
                <Database className="h-3.5 w-3.5" />
                Catalog Management
              </div>
              <h1 className="mt-4 text-3xl font-semibold tracking-[-0.05em] text-white sm:text-4xl">
                TCGplayer Magic Catalog
              </h1>
              <p className="mt-3 max-w-2xl text-sm leading-6 text-slate-400">
                Canonical condition and finish-specific TCGplayer reference rows for matching, pricing, exports, scanner workflows, and seller operations. These records are not user inventory.
              </p>
            </div>

            <a
              href="/dashboard/admin"
              className="inline-flex h-10 items-center justify-center rounded-xl border border-white/[0.08] bg-white/[0.025] px-4 text-xs font-semibold text-slate-300 transition hover:border-cyan-300/[0.16] hover:text-white"
            >
              Back to Command Center
            </a>
          </div>

          <div className="mt-7 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            <Metric label="Total catalog records" value={formatNumber(status?.totalRecords ?? 0)} />
            <Metric label="Unique products" value={formatNumber(status?.uniqueProducts ?? 0)} />
            <Metric label="Sets" value={formatNumber(status?.sets ?? 0)} />
            <Metric label="Last import" value={status?.lastImport?.status ?? "None"} />
          </div>
        </div>

        <section className="mt-5 grid gap-5 lg:grid-cols-[minmax(0,1fr)_380px]">
          <div className="rounded-[24px] border border-white/[0.08] bg-[#06111b] p-5">
            <div className="flex items-center gap-3">
              <span className="flex h-10 w-10 items-center justify-center rounded-2xl border border-cyan-300/[0.12] bg-cyan-400/[0.05] text-cyan-200">
                <FileUp className="h-5 w-5" />
              </span>
              <div>
                <h2 className="text-base font-semibold text-white">Upload canonical CSV</h2>
                <p className="mt-1 text-xs text-slate-500">Validate first, then import/update the catalog by TCGplayer ID.</p>
              </div>
            </div>

            <div className="mt-5 rounded-2xl border border-cyan-300/[0.12] bg-cyan-300/[0.035] p-4">
              <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                <div>
                  <h3 className="text-sm font-semibold text-cyan-50">Supabase Storage import</h3>
                  <p className="mt-1 text-xs leading-5 text-cyan-100/55">
                    Treats the three uploaded CSV parts as one logical catalog import. Files stay in Supabase Storage and are streamed server-side.
                  </p>
                </div>
                <span className="shrink-0 rounded-full border border-cyan-200/15 bg-black/15 px-2.5 py-1 text-[10px] font-bold text-cyan-100">
                  {formatNumber(799149)} expected rows
                </span>
              </div>

              <div className="mt-4 grid gap-3 sm:grid-cols-[180px_minmax(0,1fr)]">
                <label className="block">
                  <span className="text-[10px] font-bold uppercase tracking-[0.16em] text-cyan-100/45">Bucket</span>
                  <input
                    value={storageBucket}
                    onChange={(event) => {
                      setStorageBucket(event.target.value);
                      setStorageVerified(false);
                    }}
                    className="mt-1 h-10 w-full rounded-xl border border-white/[0.08] bg-black/20 px-3 text-xs text-white outline-none focus:border-cyan-300/30"
                  />
                </label>
                <label className="block">
                  <span className="text-[10px] font-bold uppercase tracking-[0.16em] text-cyan-100/45">Folder prefix</span>
                  <input
                    value={storagePrefix}
                    onChange={(event) => {
                      setStoragePrefix(event.target.value);
                      setStorageVerified(false);
                    }}
                    className="mt-1 h-10 w-full rounded-xl border border-white/[0.08] bg-black/20 px-3 text-xs text-white outline-none focus:border-cyan-300/30"
                  />
                </label>
              </div>

              <label className="mt-3 block">
                <span className="text-[10px] font-bold uppercase tracking-[0.16em] text-cyan-100/45">CSV objects, processed in order</span>
                <textarea
                  value={storagePaths.join("\n")}
                  onChange={(event) => {
                    setStoragePaths(event.target.value.split(/\r?\n/).map((path) => path.trim()).filter(Boolean));
                    setStorageVerified(false);
                  }}
                  rows={4}
                  className="mt-1 w-full rounded-xl border border-white/[0.08] bg-black/20 px-3 py-2 text-xs leading-5 text-white outline-none focus:border-cyan-300/30"
                />
              </label>

              <div className="mt-4 flex flex-col gap-3 sm:flex-row">
                <button
                  type="button"
                  disabled={working !== null}
                  onClick={() => void runStorage("storage-verify")}
                  className="inline-flex h-10 items-center justify-center gap-2 rounded-xl border border-cyan-300/[0.16] bg-black/15 px-4 text-xs font-semibold text-cyan-100 transition hover:bg-cyan-400/[0.06] disabled:cursor-not-allowed disabled:opacity-45"
                >
                  {working === "storage-verify" ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}
                  Verify storage parts
                </button>
                <button
                  type="button"
                  disabled={working !== null || !storageVerified}
                  onClick={() => {
                    setPaused(false);
                    void runStorage("storage-start");
                  }}
                  className="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-cyan-300 px-4 text-xs font-bold text-[#001018] transition hover:bg-cyan-200 disabled:cursor-not-allowed disabled:opacity-45"
                >
                  {working === "storage-start" || working === "storage-advance" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Database className="h-4 w-4" />}
                  Import all parts
                </button>
              </div>

              {activeStorageImport ? (
                <div className="mt-4 flex flex-wrap gap-3">
                  <button
                    type="button"
                    onClick={() => setPaused(true)}
                    className="inline-flex h-9 items-center justify-center rounded-xl border border-white/[0.08] bg-black/15 px-4 text-xs font-semibold text-slate-300"
                  >
                    Pause
                  </button>
                  <button
                    type="button"
                    disabled={working !== null}
                    onClick={() => {
                      setPaused(false);
                      void runStorage("storage-advance");
                    }}
                    className="inline-flex h-9 items-center justify-center rounded-xl border border-cyan-300/[0.16] bg-cyan-400/[0.055] px-4 text-xs font-semibold text-cyan-100 disabled:opacity-45"
                  >
                    Resume
                  </button>
                  <button
                    type="button"
                    disabled={working !== null}
                    onClick={() => {
                      setPaused(false);
                      void runStorage("storage-advance");
                    }}
                    className="inline-flex h-9 items-center justify-center rounded-xl border border-amber-300/[0.16] bg-amber-300/[0.055] px-4 text-xs font-semibold text-amber-100 disabled:opacity-45"
                  >
                    Retry failed batch
                  </button>
                </div>
              ) : null}
            </div>

            <label className="mt-5 flex min-h-40 cursor-pointer flex-col items-center justify-center rounded-2xl border border-dashed border-white/[0.12] bg-black/[0.14] p-6 text-center transition hover:border-cyan-300/[0.18] hover:bg-cyan-400/[0.025]">
              <UploadCloud className="h-8 w-8 text-cyan-300/70" />
              <span className="mt-3 text-sm font-semibold text-white">
                {file ? file.name : "Choose TCGplayer Magic CSV"}
              </span>
              <span className="mt-1 text-xs text-slate-500">
                Expected columns must match the TCGplayer pricing export exactly.
              </span>
              <input
                type="file"
                accept=".csv,text/csv"
                className="sr-only"
                onChange={(event) => {
                  setFile(event.target.files?.[0] ?? null);
                  setResult(null);
                  setError(null);
                }}
              />
            </label>

            <div className="mt-5 flex flex-col gap-3 sm:flex-row">
              <button
                type="button"
                disabled={!file || working !== null}
                onClick={() => void run("validate")}
                className="inline-flex h-11 items-center justify-center gap-2 rounded-xl border border-cyan-300/[0.16] bg-cyan-400/[0.055] px-5 text-sm font-semibold text-cyan-100 transition hover:bg-cyan-400/[0.09] disabled:cursor-not-allowed disabled:opacity-45"
              >
                {working === "validate" ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}
                Validate file
              </button>
              <button
                type="button"
                disabled={!file || working !== null}
                onClick={() => void run("import")}
                className="inline-flex h-11 items-center justify-center gap-2 rounded-xl bg-cyan-300 px-5 text-sm font-bold text-[#001018] transition hover:bg-cyan-200 disabled:cursor-not-allowed disabled:opacity-45"
              >
                {working === "import" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Database className="h-4 w-4" />}
                Import/update catalog
              </button>
            </div>

            {error ? (
              <div className="mt-5 rounded-2xl border border-rose-300/[0.18] bg-rose-400/[0.05] p-4 text-sm text-rose-100">
                <div className="flex gap-2"><AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />{error}</div>
              </div>
            ) : null}
          </div>

          <aside className="rounded-[24px] border border-white/[0.08] bg-[#06111b] p-5">
            <h2 className="text-base font-semibold text-white">Import status</h2>
            <p className="mt-1 text-xs leading-5 text-slate-500">
              Full exports refresh existing rows by TCGplayer ID instead of creating duplicates. Missing rows are not deleted automatically.
            </p>

            <div className="mt-5 h-2 overflow-hidden rounded-full bg-white/[0.06]">
              <div
                className="h-full rounded-full bg-cyan-300 transition-all"
                style={{ width: `${progress}%` }}
              />
            </div>

            <div className="mt-5 space-y-2 text-xs">
              <StatusLine label="Processing" value={displayedStatus} />
              <StatusLine label="Total rows" value={formatNumber(result?.summary?.totalRows ?? status?.lastImport?.total_rows ?? 0)} />
              <StatusLine label="Processed" value={formatNumber(result?.summary?.processedRows ?? status?.lastImport?.processed_rows ?? 0)} />
              <StatusLine label="Inserted" value={formatNumber(result?.summary?.insertedRows ?? status?.lastImport?.inserted_rows ?? 0)} />
              <StatusLine label="Updated" value={formatNumber(result?.summary?.updatedRows ?? status?.lastImport?.updated_rows ?? 0)} />
              <StatusLine label="Rejected" value={formatNumber(result?.summary?.rejectedRows ?? status?.lastImport?.rejected_rows ?? 0)} />
            </div>

            {result?.result ? (
              <div className="mt-4 rounded-2xl border border-cyan-300/[0.12] bg-cyan-300/[0.035] p-4">
                <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-cyan-100/55">TCGplayer Magic Catalog</p>
                <p className="mt-2 text-sm font-semibold text-cyan-50">
                  {result.result.status === "completed" ? "Import complete" : `Processing part ${currentPartPosition} of ${result.result.parts.length}`}
                </p>
                <p className="mt-1 text-xs text-cyan-100/60">
                  {formatNumber(result.result.summary.processedRows + result.result.summary.rejectedRows)} / {formatNumber(799149)} rows · {progress}%
                </p>
                <p className="mt-2 text-[11px] text-cyan-100/45">Current file: {currentPart ?? "All parts complete"}</p>
              </div>
            ) : null}

            {result?.parts?.length ? (
              <div className="mt-5 space-y-2">
                <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-slate-500">Verified storage objects</p>
                {result.parts.map((part) => (
                  <div key={part.path} className="rounded-xl border border-white/[0.055] bg-black/[0.1] p-3">
                    <div className="flex items-center justify-between gap-3">
                      <span className="truncate text-[11px] font-semibold text-slate-300">{part.path}</span>
                      <span className={`rounded-full border px-2 py-0.5 text-[9px] font-bold uppercase ${part.exists ? "border-emerald-300/15 text-emerald-200" : "border-rose-300/15 text-rose-200"}`}>{part.exists ? "Exists" : "Missing"}</span>
                    </div>
                    <p className="mt-1 text-[10px] text-slate-600">
                      Size: {part.size == null ? "Unknown" : formatBytes(part.size)} · Type: {part.contentType ?? "Unknown"}
                    </p>
                    {part.error ? <p className="mt-2 text-[10px] leading-4 text-rose-200">{part.error}</p> : null}
                  </div>
                ))}
              </div>
            ) : null}

            {result?.result?.parts?.length ? (
              <div className="mt-5 space-y-2">
                <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-slate-500">Storage parts</p>
                {result.result.parts.map((part) => (
                  <div key={part.path} className="rounded-xl border border-white/[0.055] bg-black/[0.1] p-3">
                    <div className="flex items-center justify-between gap-3">
                      <span className="truncate text-[11px] font-semibold text-slate-300">{part.path.split("/").pop()}</span>
                      <span className="rounded-full border border-white/[0.08] px-2 py-0.5 text-[9px] font-bold uppercase text-slate-400">{part.status}</span>
                    </div>
                    <p className="mt-1 text-[10px] text-slate-600">
                      {formatNumber(part.processedRows)} processed / {formatNumber(part.rejectedRows)} rejected
                    </p>
                    {part.error ? <p className="mt-2 text-[10px] leading-4 text-rose-200">{part.error}</p> : null}
                  </div>
                ))}
              </div>
            ) : null}

            {result?.summary?.errors?.length ? (
              <div className="mt-5 rounded-2xl border border-amber-300/[0.14] bg-amber-300/[0.045] p-3">
                <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-amber-200">Validation errors</p>
                <ul className="mt-3 space-y-2 text-[11px] leading-4 text-amber-100/75">
                  {result.summary.errors.slice(0, 5).map((item) => (
                    <li key={`${item.row}-${item.error}`}>Row {item.row}: {item.error}</li>
                  ))}
                </ul>
              </div>
            ) : null}
          </aside>
        </section>
      </div>
    </main>
  );
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-2xl border border-white/[0.07] bg-white/[0.025] p-4">
      <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-slate-500">{label}</p>
      <p className="mt-2 text-2xl font-semibold tracking-[-0.04em] text-white">{value}</p>
    </div>
  );
}

function StatusLine({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between gap-4 rounded-xl border border-white/[0.055] bg-black/[0.1] px-3 py-2.5">
      <span className="text-slate-500">{label}</span>
      <span className="font-semibold text-slate-200">{value}</span>
    </div>
  );
}

function formatNumber(value: number) {
  return new Intl.NumberFormat("en-US").format(value);
}

function formatBytes(value: number) {
  if (value < 1024) return `${value} B`;
  if (value < 1024 * 1024) return `${Math.round((value / 1024) * 10) / 10} KB`;
  return `${Math.round((value / (1024 * 1024)) * 10) / 10} MB`;
}

function titleCase(value: string) {
  return value.slice(0, 1).toUpperCase() + value.slice(1);
}

function importErrorMessage(payload: ImportResponse, fallback: string) {
  const message = payload.message || payload.error || fallback;
  const context = [
    payload.stage ? `Stage: ${payload.stage}` : "",
    payload.code ? `Code: ${payload.code}` : "",
    payload.part ? `Part: ${payload.part}` : "",
    payload.byteOffset != null ? `Byte offset: ${payload.byteOffset}` : "",
    payload.details ? `Details: ${payload.details}` : "",
    payload.hint ? `Hint: ${payload.hint}` : "",
  ].filter(Boolean).join(" · ");
  return context ? `${message} (${context})` : message;
}

"use client";

