              <div className="mt-4 flex flex-wrap items-end gap-x-4 gap-y-2">
                <h1 className="max-w-5xl text-2xl font-semibold leading-tight tracking-[-0.03em] text-white sm:text-4xl">
                  {summary.executiveBrief.headline}
