export function CalendarWorkspace() {
  const today = useMemo(() => new Date(), []);
  const [viewDate, setViewDate] = useState(new Date(today.getFullYear(), today.getMonth(), 1));
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [selectedDate, setSelectedDate] = useState(toDateKey(today));
  const [loaded, setLoaded] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [filter, setFilter] = useState<EventType | "all">("all");

  useEffect(() => {
    void (async () => {
      const documentKey = "business-calendar:v3";
      let stored = await loadAccountDocument<CalendarEvent[]>(documentKey);
      if (stored === null) {
        const legacyKey = await accountStorageKey("trading-docks-business-calendar-v3");
        const legacy = window.localStorage.getItem(legacyKey);
        if (legacy) {
          try {
            stored = JSON.parse(legacy) as CalendarEvent[];
            await saveAccountDocument(documentKey, stored);
          } catch {
            stored = [];
          }
          window.localStorage.removeItem(legacyKey);
        }
      }
      setEvents(stored ?? []);
      setLoaded(true);
    })();
  }, []);

  useEffect(() => {
    if (!loaded) return;
    const timeout = window.setTimeout(() => {
      void saveAccountDocument("business-calendar:v3", events);
    }, 300);
    return () => window.clearTimeout(timeout);
  }, [events, loaded]);

  const monthGrid = useMemo(() => buildMonthGrid(viewDate), [viewDate]);
  const visibleEvents = events.filter((event) => filter === "all" || event.type === filter);
  const selectedEvents = visibleEvents.filter((event) => event.date === selectedDate);

  return (
    <WorkspaceFrame>
      <PageHeader
        eyebrow="Business operations calendar"
        title="Schedule the work that keeps your business moving."
        description="Plan supply reorders, deliveries, events, employee shifts, time-card reviews, and payroll deadlines."
        icon={CalendarDays}
        actionLabel="Schedule activity"
        onAction={() => setModalOpen(true)}
      />

      <div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_0.65fr]">
        <section className={`${styles.glassPanel} rounded-[26px] p-5`}>
          <div className="flex items-center justify-between gap-4">
            <button type="button" onClick={() => setViewDate((current) => new Date(current.getFullYear(), current.getMonth() - 1, 1))} className="calendar-nav">
              <ChevronLeft className="h-4 w-4" />
            </button>

            <div className="text-center">
              <p className="text-lg font-semibold text-white">
                {viewDate.toLocaleString("en-US", { month: "long", year: "numeric" })}
              </p>
              <p className="mt-1 text-[9px] text-slate-600">Click a date to review or add activities</p>
            </div>

            <button type="button" onClick={() => setViewDate((current) => new Date(current.getFullYear(), current.getMonth() + 1, 1))} className="calendar-nav">
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>

          <div className="mt-5 flex flex-wrap gap-2">
            <FilterButton active={filter === "all"} onClick={() => setFilter("all")}>All</FilterButton>
            {(Object.keys(TYPE_CONFIG) as EventType[]).map((type) => (
              <FilterButton key={type} active={filter === type} onClick={() => setFilter(type)}>
                {TYPE_CONFIG[type].label}
              </FilterButton>
            ))}
          </div>

          <div className="mt-4 grid grid-cols-7 gap-2">
            {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => (
              <div key={day} className="py-2 text-center text-[8px] font-semibold uppercase tracking-[0.12em] text-slate-700">
                {day}
              </div>
            ))}

            {monthGrid.map((day) => {
              const key = toDateKey(day.date);
              const dayEvents = visibleEvents.filter((event) => event.date === key);
              const selected = key === selectedDate;

              return (
                <button
                  key={key}
                  type="button"
                  onClick={() => setSelectedDate(key)}
                  className={[
                    "min-h-[108px] rounded-xl border p-2 text-left transition",
                    day.inCurrentMonth
                      ? "border-white/[0.055] bg-black/[0.08] hover:border-cyan-300/[0.14] hover:bg-cyan-400/[0.025]"
                      : "border-transparent bg-black/[0.025] opacity-30",
                    selected ? "border-cyan-300/[0.2] bg-cyan-400/[0.05]" : "",
                  ].join(" ")}
                >
                  <span className="text-[9px] font-semibold text-slate-600">{day.date.getDate()}</span>
                  <span className="mt-1.5 block space-y-1">
                    {dayEvents.slice(0, 3).map((event) => (
                      <span key={event.id} className={`block truncate rounded-md border px-1.5 py-1 text-[6px] ${TYPE_CONFIG[event.type].className}`}>
                        {event.startTime} · {event.title}
                      </span>
                    ))}
                  </span>
                </button>
              );
            })}
          </div>
        </section>

        <aside className={`${styles.glassPanel} rounded-[26px] p-5`}>
          <p className="text-[9px] font-semibold uppercase tracking-[0.18em] text-cyan-300">
            Selected date
          </p>
          <h2 className="mt-2 text-lg font-semibold text-white">{formatDate(selectedDate)}</h2>

          <div className="mt-5 space-y-3">
            {selectedEvents.length ? (
              selectedEvents.map((event) => (
                <EventCard key={event.id} event={event} onRemove={() => setEvents((current) => current.filter((item) => item.id !== event.id))} />
              ))
            ) : (
              <button type="button" onClick={() => setModalOpen(true)} className="w-full rounded-2xl border border-dashed border-white/[0.07] bg-white/[0.015] px-4 py-8 text-center">
                <CalendarDays className="mx-auto h-5 w-5 text-slate-700" />
                <p className="mt-3 text-xs font-semibold text-slate-400">Nothing scheduled</p>
                <p className="mt-2 text-[10px] text-cyan-300">Add an activity</p>
              </button>
            )}
          </div>
        </aside>
      </div>

      <ScheduleModal
        open={modalOpen}
        defaultDate={selectedDate}
        onClose={() => setModalOpen(false)}
        onAdd={(event) => {
          setEvents((current) => [...current, event]);
          setSelectedDate(event.date);
          setModalOpen(false);
        }}
      />

      <style jsx global>{`
        .calendar-nav {
          display: flex;
          height: 40px;
          width: 40px;
          align-items: center;
          justify-content: center;
          border-radius: 12px;
          border: 1px solid rgba(255, 255, 255, 0.07);
          background: rgba(255, 255, 255, 0.025);
          color: rgb(100 116 139);
        }
        .calendar-input {
          height: 42px;
          width: 100%;
          border-radius: 12px;
          border: 1px solid rgba(255, 255, 255, 0.075);
          background: rgba(255, 255, 255, 0.025);
          padding: 0 12px;
          color: rgb(226 232 240);
          font-size: 12px;
          outline: none;
        }
        .calendar-input:focus {
          border-color: rgba(103, 232, 249, 0.24);
          box-shadow: 0 0 0 4px rgba(34, 211, 238, 0.045);
        }
      `}</style>
    </WorkspaceFrame>
  );
}

function FilterButton({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={[
        "h-9 rounded-xl border px-3 text-[9px] font-semibold",
        active ? "border-cyan-300/[0.17] bg-cyan-400/[0.07] text-cyan-100" : "border-white/[0.06] bg-white/[0.018] text-slate-600",
      ].join(" ")}
    >
      {children}
    </button>
  );
}

function EventCard({ event, onRemove }: { event: CalendarEvent; onRemove: () => void }) {
  const config = TYPE_CONFIG[event.type];
  const Icon = config.icon;

  return (
    <div className="rounded-2xl border border-white/[0.06] bg-black/[0.08] p-4">
      <div className="flex items-start gap-3">
        <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border ${config.className}`}>
          <Icon className="h-4 w-4" />
        </span>
        <div className="min-w-0 flex-1">
          <p className="text-xs font-semibold text-slate-200">{event.title}</p>
          <p className="mt-1 flex items-center gap-1.5 text-[9px] text-slate-600">
            <Clock3 className="h-3 w-3" />
            {event.startTime}{event.endTime ? `–${event.endTime}` : ""}
          </p>
          {event.assignee ? <p className="mt-1 text-[9px] text-slate-600">Assigned to {event.assignee}</p> : null}
        </div>
        <button type="button" onClick={onRemove} className="text-slate-700 hover:text-red-300">
          <X className="h-4 w-4" />
        </button>
      </div>
    </div>
  );
}

function ScheduleModal({
  open,
  defaultDate,
  onClose,
  onAdd,
}: {
  open: boolean;
  defaultDate: string;
  onClose: () => void;
  onAdd: (event: CalendarEvent) => void;
}) {
  const [title, setTitle] = useState("");
  const [date, setDate] = useState(defaultDate);
  const [startTime, setStartTime] = useState("09:00");
  const [endTime, setEndTime] = useState("");
  const [type, setType] = useState<EventType>("order");
  const [assignee, setAssignee] = useState("");
  const [recurring, setRecurring] = useState(false);

  useEffect(() => setDate(defaultDate), [defaultDate]);
  if (!open) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 p-4 backdrop-blur-md">
      <button type="button" onClick={onClose} className="absolute inset-0" />
      <form
        onSubmit={(event) => {
          event.preventDefault();
          if (!title.trim()) return;
          onAdd({
            id: crypto.randomUUID(),
            title: title.trim(),
            date,
            startTime,
            endTime: endTime || undefined,
            type,
            assignee: assignee || undefined,
            recurring,
          });
          setTitle("");
        }}
        className="relative z-10 w-full max-w-[560px] rounded-[28px] border border-cyan-300/[0.14] bg-[#06131d]/98 p-6"
      >
        <div className="flex items-center justify-between">
          <div>
            <p className="text-lg font-semibold text-white">Schedule activity</p>
            <p className="mt-1 text-[10px] text-slate-600">Orders, deliveries, events, shifts, or payroll.</p>
          </div>
          <button type="button" onClick={onClose} className="text-slate-500"><X className="h-4 w-4" /></button>
        </div>

        <div className="mt-6 grid gap-4 sm:grid-cols-2">
          <Field label="Activity name" className="sm:col-span-2">
            <input value={title} onChange={(event) => setTitle(event.target.value)} className="calendar-input" placeholder="Reorder shipping labels" required />
          </Field>
          <Field label="Type">
            <select value={type} onChange={(event) => setType(event.target.value as EventType)} className="calendar-input">
              {(Object.keys(TYPE_CONFIG) as EventType[]).map((value) => <option key={value} value={value}>{TYPE_CONFIG[value].label}</option>)}
            </select>
          </Field>
          <Field label="Date">
            <input type="date" value={date} onChange={(event) => setDate(event.target.value)} className="calendar-input" required />
          </Field>
          <Field label="Start time">
            <input type="time" value={startTime} onChange={(event) => setStartTime(event.target.value)} className="calendar-input" required />
          </Field>
          <Field label="End time">
            <input type="time" value={endTime} onChange={(event) => setEndTime(event.target.value)} className="calendar-input" />
          </Field>
          <Field label="Employee or team" className="sm:col-span-2">
            <input value={assignee} onChange={(event) => setAssignee(event.target.value)} className="calendar-input" placeholder="Alex, Fulfillment team..." />
          </Field>
        </div>

        <label className="mt-4 flex items-center gap-2 text-[10px] text-slate-500">
          <input type="checkbox" checked={recurring} onChange={(event) => setRecurring(event.target.checked)} />
          Repeat this activity
        </label>

        <button type="submit" className="mt-6 h-11 w-full rounded-xl bg-gradient-to-b from-cyan-300 via-cyan-400 to-sky-500 text-xs font-semibold text-[#001018]">
          Add to calendar
        </button>
      </form>
    </div>
  );
}

function Field({ label, children, className = "" }: { label: string; children: React.ReactNode; className?: string }) {
  return <label className={className}><span className="mb-2 block text-[9px] text-slate-500">{label}</span>{children}</label>;
}

function buildMonthGrid(viewDate: Date) {
  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const first = new Date(year, month, 1);
  const start = new Date(year, month, 1 - first.getDay());

  return Array.from({ length: 42 }, (_, index) => {
    const date = new Date(start);
    date.setDate(start.getDate() + index);
    return { date, inCurrentMonth: date.getMonth() === month };
  });
}

function toDateKey(date: Date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function formatDate(value: string) {
  const [year, month, day] = value.split("-").map(Number);
  return new Date(year, month - 1, day).toLocaleDateString("en-US", {
    weekday: "long",
    month: "long",
    day: "numeric",
  });
}

