    <input
      value={value}
      onChange={(event) => onChange(event.target.value)}
      placeholder={placeholder}
      className="h-10 w-full rounded-xl border border-white/[0.065] bg-white/[0.02] px-3 text-[10px] text-slate-300 outline-none placeholder:text-slate-700"
    />
  );
}

function SettingNumber({
  label,
  value,
  onChange,
  prefix,
  suffix,
  step = 1,
  disabled = false,
}: {
  label: string;
  value: number;
  onChange: (value: number) => void;
  prefix?: string;
  suffix?: string;
  step?: number;
  disabled?: boolean;
}) {
  return (
    <label>
      <span className="mb-2 block text-[8px] font-semibold uppercase tracking-[0.12em] text-slate-700">
        {label}
      </span>
      <span className="flex h-10 items-center rounded-xl border border-white/[0.065] bg-white/[0.02] px-3">
        {prefix ? (
          <span className="mr-1 text-[9px] text-slate-700">{prefix}</span>
        ) : null}
        <input
          type="number"
          step={step}
          value={value}
          disabled={disabled}
          onChange={(event) => onChange(Number(event.target.value) || 0)}
          className="min-w-0 flex-1 bg-transparent text-[10px] text-slate-300 outline-none disabled:opacity-40"
        />
        {suffix ? (
          <span className="ml-1 text-[9px] text-slate-700">{suffix}</span>
        ) : null}
      </span>
    </label>
  );
}

function SettingSelect({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: string;
  options: Array<[string, string]>;
  onChange: (value: string) => void;
}) {
  return (
    <label>
      <span className="mb-2 block text-[8px] font-semibold uppercase tracking-[0.12em] text-slate-700">
        {label}
      </span>
      <select
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="h-10 w-full rounded-xl border border-white/[0.065] bg-[#07141e] px-3 text-[10px] text-slate-400 outline-none"
      >
        {options.map(([optionValue, optionLabel]) => (
          <option key={optionValue} value={optionValue}>
            {optionLabel}
          </option>
        ))}
      </select>
    </label>
  );
}

function ModalFrame({
  children,
  onClose,
  maxWidth,
}: {
  children: React.ReactNode;
  onClose: () => void;
  maxWidth: string;
}) {
  return (
    <div className="fixed inset-0 z-[140] flex items-center justify-center bg-black/75 p-4 backdrop-blur-md">
      <button
        type="button"
        onClick={onClose}
        className="absolute inset-0"
        aria-label="Close"
      />
      <div
        className={`relative z-10 max-h-[92vh] w-full ${maxWidth} overflow-y-auto rounded-[28px] border border-cyan-300/[0.13] bg-[#06131d]/98 p-5 shadow-[0_38px_120px_rgba(0,0,0,0.58)] sm:p-6`}
      >
        {children}
      </div>
    </div>
  );
}

function ModalHeader({
  eyebrow,
  title,
  onClose,
}: {
  eyebrow: string;
  title: string;
  onClose: () => void;
}) {
  return (
    <div className="flex items-start justify-between gap-4">
      <div>
        <p className="text-[8px] font-semibold uppercase tracking-[0.17em] text-cyan-300">
          {eyebrow}
        </p>
        <h2 className="mt-2 text-xl font-semibold text-white">{title}</h2>
      </div>
      <button
        type="button"
        onClick={onClose}
        className="flex h-9 w-9 items-center justify-center rounded-xl border border-white/[0.07] bg-white/[0.025] text-slate-500"
      >
        <X className="h-4 w-4" />
      </button>
    </div>
  );
}

function capitalize(value: string) {
  return value.charAt(0).toUpperCase() + value.slice(1);
}

function currency(value: number) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 2,
  }).format(Number.isFinite(value) ? value : 0);
}

function exportCsv(
  cards: AppraisalCard[],
  settings: BuyingSettings,
  customerName: string,
  cashOffer: number,
) {
  const header = [
    "Card",
    "Set",
    "Collector Number",
    "Quantity",
    "Finish",
    "Condition",
    "Unit Market",
    "Adjusted Market",
    "Suggested Percent",
    "Final Offer",
  ];

  const rows = cards.map((item) => {
    const economics =
      item.status === "ready"
        ? estimateCardEconomics(item, settings)
        : null;

    return [
      item.card?.name ?? item.name,
      item.card?.set.toUpperCase() ?? item.setCode ?? "",
      item.card?.collector_number ?? item.collectorNumber ?? "",
      item.quantity,
      item.finish,
      item.condition,
      item.unitMarket.toFixed(2),
      item.lineMarketValue.toFixed(2),
      item.suggestedPercent.toFixed(2),
      economics?.offer.toFixed(2) ?? "0.00",
    ];
  });

  rows.push([
    "TOTAL OFFER",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    cashOffer.toFixed(2),
  ]);

  const csv = [header, ...rows]
    .map((row) =>
      row
        .map((value) => `"${String(value).replaceAll('"', '""')}"`)
        .join(","),
    )
    .join("\\n");

  downloadFile(
    csv,
    `${slug(customerName || "walk-in")}-collection-appraisal.csv`,
    "text/csv;charset=utf-8",
  );
}

function exportJson(payload: unknown) {
  downloadFile(
    JSON.stringify(payload, null, 2),
    "collection-appraisal.json",
    "application/json",
  );
}

function downloadFile(
  contents: string,
  filename: string,
  type: string,
) {
  const blob = new Blob([contents], { type });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
}

function slug(value: string) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

function emptyTotalsShape() {
  return {
    market: 0,
    cashOffer: 0,
    storeCreditOffer: 0,
    fees: 0,
    shipping: 0,
    labor: 0,
    projectedNet: 0,
    projectedProfit: 0,
    averageOfferPercent: 0,
    projectedMargin: 0,
    units: 0,
  };
}

function choosePokemonCandidate(
  row: ReturnType<typeof parseCollectionText>[number],
  candidates: CardCandidate[],
) {
  if (!candidates.length) return null;
  if (row.setCode && row.collectorNumber) {
    const normalizedSet = row.setCode.toLowerCase();
    const normalizedNumber = row.collectorNumber.toLowerCase();
    return candidates.find(
      (candidate) =>
        candidate.setCode.toLowerCase() === normalizedSet &&
        candidate.collectorNumber.toLowerCase() === normalizedNumber,
    ) ?? null;
  }
  if (row.setCode) {
    const normalizedSet = row.setCode.toLowerCase();
    const matchingSet = candidates.filter(
      (candidate) => candidate.setCode.toLowerCase() === normalizedSet,
    );
    return matchingSet.length === 1 ? matchingSet[0] : null;
  }
  return candidates.length === 1 ? candidates[0] : null;
}

function normalizePokemonFinish(finish: PriceFinish): PriceFinish {
  if (finish === "foil") return "holo";
  if (finish === "etched") return "reverse_holo";
  if (finish === "nonfoil") return "normal";
  return finish;
}

function pokemonCandidateToCard(candidate: CardCandidate): ScryfallCard {
  const market =
    candidate.prices.find((price) => price.label === "TCG Market")?.value ??
    candidate.prices.find((price) => price.label === "TCG Low")?.value ??
    null;

  return {
    id: candidate.id,
    gameId: "pokemon",
    provider: "tcgtracking",
    providerProductId: candidate.providerProductId,
    providerSkuId: candidate.providerSkuId,
    tcgplayerProductId: candidate.tcgplayerProductId,
    tcgplayerSkuId: candidate.tcgplayerSkuId,
    name: candidate.name,
    set: candidate.setCode.toLowerCase(),
    set_name: candidate.setName,
    collector_number: candidate.collectorNumber,
    rarity: candidate.rarity ?? "unknown",
    reserved: false,
    reprint: true,
    prices: {
      usd: market == null ? null : String(market),
      usd_foil: market == null ? null : String(market),
      usd_etched: null,
    },
    image_uris: candidate.imageUrl
      ? {
          small: candidate.imageUrl,
          normal: candidate.imageUrl,
        }
      : undefined,
    purchase_uris: {},
  };
}

async function loadOrMigrateDocument<T>(
  documentKey: string,
  legacyStorageKey: string,
  fallback: T,
): Promise<T> {
  const cloudValue = await loadAccountDocument<T>(documentKey);
  if (cloudValue !== null) return cloudValue;

  const legacyValue = window.localStorage.getItem(legacyStorageKey);
  if (!legacyValue) {
    await saveAccountDocument(documentKey, fallback);
    return fallback;
  }

  try {
    const parsed = JSON.parse(legacyValue) as T;
    await saveAccountDocument(documentKey, parsed);
    window.localStorage.removeItem(legacyStorageKey);
    return parsed;
  } catch {
    window.localStorage.removeItem(legacyStorageKey);
    await saveAccountDocument(documentKey, fallback);
    return fallback;
  }
}

