                    <h2 className="mt-4 text-xl font-semibold text-white">{selectedCard.name}</h2>
                    <p className="mt-1 text-[10px] text-slate-600">{[selectedCard.set, selectedCard.condition, selectedCard.finish].filter(Boolean).join(" · ")}</p>
