                value={analytics.averageManaValue.toFixed(2)}
              />
              <MiniMetric
                label="Missing"
                value={`${missingCards}`}
              />
              <MiniMetric
                label="Power"
                value={`${deck.power.toFixed(1)}/10`}
              />
