  const context = inspectCollection(inspectDeck(deck), collection);
  const [input, setInput] = useState("");
  const [proposal, setProposal] = useState<DeckChangeProposal | null>(null);
  const [message, setMessage] = useState("I’m connected to this working deck. Every change will be checked by Trading Docks rules before you can apply it.");
  const [busy, setBusy] = useState(false);

  async function submit(command = input) {
    const trimmed = command.trim();
    if (!trimmed) return;
    setInput(trimmed);
    setProposal(null);
    const direct = trimmed.match(/^(add|remove)\s+(.+?)(?:\s+x?(\d+))?$/i);
    if (!direct) {
      setMessage(`Deckmaster has ${context.cards.reduce((sum, card) => sum + card.quantity, 0)} cards from “${context.deckName}” in context. Recommendation generation for “${trimmed}” will use the preserved strategy providers; no unverified card changes were created.`);
      return;
    }

    const operation = direct[1].toLowerCase();
    const cardName = direct[2].trim();
    const quantity = Math.max(1, Number(direct[3] ?? 1));
    if (operation === "remove") {
      const card = deck.cards.find((item) => item.name.toLowerCase() === cardName.toLowerCase());
      if (!card) { setMessage(`${cardName} is not in this deck.`); return; }
      setProposal(createDeckChangeProposal(deck, {
        additions: [], removals: [{ card, quantity, reason: "Requested by you." }], swaps: [],
        explanation: `Remove ${quantity} ${card.name}.`,
      }));
      setMessage("I prepared a reviewable change. The deck has not been modified.");
      return;
    }

    setBusy(true);
    try {
      const params = new URLSearchParams({ q: `!\"${cardName}\"` });
      const response = await fetch(`/api/deck-vault/card-search?${params.toString()}`);
      const payload = await response.json() as { results?: ScryfallCardResult[] };
      const result = payload.results?.find((item) => item.name.toLowerCase() === cardName.toLowerCase());
      if (!result) { setMessage(`I could not resolve an exact card named “${cardName}”. Nothing changed.`); return; }
      const formatId = deckFormatToArchitectFormat(deck.format);
      const card: DeckCard = {
        id: result.id, name: result.name, quantity, manaValue: result.manaValue,
        colors: result.colorIdentity.length ? result.colorIdentity : result.colors,
        typeLine: result.typeLine, category: categoryFor(result.typeLine), price: result.price,
        owned: false, ownedQuantity: 0, image: result.image, artCrop: result.artCrop,
        setCode: result.setCode, collectorNumber: result.collectorNumber, board: "main",
        legalityStatus: result.legalities?.[formatId],
      };
      const next = createDeckChangeProposal(deck, {
        additions: [{ card, quantity, reason: "Requested by you." }], removals: [], swaps: [],
        explanation: `Add ${quantity} ${result.name}.`,
      });
      setProposal(next);
      setMessage(next.legality.canApply
        ? "I prepared a reviewable change. The deck has not been modified."
        : "Trading Docks found a new legality violation. This proposal cannot be applied.");
    } catch {
      setMessage("Card search is unavailable right now. Nothing changed.");
    } finally { setBusy(false); }
  }

  function apply() {
    if (!proposal) return;
    try {
      onApply(applyDeckChangeProposal(deck, proposal));
      setMessage("Changes applied through the deterministic deck validation pipeline.");
      setProposal(null);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Trading Docks rejected this change.");
    }
  }

  return (
    <aside aria-label="Deckmaster AI Deck Assistant" className={[
      "border-white/[0.08] bg-[#06131f] shadow-[0_24px_80px_rgba(0,0,0,.3)]",
      "fixed inset-0 z-[150] overflow-y-auto p-5 lg:sticky lg:top-5 lg:z-auto lg:block lg:max-h-[calc(100vh-2.5rem)] lg:rounded-[24px] lg:border lg:p-5",
      mobileOpen ? "block" : "hidden",
    ].join(" ")}>
      <div className="flex items-start justify-between gap-3 border-b border-white/[0.07] pb-4">
        <div><div className="flex items-center gap-2 text-cyan-300"><Sparkles className="h-4 w-4" /><span className="text-[10px] font-semibold uppercase tracking-[0.18em]">AI Deck Assistant</span></div><h2 className="mt-1 text-xl font-semibold text-white">Deckmaster</h2><p className="mt-1 text-xs text-slate-500">Working on {context.deckName} · {context.format}</p></div>
        <button type="button" onClick={onMobileClose} className="flex h-10 w-10 items-center justify-center rounded-xl border border-white/[0.08] text-slate-400 lg:hidden" aria-label="Close Deckmaster"><X className="h-4 w-4" /></button>
      </div>

      <p className="mt-4 text-sm leading-6 text-slate-300" role="status">{message}</p>
      <div className="mt-5 grid grid-cols-2 gap-2">
        {QUICK_ACTIONS.map((action) => <button key={action} type="button" onClick={() => void submit(action)} className="min-h-11 rounded-xl border border-white/[0.07] bg-white/[0.025] px-3 py-2 text-left text-xs font-medium text-slate-300 transition hover:border-cyan-300/25 hover:bg-cyan-300/[0.05] hover:text-white">{action}</button>)}
      </div>

      {proposal ? <ProposalReview proposal={proposal} onApply={apply} onCancel={() => { setProposal(null); setMessage("Proposal cancelled. Your deck is unchanged."); }} /> : null}

      <form onSubmit={(event) => { event.preventDefault(); void submit(); }} className="mt-5 border-t border-white/[0.07] pt-4">
        <label htmlFor="deckmaster-input" className="sr-only">Ask Deckmaster about this deck</label>
        <textarea id="deckmaster-input" value={input} onChange={(event) => setInput(event.target.value)} placeholder="Ask Deckmaster about this deck..." rows={3} className="w-full resize-none rounded-xl border border-white/[0.09] bg-black/20 px-3 py-3 text-sm text-white outline-none placeholder:text-slate-600 focus:border-cyan-300/40" />
        <button disabled={busy || !input.trim()} className="mt-2 inline-flex h-10 w-full items-center justify-center gap-2 rounded-xl bg-cyan-300 text-xs font-semibold text-[#00121c] disabled:opacity-40">{busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <ArrowRight className="h-4 w-4" />} Ask Deckmaster</button>
      </form>
    </aside>
  );
}

function ProposalReview({ proposal, onApply, onCancel }: { proposal: DeckChangeProposal; onApply: () => void; onCancel: () => void }) {
  const count = proposal.additions.length + proposal.removals.length + proposal.swaps.length;
  return <section className="mt-5 rounded-2xl border border-cyan-300/15 bg-cyan-300/[0.035] p-4">
    <p className="text-sm font-semibold text-white">Deckmaster recommends {count} {count === 1 ? "change" : "changes"}</p>
    <details open className="mt-3">
      <summary className="cursor-pointer text-xs font-semibold text-cyan-200">Review Changes</summary>
      {proposal.additions.length ? <ChangeList label="Add" changes={proposal.additions} tone="text-emerald-300" /> : null}
      {proposal.removals.length ? <ChangeList label="Remove" changes={proposal.removals} tone="text-rose-300" /> : null}
      {proposal.swaps.map((swap) => <p key={`${swap.remove.card.id}-${swap.add.card.id}`} className="mt-3 text-xs text-slate-300">Swap {swap.remove.card.name} → {swap.add.card.name}</p>)}
    </details>
    <dl className="mt-4 space-y-2 border-t border-white/[0.07] pt-3 text-xs"><Row label="Estimated price change" value={`${proposal.pricingImpact >= 0 ? "+" : "−"}$${Math.abs(proposal.pricingImpact).toFixed(2)}`} /><Row label="Owned / missing change" value={`${signed(proposal.ownershipImpact.owned)} owned · ${signed(proposal.ownershipImpact.missing)} missing`} /></dl>
    <div className={`mt-3 flex items-start gap-2 rounded-xl p-3 text-xs ${proposal.legality.canApply ? "bg-emerald-400/10 text-emerald-200" : "bg-rose-400/10 text-rose-100"}`}><ShieldCheck className="mt-0.5 h-4 w-4 shrink-0" /><span>{proposal.legality.valid ? "Legal complete-deck state" : proposal.legality.canApply ? "Safe for this in-progress deck; complete-format validation is still pending." : proposal.legality.introducedIssues.map((issue) => issue.message).join(" ")}</span></div>
    <div className="mt-4 grid grid-cols-2 gap-2"><button type="button" onClick={onCancel} className="h-10 rounded-xl border border-white/[0.09] text-xs font-semibold text-slate-300">Cancel</button><button type="button" onClick={onApply} disabled={!proposal.legality.canApply} className="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-cyan-300 text-xs font-semibold text-[#00121c] disabled:cursor-not-allowed disabled:opacity-40"><CheckCircle2 className="h-4 w-4" />Apply All</button></div>
  </section>;
}

function ChangeList({ label, changes, tone }: { label: string; changes: Array<{ card: DeckCard; quantity: number }>; tone: string }) { return <div className="mt-3"><p className={`text-[10px] font-semibold uppercase tracking-[0.14em] ${tone}`}>{label}</p>{changes.map((change) => <div key={`${label}-${change.card.id}`} className="mt-2 flex items-center gap-3"><div className="h-12 w-9 overflow-hidden rounded-md bg-white/5">{change.card.image ? <img src={change.card.image} alt="" className="h-full w-full object-cover" /> : null}</div><span className="text-xs text-slate-200">{change.quantity}× {change.card.name}</span></div>)}</div>; }
function Row({ label, value }: { label: string; value: string }) { return <div className="flex justify-between gap-3"><dt className="text-slate-500">{label}</dt><dd className="text-right text-slate-200">{value}</dd></div>; }
function signed(value: number) { return value > 0 ? `+${value}` : String(value); }
function categoryFor(typeLine: string) { return ["Creature", "Instant", "Sorcery", "Artifact", "Enchantment", "Planeswalker", "Land"].find((type) => typeLine.includes(type)) ?? "Other"; }

"use client";

import { useState } from "react";
import type { ManaColor } from "@/lib/deck-vault/types";

export function ManaPips({
  colors,
  size = "md",
}: {
  colors: ManaColor[];
  size?: "sm" | "md" | "lg";
}) {
  return (
    <div className="flex flex-wrap items-center gap-1.5">
      {colors.map((color) => (
        <ManaSymbol
          key={color}
          color={color}
          size={size}
        />
      ))}
    </div>
  );
}

function ManaSymbol({
  color,
  size,
}: {
  color: ManaColor;
  size: "sm" | "md" | "lg";
}) {
  const [failed, setFailed] = useState(false);

  const wrapperSize = {
    sm: "h-7 w-7",
    md: "h-9 w-9",
    lg: "h-11 w-11",
  }[size];

  const fallbackSize = {
    sm: "text-[11px]",
    md: "text-[13px]",
    lg: "text-[15px]",
  }[size];

  return (
    <span
      title={`${name(color)} mana`}
      className={[
        "inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full border border-white/15 bg-slate-950 shadow-[0_2px_8px_rgba(0,0,0,0.38)]",
        wrapperSize,
      ].join(" ")}
    >
      {!failed ? (
        <img
          src={`/mana/${color}.svg`}
          alt={`${name(color)} mana`}
          loading="eager"
          onError={() => setFailed(true)}
          className="h-[92%] w-[92%] object-contain"
        />
      ) : (
        <span
          className={[
            "font-black",
            fallbackSize,
            fallbackColor(color),
          ].join(" ")}
        >
          {color}
        </span>
      )}
    </span>
  );
}

function fallbackColor(color: ManaColor) {
  return {
    W: "text-amber-100",
    U: "text-sky-300",
    B: "text-stone-200",
    R: "text-rose-300",
    G: "text-emerald-300",
    C: "text-slate-300",
  }[color];
}

function name(color: ManaColor) {
  return {
    W: "White",
    U: "Blue",
    B: "Black",
    R: "Red",
    G: "Green",
    C: "Colorless",
  }[color];
}

"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import {
  ArrowRight,
  BrainCircuit,
  FolderPlus,
  Import,
  LibraryBig,
  Pencil,
  Save,
  Search,
  Sparkles,
  Trash2,
  TrendingUp,
  X,
} from "lucide-react";

import { ManaPips } from "./ManaPips";
import type { DeckRecord } from "@/lib/deck-vault/types";
import {
  deleteDeckRecord,
  loadDeckVault,
  saveDeckRecord,
} from "@/lib/deck-vault/persistence";

const FORMATS = [
  "All Formats",
  "EDH",
  "Pauper EDH",
  "Standard",
  "Modern",
  "Pioneer",
  "Legacy",
  "Vintage",
  "Alchemy",
  "Premodern",
  "Pauper",
];

export function DeckVaultHome({ plan, deckLimit }: { plan: string; deckLimit: number | null }) {
  const [format, setFormat] = useState("All Formats");
  const [savedDecks, setSavedDecks] =
    useState<DeckRecord[]>([]);
  const [searchQuery, setSearchQuery] =
    useState("");
  const [loadingDecks, setLoadingDecks] = useState(true);
  const [storageError, setStorageError] = useState("");
  const [renameDeck, setRenameDeck] = useState<DeckRecord | null>(null);
  const [renameValue, setRenameValue] = useState("");

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const decks = await loadDeckVault();
        if (!cancelled) {
          setSavedDecks(decks);
          setStorageError("");
        }
      } catch (error) {
        if (!cancelled) {
          setSavedDecks([]);
          setStorageError(
            error instanceof Error
              ? error.message
              : "Your saved decks could not be loaded.",
          );
        }
      } finally {
        if (!cancelled) setLoadingDecks(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const visibleDecks = useMemo(() => {
    const normalized =
      searchQuery.trim().toLowerCase();

    return savedDecks.filter((deck) => {
      const matchesFormat =
        format === "All Formats" ||
        deck.format === format;
      const matchesSearch =
        !normalized ||
        deck.name
          .toLowerCase()
          .includes(normalized) ||
        deck.commander
          ?.toLowerCase()
          .includes(normalized) ||
        deck.theme
          .toLowerCase()
          .includes(normalized);

      return matchesFormat && matchesSearch;
    });
  }, [format, savedDecks, searchQuery]);

  const combinedValue = savedDecks.reduce(
    (total, deck) => total + (Number.isFinite(deck.marketValue) ? deck.marketValue : 0),
    0,
  );
  const limitReached = deckLimit !== null && savedDecks.length >= deckLimit;

  async function deleteDeck(
    deckId: string,
    deckName: string,
  ) {
    const confirmed = window.confirm(
      `Delete "${deckName}" from Deck Vault?`,
    );

    if (!confirmed) return;

    try {
      await deleteDeckRecord(deckId);
      setSavedDecks((current) =>
        current.filter((deck) => deck.id !== deckId),
      );
      setStorageError("");
    } catch (error) {
      setStorageError(
        error instanceof Error ? error.message : "The deck could not be deleted.",
      );
    }
  }

  async function saveDeckName() {
    if (!renameDeck) return;
    const name = renameValue.trim();
    if (!name) return;
    const updated = { ...renameDeck, name, updatedAt: "Just now" };
    try {
      await saveDeckRecord(updated);
      setSavedDecks((current) =>
        current.map((deck) => (deck.id === updated.id ? updated : deck)),
      );
      setRenameDeck(null);
      setStorageError("");
    } catch (error) {
      setStorageError(
        error instanceof Error ? error.message : "The deck name could not be saved.",
      );
    }
  }

  return (
    <main className="min-h-screen bg-[#020912] px-5 py-7 text-white sm:px-8 lg:px-10">
      <div className="mx-auto max-w-[1500px]">
        {storageError ? (
          <div className="mb-5 rounded-2xl border border-rose-400/20 bg-rose-400/[0.06] px-4 py-3 text-sm text-rose-200">
            {storageError}
          </div>
        ) : null}
        <header className="relative overflow-hidden rounded-[30px] border border-sky-300/[0.12] bg-[#06131f] p-6 sm:p-8">
          <div className="absolute -right-20 -top-24 h-72 w-72 rounded-full bg-sky-400/[0.08] blur-3xl" />
          <div className="absolute bottom-[-90px] left-[35%] h-56 w-56 rounded-full bg-violet-500/[0.08] blur-3xl" />

          <div className="relative flex flex-col gap-6 xl:flex-row xl:items-end xl:justify-between">
            <div>
              <div className="flex items-center gap-3">
                <span className="flex h-11 w-11 items-center justify-center rounded-2xl border border-sky-300/[0.14] bg-sky-400/[0.05] text-sky-300">
                  <LibraryBig className="h-5 w-5" />
                </span>
                <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-sky-300">
                  Deck Vault
                </p>
              </div>

              <h1 className="mt-5 max-w-4xl text-3xl font-semibold tracking-[-0.05em] sm:text-5xl">
                Build deeper. Analyze smarter. Know every deck.
              </h1>
              <p className="mt-4 max-w-3xl text-[15px] leading-7 text-slate-400">
                Import decks from Moxfield, ManaBox, MTGGoldfish, Archidekt,
                Deckstats, Arena, CSV, or plain text and turn them into a
                living analytics workspace connected to your collection.
              </p>

              <div className="mt-5">
                <ManaPips colors={["W", "U", "B", "R", "G"]} size="lg" />
              </div>
            </div>

            <div className="grid gap-3 sm:grid-cols-2">
              <Link
                href={limitReached ? "/dashboard/plans" : "/dashboard/deck-vault/import"}
                className="inline-flex h-12 items-center justify-center gap-2 rounded-xl bg-sky-300 px-5 text-[13px] font-semibold text-[#00121c]"
              >
                <Import className="h-4 w-4" />
                {limitReached ? "Upgrade to add decks" : "Import a deck"}
              </Link>
              <Link
                href={limitReached ? "/dashboard/plans" : "/dashboard/deck-vault/new"}
                className="inline-flex h-12 items-center justify-center gap-2 rounded-xl border border-white/[0.08] bg-white/[0.025] px-5 text-[13px] font-semibold text-slate-300"
              >
                <FolderPlus className="h-4 w-4" />
                {limitReached ? "Deck limit reached" : "Create new deck"}
              </Link>
            </div>
          </div>
        </header>

        <section className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
          <Kpi label="Decks" value={loadingDecks ? "…" : deckLimit === null ? String(savedDecks.length) : `${savedDecks.length} / ${deckLimit}`} detail={deckLimit === null ? "Unlimited on this plan" : `${plan === "free" ? "Free" : "Collector"} plan allowance`} icon={LibraryBig} />
          <Kpi label="Combined Value" value={`$${combinedValue.toFixed(2)}`} detail={savedDecks.length ? "Across saved decks" : "No deck value tracked"} icon={TrendingUp} />
          <Kpi label="Collection Coverage" value="0%" detail={savedDecks.length ? "Add inventory to calculate coverage" : "No decks to compare"} icon={Sparkles} />
          <Kpi label="AI Reviews" value="0" detail="No reviews generated" icon={BrainCircuit} />
        </section>

        <section className="mt-5 grid gap-5 xl:grid-cols-[1.4fr_0.7fr]">
          <div className="rounded-[26px] border border-white/[0.07] bg-[#06131f] p-5">
            <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
              <div>
                <p className="text-[11px] font-semibold uppercase tracking-[0.13em] text-sky-300">
                  My Decks
                </p>
                <h2 className="mt-2 text-2xl font-semibold">Recently opened</h2>
              </div>
              <div className="flex flex-col gap-2 sm:flex-row">
                <select
                  value={format}
                  onChange={(event) =>
                    setFormat(event.target.value)
                  }
                  className="h-10 rounded-xl border border-white/[0.07] bg-[#07141e] px-3 text-[12px] text-slate-400 outline-none"
                >
                  {FORMATS.map((item) => (
                    <option key={item}>{item}</option>
                  ))}
                </select>

                <label className="flex h-10 items-center gap-2 rounded-xl border border-white/[0.07] bg-black/[0.1] px-3">
                  <Search className="h-4 w-4 text-slate-700" />
                  <input
                    value={searchQuery}
                    onChange={(event) =>
                      setSearchQuery(
                        event.target.value,
                      )
                    }
                    placeholder="Search decks..."
                    className="bg-transparent text-[12px] text-slate-300 outline-none placeholder:text-slate-700"
                  />
                </label>
              </div>
            </div>

            <div className="mt-5 grid gap-4 lg:grid-cols-3">
              {visibleDecks.length === 0 ? (
                <div className="col-span-full rounded-[22px] border border-dashed border-white/[0.08] bg-black/[0.08] px-6 py-12 text-center">
                  <p className="text-sm font-semibold text-slate-300">Your Deck Vault is empty</p>
                  <p className="mt-2 text-[12px] text-slate-600">Import a deck or create one to get started.</p>
                </div>
              ) : null}
              {visibleDecks.map((deck) => (
                <article
                  key={deck.id}
                  className="group relative overflow-hidden rounded-[22px] border border-white/[0.07] bg-black/[0.12] transition duration-300 hover:-translate-y-1 hover:border-sky-300/[0.18]"
                >
                  <Link
                    href={`/dashboard/deck-vault/decks/${deck.id}`}
                    className="block p-4"
                  >
                    <div className="absolute right-[-30px] top-[-30px] h-28 w-28 rounded-full bg-sky-400/[0.05] blur-2xl" />
                    <div className="relative">
                      <ManaPips colors={displayDeckColors(deck.colors)} />
                      <h3 className="mt-4 text-[18px] font-semibold">{deck.name}</h3>
                      <p className="mt-1 text-[13px] text-slate-400">{deck.commander || "No commander selected"}</p>
                      <p className="mt-1 text-[12px] text-slate-500">{deck.theme}</p>

                      <div className="mt-5 grid grid-cols-2 gap-2">
                        <Metric label="Value" value={`$${deck.marketValue.toFixed(2)}`} />
                        <Metric label="Power" value={`${deck.power.toFixed(1)} / 10`} />
                        <Metric label="Owned" value={`${deck.ownedCount}%`} />
                        <Metric label="Format" value={deck.format} />
                      </div>

                      <div className="mt-4 flex items-center justify-between border-t border-white/[0.05] pt-3">
                        <span className="text-[12px] text-slate-500">{deck.updatedAt}</span>
                        <ArrowRight className="h-4 w-4 text-slate-700 transition group-hover:translate-x-1 group-hover:text-sky-300" />
                      </div>
                    </div>
                  </Link>

                  <button
                    type="button"
                    onClick={() => {
                      setRenameDeck(deck);
                      setRenameValue(deck.name);
                    }}
                    className="absolute right-3 top-3 z-20 inline-flex h-9 items-center justify-center gap-2 rounded-xl border border-sky-300/[0.22] bg-[#07141e]/95 px-3 text-[11px] font-semibold text-sky-200 shadow-lg backdrop-blur transition hover:border-sky-200/40 hover:bg-sky-400/[0.1] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-300/60"
                    aria-label={`Rename ${deck.name}`}
                    title="Rename deck"
                  >
                    <Pencil className="h-4 w-4" />
                    Rename
                  </button>

                  <button
                    type="button"
                    onClick={() =>
                      deleteDeck(
                        deck.id,
                        deck.name,
                      )
                    }
                    className="absolute right-3 top-14 z-20 flex h-9 w-9 items-center justify-center rounded-xl border border-rose-300/[0.13] bg-[#07141e]/92 text-rose-300 opacity-0 shadow-lg backdrop-blur transition hover:bg-rose-400/[0.08] focus-visible:opacity-100 group-hover:opacity-100"
                    aria-label={`Delete ${deck.name}`}
                    title="Delete deck"
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </article>
              ))}
