      ) : null}
    </main>
  );
}

function displayDeckColors(
  colors: DeckRecord["colors"],
) {
  const unique = Array.from(
    new Set(colors),
  );
  const colored = unique.filter(
    (color) => color !== "C",
  );

  return colored.length
    ? colored
    : unique;
}

