  items,
  locations,
  allItems,
  onClose,
  onMove,
  onUndo,
  onDelete,
}: {
  items: InventoryItem[];
  locations: LocationRecord[];
  allItems: InventoryItem[];
  onClose: () => void;
  onMove: (
    itemId: string,
