  }
  return (
    <section className={`${styles.glassPanel} rounded-[26px] p-5`}>
      <div className="flex items-start justify-between gap-4">
        <div>
          <p className="text-[9px] font-semibold uppercase tracking-[0.18em] text-amber-300">
