            background-color: #0b1822;
            color: #e2e8f0;
          }

          select.inventory-input option:checked {
            background: #164e63 linear-gradient(0deg, #164e63 0%, #164e63 100%);
            color: #ecfeff;
          }

          select.inventory-input option:disabled {
