} from "lucide-react";

import { createClient } from "@/lib/supabase/client";

type ConnectionMethod = "api" | "csv" | "email" | "manual";
type ConnectionStatus = "not_configured" | "setup_required" | "ready" | "attention";
type MarketplaceDefinition = {
