  email: "Order email tracking",
  manual: "Guided manual tracking",
};

const MARKETPLACE_CALLBACK_ORIGIN =
  process.env.NEXT_PUBLIC_SITE_URL?.replace(/\/+$/, "") ||
  "https://www.tradingdocks.com";

const marketplaces: MarketplaceDefinition[] = [
  {
