  "Moderately Played",
  "Heavily Played",
  "Damaged",
];

const conditionMultiplier: Record<string, number> = {
  "Near Mint": 1,
  "Lightly Played": 0.9,
  "Moderately Played": 0.76,
  "Heavily Played": 0.58,
  Damaged: 0.4,
};

const TCGTRACKING_SCAN_MAX_IMAGE_BYTES = 100_000;

