"use client";

import Link from "next/link";
import {
  Boxes,
  CalendarDays,
  Command,
  FolderKanban,
  History,
  Package,
  Search,
  ShoppingBag,
  Sparkles,
  Store,
  X,
} from "lucide-react";
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

type SearchCategory =
  | "Inventory"
  | "Organization"
  | "Commerce"
  | "Actions";

type SearchResult = {
  id: string;
  title: string;
  description: string;
  href: string;
  category: SearchCategory;
  keywords: string[];
  icon: typeof Search;
  badge?: string;
};

type SearchBarProps = {
  className?: string;
  compact?: boolean;
};

const searchResults: SearchResult[] = [
  {
    id: "all-inventory",
    title: "All Inventory",
    description: "Search every card, product, grade, and location.",
    href: "/dashboard/inventory",
    category: "Inventory",
    keywords: [
      "inventory",
      "cards",
      "singles",
      "sealed",
      "graded",
      "bulk",
    ],
    icon: Boxes,
  },
  {
    id: "singles",
    title: "Singles",
    description: "Browse individual cards by set, condition, and printing.",
    href: "/dashboard/inventory?view=singles",
    category: "Inventory",
    keywords: [
      "single",
      "cards",
      "magic",
      "mtg",
      "pokemon",
      "condition",
    ],
    icon: Sparkles,
  },
  {
    id: "sealed",
    title: "Sealed Products",
    description: "Boxes, bundles, packs, cases, and preconstructed decks.",
    href: "/dashboard/inventory?view=sealed",
    category: "Inventory",
    keywords: [
      "sealed",
      "booster",
      "box",
      "bundle",
      "pack",
      "deck",
    ],
    icon: Package,
  },
  {
    id: "graded",
    title: "Graded Cards",
    description: "PSA, BGS, CGC, SGC, and certification tracking.",
    href: "/dashboard/inventory?view=graded",
    category: "Inventory",
    keywords: [
      "graded",
      "psa",
      "bgs",
      "cgc",
      "sgc",
      "slab",
      "certification",
    ],
    icon: Sparkles,
  },
  {
    id: "binders",
    title: "Binders",
    description: "Open binder collections and page-based storage.",
    href: "/dashboard/organization/binders",
    category: "Organization",
    keywords: [
      "binder",
      "pages",
      "collection",
      "storage",
      "organization",
    ],
    icon: FolderKanban,
  },
  {
    id: "locations",
    title: "Storage Locations",
    description: "Find shelves, boxes, bins, vaults, and warehouse spaces.",
    href: "/dashboard/organization/locations",
    category: "Organization",
    keywords: [
      "location",
      "shelf",
      "box",
      "bin",
      "warehouse",
      "vault",
    ],
    icon: Store,
  },
  {
    id: "card-shows",
    title: "Card Shows",
    description: "Plan events, manage show inventory, record sales, and track profit.",
    href: "/dashboard/card-shows",
    category: "Commerce",
    keywords: [
      "card show",
      "event",
      "vendor",
      "booth",
      "table",
      "show inventory",
      "show sales",
    ],
    icon: CalendarDays,
  },
  {
    id: "marketplaces",
    title: "Marketplaces",
    description: "Manage TCGplayer, eBay, Shopify, and Mana Pool.",
    href: "/dashboard/marketplaces",
    category: "Commerce",
    keywords: [
      "marketplace",
      "tcgplayer",
      "ebay",
      "shopify",
      "mana pool",
      "listing",
    ],
    icon: Store,
  },
  {
    id: "orders",
    title: "Orders",
    description: "Review open, fulfilled, shipped, and returned orders.",
    href: "/dashboard/orders",
    category: "Commerce",
    keywords: [
      "order",
      "shipping",
      "fulfilled",
      "pending",
      "return",
      "sale",
    ],
    icon: ShoppingBag,
    badge: "12 open",
  },
  {
    id: "add-card",
    title: "Add a Card",
    description: "Create a new single-card inventory record.",
    href: "/dashboard/inventory/new?type=single",
    category: "Actions",
    keywords: [
      "add",
      "new",
      "create",
      "card",
      "single",
      "inventory",
    ],
    icon: Sparkles,
  },
  {
    id: "create-binder",
    title: "Create a Binder",
    description: "Start a new binder and configure its layout.",
    href: "/dashboard/organization/binders/new",
    category: "Actions",
    keywords: [
      "create",
      "new",
      "binder",
      "pages",
      "collection",
    ],
    icon: FolderKanban,
  },
];

const categoryOrder: SearchCategory[] = [
  "Inventory",
  "Organization",
  "Commerce",
  "Actions",
];

function normalize(value: string) {
  return value.trim().toLowerCase();
}

function matchesResult(result: SearchResult, query: string) {
  const normalizedQuery = normalize(query);

  if (!normalizedQuery) {
    return true;
  }

  const searchableContent = [
    result.title,
    result.description,
    result.category,
    ...result.keywords,
  ]
    .join(" ")
    .toLowerCase();

  return normalizedQuery
    .split(/\s+/)
    .every((term) => searchableContent.includes(term));
}

export function SearchBar({
  className = "",
  compact = false,
}: SearchBarProps) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);

  const inputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const filteredResults = useMemo(
    () =>
      searchResults.filter((result) =>
        matchesResult(result, query),
      ),
    [query],
  );

  const groupedResults = useMemo(
    () =>
      categoryOrder
        .map((category) => ({
          category,
          items: filteredResults.filter(
            (result) => result.category === category,
          ),
        }))
        .filter((group) => group.items.length > 0),
    [filteredResults],
  );

  const flatResults = useMemo(
    () => groupedResults.flatMap((group) => group.items),
    [groupedResults],
  );

  const closeSearch = useCallback(() => {
    setOpen(false);
    setActiveIndex(0);
  }, []);

  useEffect(() => {
    function handleKeyboardShortcut(event: KeyboardEvent) {
      const isShortcut =
        (event.ctrlKey || event.metaKey) &&
        event.key.toLowerCase() === "k";

      if (!isShortcut) {
        return;
      }

      event.preventDefault();
      setOpen(true);

      window.setTimeout(() => {
        inputRef.current?.focus();
      }, 0);
    }

    window.addEventListener("keydown", handleKeyboardShortcut);

    return () => {
      window.removeEventListener(
        "keydown",
        handleKeyboardShortcut,
      );
    };
  }, []);

  useEffect(() => {
    function handlePointerDown(event: MouseEvent) {
      if (
        containerRef.current &&
        !containerRef.current.contains(event.target as Node)
      ) {
        closeSearch();
      }
    }

    document.addEventListener("mousedown", handlePointerDown);

    return () => {
      document.removeEventListener(
        "mousedown",
        handlePointerDown,
      );
    };
  }, [closeSearch]);

  useEffect(() => {
    if (activeIndex >= flatResults.length) {
      setActiveIndex(Math.max(flatResults.length - 1, 0));
    }
  }, [activeIndex, flatResults.length]);

  function handleKeyDown(
    event: React.KeyboardEvent<HTMLInputElement>,
  ) {
    if (!open && event.key !== "Escape") {
      setOpen(true);
    }

    if (event.key === "ArrowDown") {
      event.preventDefault();

      setActiveIndex((current) =>
        flatResults.length === 0
          ? 0
          : (current + 1) % flatResults.length,
      );
    }

    if (event.key === "ArrowUp") {
      event.preventDefault();

      setActiveIndex((current) =>
        flatResults.length === 0
          ? 0
          : (current - 1 + flatResults.length) %
            flatResults.length,
      );
    }

    if (event.key === "Enter") {
      const selectedResult = flatResults[activeIndex];

      if (!selectedResult) {
        return;
      }

      event.preventDefault();
      window.location.href = selectedResult.href;
    }

    if (event.key === "Escape") {
      event.preventDefault();
      closeSearch();
      inputRef.current?.blur();
    }
  }

  function clearQuery() {
    setQuery("");
    setActiveIndex(0);
    inputRef.current?.focus();
  }

  return (
    <div
      ref={containerRef}
      className={`relative w-full ${className}`}
    >
      <div
        className={`group relative flex items-center rounded-xl border transition-all duration-200 ${
          open
            ? "border-cyan-300/30 bg-[#08131a] shadow-[0_0_0_1px_rgba(34,211,238,0.06),0_14px_40px_rgba(0,0,0,0.24),0_0_30px_rgba(34,211,238,0.06)]"
            : "border-white/[0.08] bg-white/[0.025] hover:border-white/[0.13] hover:bg-white/[0.035]"
        } ${
          compact ? "h-9" : "h-10"
        }`}
      >
        <Search
          className={`ml-3 h-4 w-4 shrink-0 transition-colors ${
            open
              ? "text-cyan-300"
              : "text-slate-600 group-hover:text-slate-400"
          }`}
        />

        <input
          ref={inputRef}
          value={query}
          onChange={(event) => {
            setQuery(event.target.value);
            setActiveIndex(0);
          }}
          onFocus={() => setOpen(true)}
          onKeyDown={handleKeyDown}
          placeholder="Search inventory, orders, locations..."
          aria-label="Search Trading Docks"
          aria-expanded={open}
          aria-controls="dashboard-search-results"
          className="h-full min-w-0 flex-1 bg-transparent px-3 text-[11px] text-white outline-none placeholder:text-slate-600"
        />

        {query ? (
          <button
            type="button"
            onClick={clearQuery}
            aria-label="Clear search"
            className="mr-1.5 flex h-7 w-7 items-center justify-center rounded-lg text-slate-600 transition hover:bg-white/[0.05] hover:text-white"
          >
            <X className="h-3.5 w-3.5" />
          </button>
        ) : (
          <div className="mr-2 hidden items-center gap-1 rounded-md border border-white/[0.08] bg-white/[0.035] px-1.5 py-1 text-[8px] font-medium text-slate-600 sm:flex">
            <Command className="h-2.5 w-2.5" />
            K
          </div>
        )}
      </div>

      {open ? (
        <div
          id="dashboard-search-results"
          className="absolute left-0 right-0 top-[calc(100%+10px)] z-[80] overflow-hidden rounded-2xl border border-white/[0.1] bg-[#071017]/98 shadow-[0_28px_90px_rgba(0,0,0,0.58),0_0_45px_rgba(34,211,238,0.08)] backdrop-blur-2xl"
        >
          <div className="border-b border-white/[0.07] px-4 py-3">
            <div className="flex items-center justify-between gap-3">
              <div>
                <p className="text-[10px] font-semibold text-white">
                  Search Trading Docks
                </p>

                <p className="mt-0.5 text-[9px] text-slate-600">
                  Inventory, navigation, orders, and actions
                </p>
              </div>

              <div className="hidden items-center gap-1.5 text-[8px] text-slate-600 sm:flex">
                <span className="rounded border border-white/[0.08] bg-white/[0.03] px-1.5 py-0.5">
                  ↑↓
                </span>
                Navigate
                <span className="ml-1 rounded border border-white/[0.08] bg-white/[0.03] px-1.5 py-0.5">
                  Enter
                </span>
                Open
              </div>
            </div>
          </div>

          <div className="search-results-scrollbar max-h-[440px] overflow-y-auto p-2">
            {!query ? (
              <div className="mb-2 flex items-center gap-2 px-2 py-1 text-[9px] text-slate-600">
                <History className="h-3 w-3" />
                Suggested destinations
              </div>
            ) : null}

            {groupedResults.length > 0 ? (
              <div className="space-y-3">
                {groupedResults.map((group) => (
                  <div key={group.category}>
                    <p className="px-2 pb-1.5 text-[8px] font-semibold uppercase tracking-[0.16em] text-slate-600">
                      {group.category}
                    </p>

                    <div className="space-y-1">
                      {group.items.map((result) => {
                        const currentIndex = flatResults.findIndex(
                          (flatResult) => flatResult.id === result.id,
                        );
                        const active =
                          currentIndex === activeIndex;
                        const Icon = result.icon;

                        return (
                          <Link
                            key={result.id}
                            href={result.href}
                            onMouseEnter={() =>
                              setActiveIndex(currentIndex)
                            }
                            onClick={closeSearch}
                            className={`group flex items-center gap-3 rounded-xl border px-3 py-2.5 transition ${
                              active
                                ? "border-cyan-300/20 bg-cyan-400/[0.07] shadow-[0_0_22px_rgba(34,211,238,0.05)]"
                                : "border-transparent hover:border-white/[0.06] hover:bg-white/[0.03]"
                            }`}
                          >
                            <div
                              className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border transition ${
                                active
                                  ? "border-cyan-300/25 bg-cyan-400/10 text-cyan-300"
                                  : "border-white/[0.07] bg-white/[0.025] text-slate-600 group-hover:text-slate-400"
                              }`}
                            >
                              <Icon className="h-4 w-4" />
                            </div>

                            <div className="min-w-0 flex-1">
                              <div className="flex items-center gap-2">
                                <p
                                  className={`truncate text-[11px] font-medium ${
                                    active
                                      ? "text-cyan-100"
                                      : "text-slate-200"
                                  }`}
                                >
                                  {result.title}
                                </p>

                                {result.badge ? (
                                  <span className="shrink-0 rounded-full border border-cyan-300/15 bg-cyan-400/[0.07] px-2 py-0.5 text-[8px] text-cyan-300">
                                    {result.badge}
                                  </span>
                                ) : null}
                              </div>

                              <p className="mt-0.5 truncate text-[9px] text-slate-600">
                                {result.description}
                              </p>
                            </div>

                            <span
                              className={`text-[9px] transition ${
                                active
                                  ? "translate-x-0 text-cyan-300 opacity-100"
                                  : "-translate-x-1 text-slate-700 opacity-0 group-hover:translate-x-0 group-hover:opacity-100"
                              }`}
                            >
                              Open
                            </span>
                          </Link>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="flex min-h-[190px] flex-col items-center justify-center px-6 text-center">
                <div className="flex h-11 w-11 items-center justify-center rounded-2xl border border-white/[0.08] bg-white/[0.025] text-slate-600">
                  <Search className="h-4 w-4" />
                </div>

                <p className="mt-3 text-[11px] font-medium text-slate-300">
                  No results found
                </p>

                <p className="mt-1 max-w-[270px] text-[9px] leading-4 text-slate-600">
                  Try searching for an inventory category,
                  marketplace, order, binder, or storage location.
                </p>
              </div>
            )}
          </div>

          <div className="flex items-center justify-between border-t border-white/[0.07] px-4 py-2.5">
            <p className="text-[8px] text-slate-600">
              Search will expand to individual cards, SKUs, orders,
              and customers when those records are connected.
            </p>

            <button
              type="button"
              onClick={closeSearch}
              className="ml-4 shrink-0 text-[8px] font-medium text-slate-600 transition hover:text-slate-300"
            >
              Esc to close
            </button>
          </div>
        </div>
      ) : null}

      <style jsx global>{`
        .search-results-scrollbar {
          scrollbar-width: thin;
          scrollbar-color: rgba(148, 163, 184, 0.14)
            transparent;
        }

        .search-results-scrollbar::-webkit-scrollbar {
          width: 6px;
        }

        .search-results-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }

        .search-results-scrollbar::-webkit-scrollbar-thumb {
          border-radius: 999px;
          background: rgba(148, 163, 184, 0.12);
        }

        .search-results-scrollbar::-webkit-scrollbar-thumb:hover {
          background: rgba(34, 211, 238, 0.2);
        }
      `}</style>
    </div>
  );
}

"use client";

import Link from "next/link";
import {
  ArrowRight,
  BadgeCheck,
  Boxes,
  Check,
  CircleDollarSign,
  ContactRound,
  FileSpreadsheet,
  PackageSearch,
  RefreshCw,
  Rocket,
  ShoppingBag,
  Store,
  WandSparkles,
} from "lucide-react";
import { useMemo, useState } from "react";

export type SellerReadinessSnapshot = {
  inventoryItemCount: number;
  inventoryUnitCount: number;
  connectedMarketplaceCount: number;
  connectedMarketplaces: string[];
  orderCount: number;
  customerCount: number;
  completedSyncCount: number;
  workspaceConfigured: boolean;
  generatedAt: string;
};

type LaunchStep = {
  id: string;
  phase: string;
  title: string;
  description: string;
  href: string;
  action: string;
  icon: React.ComponentType<{ className?: string }>;
  required: boolean;
  automatic: boolean;
  complete: boolean;
  evidence: string;
};

export function SellerLaunchCenter({
  snapshot,
}: {
  snapshot: SellerReadinessSnapshot;
}) {
  const [manualComplete, setManualComplete] = useState<string[]>([]);

  const steps = useMemo<LaunchStep[]>(
    () => [
      {
        id: "business-profile",
        phase: "Foundation",
        title: "Confirm your seller workspace",
        description:
          "Review account details, business identity, and workspace preferences.",
        href: "/dashboard/settings",
        action: "Review settings",
        icon: Store,
        required: true,
        automatic: true,
        complete: snapshot.workspaceConfigured,
        evidence: snapshot.workspaceConfigured
          ? "Active workspace detected"
          : "No active workspace detected",
      },
      {
        id: "inventory",
        phase: "Inventory",
        title: "Add or import sellable inventory",
        description:
          "Trading Docks checks your durable inventory records automatically.",
        href: "/dashboard/inventory",
        action: "Open inventory",
        icon: Boxes,
        required: true,
        automatic: true,
        complete: snapshot.inventoryItemCount > 0,
        evidence:
          snapshot.inventoryItemCount > 0
            ? `${snapshot.inventoryItemCount.toLocaleString()} records · ${snapshot.inventoryUnitCount.toLocaleString()} units`
            : "No inventory detected",
      },
      {
        id: "csv",
        phase: "Inventory",
        title: "Validate an inventory import",
        description:
          "Completed sync activity is used as evidence that an import or synchronization workflow has run.",
        href: "/dashboard/tools/csv-converter",
        action: "Open CSV Engine",
        icon: FileSpreadsheet,
        required: false,
        automatic: true,
        complete: snapshot.completedSyncCount > 0,
        evidence:
          snapshot.completedSyncCount > 0
            ? `${snapshot.completedSyncCount.toLocaleString()} completed sync run${snapshot.completedSyncCount === 1 ? "" : "s"}`
            : "No completed sync activity detected",
      },
      {
        id: "marketplace",
        phase: "Connections",
        title: "Connect your first marketplace",
        description:
          "Ready marketplace connections and saved self-service credentials are detected automatically.",
        href: "/dashboard/marketplaces",
        action: "Connect a channel",
        icon: Store,
        required: true,
        automatic: true,
        complete: snapshot.connectedMarketplaceCount > 0,
        evidence:
          snapshot.connectedMarketplaceCount > 0
            ? snapshot.connectedMarketplaces.join(", ")
            : "No ready marketplace connection detected",
      },
      {
        id: "orders",
        phase: "Orders",
        title: "Import and review an order",
        description:
          "The checklist completes when a real order reaches the universal Orders Center.",
        href: "/dashboard/orders",
        action: "Open Orders",
        icon: ShoppingBag,
        required: true,
        automatic: true,
        complete: snapshot.orderCount > 0,
        evidence:
          snapshot.orderCount > 0
            ? `${snapshot.orderCount.toLocaleString()} order${snapshot.orderCount === 1 ? "" : "s"} detected`
            : "No imported orders detected",
      },
      {
        id: "purchasing",
        phase: "Buying",
        title: "Configure purchasing intelligence",
        description:
          "Buying-rule persistence is not yet available as a durable readiness signal.",
        href: "/dashboard/card-photo-scanner",
        action: "Open Purchasing",
        icon: PackageSearch,
        required: false,
        automatic: false,
        complete: manualComplete.includes("purchasing"),
        evidence: manualComplete.includes("purchasing")
          ? "Confirmed manually"
          : "Manual confirmation required",
      },
      {
        id: "crm",
        phase: "Customers",
        title: "Create your first customer",
        description:
          "Customer records in the active workspace are checked automatically.",
        href: "/dashboard/customers",
        action: "Open Customer CRM",
        icon: ContactRound,
        required: false,
        automatic: true,
        complete: snapshot.customerCount > 0,
        evidence:
          snapshot.customerCount > 0
            ? `${snapshot.customerCount.toLocaleString()} customer${snapshot.customerCount === 1 ? "" : "s"} detected`
            : "No CRM customers detected",
      },
      {
        id: "automation",
        phase: "Operations",
        title: "Review seller automation",
        description:
          "Automation preferences do not yet expose a durable completion record.",
        href: "/dashboard/automation",
        action: "Review automation",
        icon: WandSparkles,
        required: false,
        automatic: false,
        complete: manualComplete.includes("automation"),
        evidence: manualComplete.includes("automation")
          ? "Confirmed manually"
          : "Manual confirmation required",
      },
    ],
    [manualComplete, snapshot],
  );

  const required = steps.filter((step) => step.required);
  const requiredComplete = required.filter((step) => step.complete).length;
  const totalComplete = steps.filter((step) => step.complete).length;
  const score = Math.round((totalComplete / steps.length) * 100);
  const ready = requiredComplete === required.length;
  const nextStep = steps.find((step) => !step.complete) ?? null;

  function toggleManual(id: string) {
    setManualComplete((current) =>
      current.includes(id)
        ? current.filter((value) => value !== id)
        : [...current, id],
    );
  }

  return (
    <main className="min-h-screen bg-[#020a12] px-4 py-6 text-white sm:px-6 lg:px-10 lg:py-9">
      <div className="mx-auto max-w-[1500px]">
        <section className="relative overflow-hidden rounded-[30px] border border-blue-300/[0.15] bg-gradient-to-br from-[#0a1c2b] via-[#071522] to-[#04101a] p-5 shadow-[0_34px_120px_rgba(0,0,0,.42)] sm:p-8">
          <div className="pointer-events-none absolute -right-28 -top-28 h-80 w-80 rounded-full bg-blue-500/[0.14] blur-[110px]" />

          <div className="relative grid gap-8 xl:grid-cols-[1fr_390px] xl:items-center">
            <div>
              <div className="inline-flex items-center gap-2 rounded-full border border-cyan-300/[0.18] bg-cyan-300/[0.06] px-3 py-2 text-xs font-semibold text-cyan-200">
                <Rocket className="h-4 w-4" />
                Automatic Seller Readiness
              </div>

              <h1 className="mt-5 max-w-4xl text-3xl font-semibold tracking-[-0.045em] sm:text-5xl">
                Trading Docks now verifies your core seller setup.
              </h1>

              <p className="mt-5 max-w-3xl text-sm leading-7 text-slate-400 sm:text-base sm:leading-8">
                Inventory, marketplace connections, orders, customers, and sync
                activity are checked from your real workspace data instead of
                relying on manual checklist claims.
              </p>

              <div className="mt-7 flex flex-wrap gap-2">
                <StatusPill
                  label={`${requiredComplete}/${required.length} required complete`}
                  good={ready}
                />
                <StatusPill
                  label={`${totalComplete}/${steps.length} total complete`}
                  good={score >= 75}
                />
                <StatusPill
                  label={ready ? "Core seller workflows ready" : "Setup in progress"}
                  good={ready}
                />
              </div>
            </div>

            <div className="rounded-[24px] border border-white/[0.08] bg-black/[0.16] p-5">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-xs font-semibold uppercase tracking-[0.14em] text-slate-600">
                    Verified readiness
                  </p>
                  <p className="mt-2 text-4xl font-bold tracking-[-0.05em] text-white [font-variant-numeric:tabular-nums]">
                    {score}%
                  </p>
                </div>
                <span
                  className={[
                    "flex h-12 w-12 items-center justify-center rounded-2xl border",
                    ready
                      ? "border-emerald-300/[0.18] bg-emerald-300/[0.07] text-emerald-300"
                      : "border-blue-300/[0.16] bg-blue-400/[0.06] text-blue-300",
                  ].join(" ")}
                >
                  {ready ? (
                    <BadgeCheck className="h-5 w-5" />
                  ) : (
                    <RefreshCw className="h-5 w-5" />
                  )}
                </span>
              </div>

              <div className="mt-5 h-2 overflow-hidden rounded-full bg-white/[0.055]">
                <span
                  className="block h-full rounded-full bg-gradient-to-r from-blue-500 to-cyan-300 transition-[width] duration-500"
                  style={{ width: `${score}%` }}
                />
              </div>

              <p className="mt-3 text-[11px] text-slate-600">
                Checked {new Date(snapshot.generatedAt).toLocaleString()}
              </p>

              {nextStep ? (
                <Link
                  href={nextStep.href}
                  className="mt-5 flex items-center justify-between gap-4 rounded-2xl border border-blue-300/[0.12] bg-blue-400/[0.04] px-4 py-3 transition hover:border-cyan-300/[0.22] hover:bg-blue-400/[0.07]"
                >
                  <span>
                    <span className="block text-[10px] font-semibold uppercase tracking-[0.13em] text-slate-600">
                      Best next action
                    </span>
                    <span className="mt-1 block text-sm font-semibold text-white">
                      {nextStep.title}
                    </span>
                  </span>
                  <ArrowRight className="h-4 w-4 shrink-0 text-cyan-300" />
                </Link>
              ) : null}
            </div>
          </div>
        </section>

        <section className="mt-6 grid gap-3 md:grid-cols-2">
          {steps.map((step, index) => {
            const Icon = step.icon;

            return (
              <article
                key={step.id}
                className={[
                  "rounded-[24px] border p-5 transition duration-300",
                  step.complete
                    ? "border-emerald-300/[0.15] bg-emerald-300/[0.035]"
                    : "border-white/[0.075] bg-[#071522]",
                ].join(" ")}
              >
                <div className="flex items-start justify-between gap-4">
                  <span
                    className={[
                      "flex h-11 w-11 items-center justify-center rounded-2xl border",
                      step.complete
                        ? "border-emerald-300/[0.16] bg-emerald-300/[0.06] text-emerald-300"
                        : "border-blue-300/[0.12] bg-blue-400/[0.05] text-blue-300",
                    ].join(" ")}
                  >
                    {step.complete ? (
                      <Check className="h-5 w-5" />
                    ) : (
                      <Icon className="h-5 w-5" />
                    )}
                  </span>

                  <div className="flex flex-wrap justify-end gap-1.5">
                    <span className="rounded-full border border-white/[0.07] px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[0.1em] text-slate-600">
                      {step.required ? "Required" : "Recommended"}
                    </span>
                    <span className="rounded-full border border-blue-300/[0.1] bg-blue-400/[0.03] px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[0.1em] text-blue-200/65">
                      {step.automatic ? "Auto verified" : "Manual"}
                    </span>
                  </div>
                </div>

                <p className="mt-5 text-[10px] font-semibold uppercase tracking-[0.14em] text-cyan-300/75">
                  {String(index + 1).padStart(2, "0")} · {step.phase}
                </p>
                <h2 className="mt-2 text-lg font-semibold tracking-[-0.025em] text-white">
                  {step.title}
                </h2>
                <p className="mt-3 text-sm leading-6 text-slate-500">
                  {step.description}
                </p>

                <div
                  className={[
                    "mt-4 rounded-xl border px-3 py-2.5 text-xs font-medium",
                    step.complete
                      ? "border-emerald-300/[0.11] bg-emerald-300/[0.035] text-emerald-200"
                      : "border-white/[0.06] bg-black/[0.11] text-slate-600",
                  ].join(" ")}
                >
                  {step.evidence}
                </div>

                <div className="mt-5 flex items-center gap-2">
                  <Link
                    href={step.href}
                    className="inline-flex h-10 flex-1 items-center justify-center gap-2 rounded-xl border border-blue-300/[0.13] bg-blue-400/[0.045] px-3 text-xs font-semibold text-blue-100"
                  >
                    {step.action}
                    <ArrowRight className="h-3.5 w-3.5" />
                  </Link>

                  {!step.automatic ? (
                    <button
                      type="button"
                      onClick={() => toggleManual(step.id)}
                      className={[
                        "inline-flex h-10 items-center justify-center rounded-xl px-3 text-xs font-semibold",
                        step.complete
                          ? "bg-emerald-300/[0.09] text-emerald-200"
                          : "border border-white/[0.08] bg-white/[0.025] text-slate-400",
                      ].join(" ")}
                    >
                      {step.complete ? "Confirmed" : "Confirm"}
                    </button>
                  ) : null}
                </div>
              </article>
            );
          })}
        </section>

        <section className="mt-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          <SummaryCard
            label="Inventory units"
            value={snapshot.inventoryUnitCount.toLocaleString()}
            icon={Boxes}
          />
          <SummaryCard
            label="Connected channels"
            value={snapshot.connectedMarketplaceCount.toLocaleString()}
            icon={Store}
          />
          <SummaryCard
            label="Imported orders"
            value={snapshot.orderCount.toLocaleString()}
            icon={ShoppingBag}
          />
          <SummaryCard
            label="CRM customers"
            value={snapshot.customerCount.toLocaleString()}
            icon={ContactRound}
          />
        </section>
      </div>
    </main>
  );
}

function StatusPill({ label, good }: { label: string; good: boolean }) {
  return (
    <span
      className={[
        "inline-flex items-center gap-2 rounded-full border px-3 py-2 text-xs font-semibold",
        good
          ? "border-emerald-300/[0.14] bg-emerald-300/[0.045] text-emerald-200"
          : "border-blue-300/[0.12] bg-blue-400/[0.035] text-blue-200/80",
      ].join(" ")}
    >
      <span className={good ? "h-1.5 w-1.5 rounded-full bg-emerald-300" : "h-1.5 w-1.5 rounded-full bg-blue-300"} />
      {label}
    </span>
  );
}

function SummaryCard({
  label,
  value,
  icon: Icon,
}: {
  label: string;
  value: string;
  icon: React.ComponentType<{ className?: string }>;
}) {
  return (
    <div className="rounded-[22px] border border-white/[0.075] bg-[#071522] p-4">
      <div className="flex items-center justify-between">
        <p className="text-xs font-semibold uppercase tracking-[0.11em] text-slate-600">
          {label}
        </p>
        <Icon className="h-4 w-4 text-blue-300/70" />
      </div>
      <p className="mt-4 text-2xl font-bold tracking-[-0.035em] text-white [font-variant-numeric:tabular-nums]">
        {value}
      </p>
    </div>
  );
}

"use client";

import {
  Bell,
  Boxes,
  Building2,
  Check,
  ChevronRight,
  CircleUserRound,
  Cloud,
  CreditCard,
  Database,
  Download,
  FileSpreadsheet,
  Globe2,
  KeyRound,
  LayoutDashboard,
  Link2,
  LockKeyhole,
  Moon,
  Paintbrush,
  PlugZap,
  Save,
  Search,
  ShieldCheck,
  ShoppingBag,
  Store,
  UsersRound,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { useMemo, useState, useTransition } from "react";

import { saveSettings } from "@/app/actions/settings";
import { RevenueCatBillingManagementButton } from "@/components/billing/RevenueCatBillingManagementButton";
import type { AccountTier } from "@/lib/plan-entitlements";

type SettingsData = Record<string, string | boolean | number>;
type SectionId =
  | "overview"
  | "account"
  | "workspace"
  | "billing"
  | "integrations"
  | "inventory"
  | "csv"
  | "selling"
  | "storage"
  | "notifications"
  | "team"
  | "security"
  | "data"
  | "appearance";

type NavItem = {
  id: SectionId;
  label: string;
  description: string;
  icon: LucideIcon;
  storeOnly?: boolean;
};

const NAV_ITEMS: NavItem[] = [
  { id: "overview", label: "Overview", description: "Workspace health", icon: LayoutDashboard },
  { id: "account", label: "Account", description: "Profile and contact", icon: CircleUserRound },
  { id: "workspace", label: "Workspace", description: "Business identity", icon: Building2 },
  { id: "billing", label: "Billing", description: "Plan and invoices", icon: CreditCard },
  { id: "integrations", label: "Integrations", description: "Connected channels", icon: PlugZap },
  { id: "inventory", label: "Inventory", description: "Card defaults", icon: Boxes },
  { id: "csv", label: "CSV & Imports", description: "Conversion rules", icon: FileSpreadsheet },
  { id: "selling", label: "Selling", description: "Listing defaults", icon: ShoppingBag },
  { id: "storage", label: "Storage", description: "Locations and labels", icon: Database },
  { id: "notifications", label: "Notifications", description: "Alerts and delivery", icon: Bell },
  { id: "team", label: "Team", description: "People and permissions", icon: UsersRound, storeOnly: true },
  { id: "security", label: "Security", description: "Sessions and protection", icon: ShieldCheck },
  { id: "data", label: "Data & Privacy", description: "Backups and deletion", icon: Cloud },
  { id: "appearance", label: "Appearance", description: "Display preferences", icon: Paintbrush },
];

const DEFAULTS: SettingsData = {
  fullName: "",
  phone: "",
  timezone: "America/Phoenix",
  currency: "USD",
  businessName: "",
  website: "",
  storeAddress: "",
  defaultGame: "Magic: The Gathering",
  condition: "Near Mint",
  language: "English",
  finish: "Non-foil",
  priceSource: "TCGplayer Market",
  storageLocation: "Unsorted Inventory",
  duplicateHandling: "Combine quantities",
  lowStock: 1,
  csvInput: "Automatic detection",
  csvOutput: "Trading Docks Universal",
  csvReview: true,
  scryfallVerify: true,
  csvSaveInventory: false,
  marketplace: "TCGplayer",
  pricingRule: "Market price",
  minimumPrice: 1.99,
  handlingTime: "1 business day",
  markListed: true,
  overselling: true,
  salesAlerts: true,
  priceAlerts: true,
  syncAlerts: true,
  taskAlerts: true,
  emailAlerts: true,
  browserAlerts: true,
  theme: "Dark",
  density: "Comfortable",
  cardSize: "Medium",
  largerText: false,
  reducedMotion: false,
};

function isSectionId(value: string): value is SectionId {
  return NAV_ITEMS.some((item) => item.id === value);
}

export function SettingsCenter({
  initialSection,
  initialSettings,
  email,
  plan,
  planName,
  subscription,
}: {
  initialSection: string;
  initialSettings: Record<string, unknown>;
  email: string;
  plan: AccountTier;
  planName: string;
  subscription: {
    status: string;
    billingCycle: string;
    renewalDate: string | null;
    cancelAtPeriodEnd: boolean;
  } | null;
}) {
  const [active, setActive] = useState<SectionId>(
    isSectionId(initialSection) ? initialSection : "overview",
  );
  const [settings, setSettings] = useState<SettingsData>(() => {
    const savedSettings: SettingsData = {};
    for (const [key, value] of Object.entries(initialSettings)) {
      if (
        typeof value === "string" ||
        typeof value === "boolean" ||
        typeof value === "number"
      ) {
        savedSettings[key] = value;
      }
    }
    return { ...DEFAULTS, ...savedSettings };
  });
  const [query, setQuery] = useState("");
  const [saved, setSaved] = useState(false);
  const [error, setError] = useState("");
  const [pending, startTransition] = useTransition();

  const visibleNav = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return NAV_ITEMS;
    return NAV_ITEMS.filter(
      (item) =>
        item.label.toLowerCase().includes(normalized) ||
        item.description.toLowerCase().includes(normalized),
    );
  }, [query]);

  function update(key: string, value: string | boolean | number) {
    setSaved(false);
    setSettings((current) => ({ ...current, [key]: value }));
  }

  function persist() {
    setError("");
    startTransition(async () => {
      try {
        await saveSettings(settings);
        setSaved(true);
        window.setTimeout(() => setSaved(false), 2600);
      } catch (saveError) {
        setError(saveError instanceof Error ? saveError.message : "Settings could not be saved.");
      }
    });
  }

  const activeItem = NAV_ITEMS.find((item) => item.id === active) ?? NAV_ITEMS[0];

  return (
    <div className="mt-4 grid overflow-hidden rounded-[28px] border border-white/[0.08] bg-[#06121a]/95 shadow-[0_28px_90px_rgba(0,0,0,0.28)] sm:mt-7 xl:min-h-[760px] xl:grid-cols-[286px_minmax(0,1fr)]">
      <aside className="border-b border-white/[0.07] bg-[#081822]/90 p-3 sm:p-4 xl:border-b-0 xl:border-r">
        <div className="relative">
          <Search className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-600" />
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Find a setting"
            className="h-11 w-full rounded-xl border border-white/[0.07] bg-black/15 pl-10 pr-3 text-sm text-white outline-none transition placeholder:text-slate-600 focus:border-cyan-300/30"
          />
        </div>
        <div className="relative mt-3 sm:hidden">
          <select
            value={active}
            onChange={(event) => setActive(event.target.value as SectionId)}
            aria-label="Choose a settings section"
            className="h-12 w-full appearance-none rounded-xl border border-cyan-300/[0.16] bg-cyan-300/[0.07] px-4 pr-10 text-sm font-semibold text-white outline-none focus:border-cyan-300/40"
          >
            {visibleNav.map((item) => (
              <option key={item.id} value={item.id} className="bg-[#081822] text-white">
                {item.label} — {item.description}
              </option>
            ))}
          </select>
          <ChevronRight className="pointer-events-none absolute right-4 top-1/2 h-4 w-4 -translate-y-1/2 rotate-90 text-cyan-300" />
          <p className="mt-2 px-1 text-[10px] text-slate-500">
            All settings sections are available from this menu.
          </p>
        </div>
        <nav className="mt-4 hidden grid-cols-3 gap-2 sm:grid lg:grid-cols-4 xl:grid-cols-1">
          {visibleNav.map((item) => {
            const Icon = item.icon;
            const locked = item.storeOnly && plan !== "store";
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => setActive(item.id)}
                className={`group flex min-h-14 items-center gap-2.5 rounded-xl px-3 text-left transition ${
                  active === item.id
                    ? "border border-cyan-300/[0.16] bg-cyan-300/[0.08] text-white"
                    : "border border-transparent text-slate-400 hover:bg-white/[0.035] hover:text-slate-200"
                }`}
              >
                <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${active === item.id ? "bg-cyan-300/10 text-cyan-300" : "bg-white/[0.035] text-slate-500"}`}>
                  <Icon className="h-4 w-4" />
                </span>
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-2 text-xs font-semibold">
                    {item.label}
                    {locked ? <LockKeyhole className="h-3 w-3 text-amber-300" /> : null}
                  </span>
                  <span className="mt-0.5 block truncate text-[9px] text-slate-600 sm:text-[10px]">{item.description}</span>
                </span>
                <ChevronRight className="hidden h-3.5 w-3.5 text-slate-700 xl:block" />
              </button>
            );
          })}
        </nav>
      </aside>

      <main className="min-w-0 p-4 sm:p-7 lg:p-9">
        <div className="flex flex-col gap-4 border-b border-white/[0.07] pb-6 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <div className="text-[10px] font-semibold uppercase tracking-[0.2em] text-cyan-300/80">Settings / {activeItem.label}</div>
            <h2 className="mt-2 text-2xl font-semibold tracking-[-0.03em] text-white">{activeItem.label}</h2>
            <p className="mt-1 text-sm text-slate-500">{activeItem.description}</p>
          </div>
          {active !== "overview" && active !== "billing" && active !== "integrations" && active !== "team" && active !== "data" ? (
            <button
              type="button"
              onClick={persist}
              disabled={pending}
              className="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-cyan-300 px-4 text-xs font-semibold text-[#001018] transition hover:brightness-110 disabled:opacity-60"
            >
              {saved ? <Check className="h-4 w-4" /> : <Save className="h-4 w-4" />}
              {pending ? "Saving…" : saved ? "Saved" : "Save changes"}
            </button>
          ) : null}
        </div>
        {error ? <div className="mt-5 rounded-xl border border-rose-300/20 bg-rose-400/[0.07] px-4 py-3 text-xs text-rose-200">{error}</div> : null}

        <div className="mt-5 sm:mt-7">
          {active === "overview" && <Overview planName={planName} subscription={subscription} onOpen={setActive} />}
          {active === "account" && <AccountSettings settings={settings} email={email} update={update} />}
          {active === "workspace" && <WorkspaceSettings settings={settings} update={update} />}
          {active === "billing" && <BillingSettings planName={planName} subscription={subscription} />}
          {active === "integrations" && <Integrations />}
          {active === "inventory" && <InventorySettings settings={settings} update={update} />}
          {active === "csv" && <CsvSettings settings={settings} update={update} />}
          {active === "selling" && <SellingSettings settings={settings} update={update} />}
          {active === "storage" && <StorageSettings settings={settings} update={update} />}
          {active === "notifications" && <NotificationSettings settings={settings} update={update} />}
          {active === "team" && <TeamSettings locked={plan !== "store"} />}
          {active === "security" && <SecuritySettings />}
          {active === "data" && <DataSettings email={email} />}
          {active === "appearance" && <AppearanceSettings settings={settings} update={update} />}
        </div>
      </main>
    </div>
  );
}

function Overview({ planName, subscription, onOpen }: { planName: string; subscription: { renewalDate: string | null } | null; onOpen: (id: SectionId) => void }) {
  const cards = [
    { label: "Membership", value: planName, detail: subscription?.renewalDate ? `Renews ${subscription.renewalDate}` : "Core access active", icon: CreditCard, color: "cyan", target: "billing" as const },
    { label: "Connections", value: "0 connected", detail: "Connect your selling channels", icon: Link2, color: "violet", target: "integrations" as const },
    { label: "Inventory defaults", value: "Configured", detail: "Review condition and pricing", icon: Boxes, color: "emerald", target: "inventory" as const },
    { label: "Security", value: "Standard", detail: "Add two-step verification", icon: ShieldCheck, color: "amber", target: "security" as const },
  ];
  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
        {cards.map((card) => {
          const Icon = card.icon;
          return (
            <button key={card.label} type="button" onClick={() => onOpen(card.target)} className="rounded-2xl border border-white/[0.07] bg-white/[0.025] p-4 text-left transition hover:-translate-y-0.5 hover:border-cyan-300/[0.18] hover:bg-white/[0.04]">
              <div className="flex items-start justify-between">
                <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-cyan-300/[0.07] text-cyan-300"><Icon className="h-4 w-4" /></span>
                <ChevronRight className="h-4 w-4 text-slate-700" />
              </div>
              <div className="mt-5 text-[10px] font-semibold uppercase tracking-[0.14em] text-slate-600">{card.label}</div>
              <div className="mt-1 text-lg font-semibold text-white">{card.value}</div>
              <div className="mt-1 text-xs text-slate-500">{card.detail}</div>
            </button>
          );
        })}
      </div>
      <Panel title="Finish setting up Trading Docks" description="These steps unlock the most useful seller and store workflows.">
        <div className="grid gap-3 md:grid-cols-3">
          {[
            ["Connect a marketplace", "Keep listing and sync status in one place", "integrations"],
            ["Choose inventory defaults", "Speed up imports and collection intake", "inventory"],
            ["Set CSV conversion rules", "Make every conversion consistent", "csv"],
          ].map(([title, detail, target], index) => (
            <button key={title} type="button" onClick={() => onOpen(target as SectionId)} className="flex gap-3 rounded-xl border border-white/[0.06] bg-black/10 p-4 text-left transition hover:border-cyan-300/20">
              <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-cyan-300/10 text-xs font-semibold text-cyan-300">{index + 1}</span>
              <span><span className="block text-xs font-semibold text-slate-200">{title}</span><span className="mt-1 block text-[11px] leading-5 text-slate-600">{detail}</span></span>
            </button>
          ))}
        </div>
      </Panel>
    </div>
  );
}

function AccountSettings({ settings, email, update }: SettingsProps & { email: string }) {
  return <FormGrid>
    <Field label="Full name"><Input value={settings.fullName as string} onChange={(v) => update("fullName", v)} placeholder="Your name" /></Field>
    <Field label="Email address" hint="Managed by your sign-in provider"><Input value={email} disabled /></Field>
    <Field label="Phone number"><Input value={settings.phone as string} onChange={(v) => update("phone", v)} placeholder="Optional" /></Field>
    <Field label="Time zone"><Select value={settings.timezone as string} onChange={(v) => update("timezone", v)} options={["America/Phoenix", "America/Los_Angeles", "America/Denver", "America/Chicago", "America/New_York"]} /></Field>
    <Field label="Currency"><Select value={settings.currency as string} onChange={(v) => update("currency", v)} options={["USD", "CAD", "EUR", "GBP", "AUD"]} /></Field>
  </FormGrid>;
}

function WorkspaceSettings({ settings, update }: SettingsProps) {
  return <FormGrid>
    <Field label="Business or store name" hint="Used in your Mission Control greeting"><Input value={settings.businessName as string} onChange={(v) => update("businessName", v)} placeholder="Example: Desert Mana Games" /></Field>
    <Field label="Website"><Input value={settings.website as string} onChange={(v) => update("website", v)} placeholder="https://" /></Field>
    <Field label="Store address" wide><Input value={settings.storeAddress as string} onChange={(v) => update("storeAddress", v)} placeholder="Used for invoices and local operations" /></Field>
    <Field label="Business logo" wide><UploadPlaceholder /></Field>
  </FormGrid>;
}

function BillingSettings({ planName, subscription }: { planName: string; subscription: { status: string; billingCycle: string; renewalDate: string | null; cancelAtPeriodEnd: boolean } | null }) {
  return <div className="space-y-5">
    <div className="relative overflow-hidden rounded-2xl border border-cyan-300/[0.15] bg-gradient-to-br from-cyan-300/[0.09] via-[#081a24] to-[#07121a] p-6">
      <div className="absolute -right-12 -top-16 h-48 w-48 rounded-full bg-cyan-400/10 blur-3xl" />
      <div className="relative flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between">
        <div><div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-cyan-300">Current membership</div><h3 className="mt-2 text-3xl font-semibold text-white">{planName}</h3><p className="mt-2 text-sm text-slate-400">{subscription ? `${subscription.status} · ${subscription.billingCycle} billing${subscription.renewalDate ? ` · ${subscription.cancelAtPeriodEnd ? "Ends" : "Renews"} ${subscription.renewalDate}` : ""}` : "No paid subscription is connected."}</p></div>
        {subscription ? <RevenueCatBillingManagementButton /> : <a href="/dashboard/plans" className="inline-flex h-11 items-center justify-center rounded-xl bg-cyan-300 px-5 text-sm font-semibold text-[#001018]">Compare plans</a>}
      </div>
    </div>
    <Panel title="Billing controls" description="Securely managed through RevenueCat.">
      <div className="grid gap-3 sm:grid-cols-3">{["Payment methods", "Invoices & receipts", "Change or cancel plan"].map((item) => <div key={item} className="rounded-xl border border-white/[0.06] bg-black/10 p-4 text-xs font-medium text-slate-300">{item}</div>)}</div>
    </Panel>
  </div>;
}

function Integrations() {
  const connections = [
    ["TCGplayer", "Listings, inventory and sales files", "Seller"],
    ["eBay", "Listings, orders and fulfillment", "Seller"],
    ["Mana Pool", "Inventory and marketplace activity", "Seller"],
    ["Shopify", "Products, inventory and orders", "Store"],
    ["Discord", "Community and tournament alerts", "All plans"],
    ["Scryfall", "Card identity and printing verification", "Connected"],
  ];
  return <div className="grid gap-4 md:grid-cols-2">
    {connections.map(([name, detail, tier]) => <div key={name} className="flex items-center gap-4 rounded-2xl border border-white/[0.07] bg-white/[0.025] p-4">
      <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-white/[0.06] bg-black/15 text-cyan-300"><Globe2 className="h-5 w-5" /></span>
      <span className="min-w-0 flex-1"><span className="flex items-center gap-2 text-sm font-semibold text-white">{name}<span className="rounded-full bg-white/[0.05] px-2 py-0.5 text-[9px] font-medium text-slate-500">{tier}</span></span><span className="mt-1 block text-[11px] text-slate-500">{detail}</span></span>
      <button type="button" className={`rounded-lg px-3 py-2 text-[10px] font-semibold ${tier === "Connected" ? "bg-emerald-300/10 text-emerald-300" : "border border-white/[0.08] text-slate-300 hover:border-cyan-300/25"}`}>{tier === "Connected" ? "Active" : "Connect"}</button>
    </div>)}
  </div>;
}

function InventorySettings({ settings, update }: SettingsProps) {
  return <FormGrid>
    <Field label="Default card game"><Select value={settings.defaultGame as string} onChange={(v) => update("defaultGame", v)} options={["Magic: The Gathering", "Pokémon", "Disney Lorcana", "Yu-Gi-Oh!", "One Piece"]} /></Field>
    <Field label="Preferred price source"><Select value={settings.priceSource as string} onChange={(v) => update("priceSource", v)} options={["TCGplayer Market", "TCGplayer Low", "Scryfall USD", "Card Kingdom"]} /></Field>
    <Field label="Default condition"><Select value={settings.condition as string} onChange={(v) => update("condition", v)} options={["Near Mint", "Lightly Played", "Moderately Played", "Heavily Played", "Damaged"]} /></Field>
    <Field label="Default language"><Select value={settings.language as string} onChange={(v) => update("language", v)} options={["English", "Japanese", "Spanish", "French", "German", "Italian"]} /></Field>
    <Field label="Default finish"><Select value={settings.finish as string} onChange={(v) => update("finish", v)} options={["Non-foil", "Foil", "Etched"]} /></Field>
    <Field label="Default storage location"><Input value={settings.storageLocation as string} onChange={(v) => update("storageLocation", v)} /></Field>
    <Field label="Duplicate handling"><Select value={settings.duplicateHandling as string} onChange={(v) => update("duplicateHandling", v)} options={["Combine quantities", "Keep separate rows", "Ask every time"]} /></Field>
    <Field label="Low-stock threshold"><NumberInput value={settings.lowStock as number} onChange={(v) => update("lowStock", v)} /></Field>
  </FormGrid>;
}

function CsvSettings({ settings, update }: SettingsProps) {
  return <div className="space-y-5"><FormGrid>
    <Field label="Preferred input format"><Select value={settings.csvInput as string} onChange={(v) => update("csvInput", v)} options={["Automatic detection", "ManaBox", "TCGplayer", "Moxfield", "Dragon Shield", "Trading Docks Universal"]} /></Field>
    <Field label="Preferred output format"><Select value={settings.csvOutput as string} onChange={(v) => update("csvOutput", v)} options={["Trading Docks Universal", "TCGplayer", "ManaBox", "Moxfield", "Card Kingdom", "Deckbox"]} /></Field>
  </FormGrid><Panel title="Conversion safeguards" description="Applied to every file processed in the CSV Conversion Engine.">
    <ToggleList items={[
      ["Require manual review before export", "Prevent unresolved rows from becoming marketplace files", "csvReview"],
      ["Verify printings with Scryfall", "Use IDs, set codes and collector numbers to confirm matches", "scryfallVerify"],
      ["Save converted cards to inventory", "Choose or create a storage location after conversion", "csvSaveInventory"],
    ]} settings={settings} update={update} />
  </Panel></div>;
}

function SellingSettings({ settings, update }: SettingsProps) {
  return <div className="space-y-5"><FormGrid>
    <Field label="Default marketplace"><Select value={settings.marketplace as string} onChange={(v) => update("marketplace", v)} options={["TCGplayer", "eBay", "Mana Pool", "Trading Docks", "In-Store"]} /></Field>
    <Field label="Pricing rule"><Select value={settings.pricingRule as string} onChange={(v) => update("pricingRule", v)} options={["Market price", "Lowest listed", "Market minus 5%", "Custom price"]} /></Field>
    <Field label="Minimum listing price"><NumberInput value={settings.minimumPrice as number} step={0.01} onChange={(v) => update("minimumPrice", v)} /></Field>
    <Field label="Handling time"><Select value={settings.handlingTime as string} onChange={(v) => update("handlingTime", v)} options={["Same business day", "1 business day", "2 business days", "3 business days"]} /></Field>
  </FormGrid><Panel title="Listing protection"><ToggleList items={[
    ["Automatically mark exports as listed", "Allocate exported inventory to the selected marketplace", "markListed"],
    ["Overselling protection", "Warn or block listings that exceed available quantity", "overselling"],
  ]} settings={settings} update={update} /></Panel></div>;
}

function StorageSettings({ settings, update }: SettingsProps) {
  return <div className="space-y-5">
    <Panel title="Default intake location" description="New cards will begin here unless you choose another location."><Field label="Location"><Input value={settings.storageLocation as string} onChange={(v) => update("storageLocation", v)} /></Field></Panel>
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{["Bulk Box 001", "Trade Binder", "Unsorted Inventory"].map((name, index) => <div key={name} className="rounded-2xl border border-white/[0.07] bg-white/[0.025] p-4"><div className="flex items-center justify-between"><Database className="h-4 w-4 text-cyan-300" /><span className="text-[9px] uppercase tracking-[0.15em] text-slate-600">{index === 2 ? "Default" : "Active"}</span></div><div className="mt-4 text-sm font-semibold text-white">{name}</div><div className="mt-1 text-[11px] text-slate-500">Ready for inventory</div></div>)}</div>
    <button type="button" className="inline-flex h-10 items-center gap-2 rounded-xl border border-cyan-300/20 bg-cyan-300/[0.05] px-4 text-xs font-semibold text-cyan-200">+ Create storage location</button>
  </div>;
}

function NotificationSettings({ settings, update }: SettingsProps) {
  return <div className="space-y-5"><Panel title="Alert types"><ToggleList items={[
    ["Sales and order alerts", "New orders, cancellations and fulfillment updates", "salesAlerts"],
    ["Price-change alerts", "Meaningful movement on watched inventory", "priceAlerts"],
    ["Failed synchronization alerts", "Marketplace or import actions that need attention", "syncAlerts"],
    ["Task and tournament reminders", "Upcoming work and event notifications", "taskAlerts"],
  ]} settings={settings} update={update} /></Panel><Panel title="Delivery channels"><ToggleList items={[
    ["Email", "Send important alerts to your account email", "emailAlerts"],
    ["Browser and in-app", "Show notifications while using Trading Docks", "browserAlerts"],
  ]} settings={settings} update={update} /></Panel></div>;
}

function TeamSettings({ locked }: { locked: boolean }) {
  if (locked) return <LockedFeature title="Team management is included with Store" detail="Invite employees, assign operational roles, protect financial information, and review team activity." />;
  return <div className="space-y-5"><Panel title="Team members" description="Invite people and control what each role can access."><div className="flex items-center justify-between rounded-xl border border-white/[0.06] bg-black/10 p-4"><div><div className="text-sm font-semibold text-white">You</div><div className="mt-1 text-[11px] text-slate-500">Owner · Full access</div></div><span className="rounded-full bg-cyan-300/10 px-3 py-1 text-[10px] font-semibold text-cyan-300">Owner</span></div></Panel><button type="button" className="inline-flex h-10 items-center rounded-xl bg-cyan-300 px-4 text-xs font-semibold text-[#001018]">Invite team member</button></div>;
}

function SecuritySettings() {
  return <div className="space-y-4">{[
    ["Two-factor authentication", "Add an extra verification step when signing in", "Set up"],
    ["Active sessions", "Review devices currently signed into this account", "Review"],
    ["Password", "Update your password through your sign-in provider", "Change"],
    ["Connected applications", "Review services that can access Trading Docks", "Review"],
  ].map(([title, detail, action]) => <div key={title} className="flex flex-col gap-4 rounded-2xl border border-white/[0.07] bg-white/[0.025] p-5 sm:flex-row sm:items-center"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-emerald-300/[0.07] text-emerald-300"><KeyRound className="h-4 w-4" /></span><span className="flex-1"><span className="block text-sm font-semibold text-white">{title}</span><span className="mt-1 block text-[11px] text-slate-500">{detail}</span></span><button type="button" className="h-9 rounded-lg border border-white/[0.08] px-3 text-[10px] font-semibold text-slate-300">{action}</button></div>)}</div>;
}

function DataSettings({ email }: { email: string }) {
  const deletionRequestHref = accountDeletionRequestHref(email);

  return (
    <div className="space-y-5">
      <Panel title="Your data" description="Download a portable copy or create a safety backup.">
        <div className="grid gap-3 sm:grid-cols-2">
          <ActionCard
            icon={Download}
            title="Export account data"
            detail="Support can prepare an account export during beta."
            status="Support-assisted"
          />
          <ActionCard
            icon={FileSpreadsheet}
            title="Download inventory backup"
            detail="Use CSV Conversion for inventory files while full export is prepared."
            status="Use CSV tools"
            href="/dashboard/tools/csv-converter"
          />
        </div>
      </Panel>
      <div className="rounded-2xl border border-rose-300/[0.14] bg-rose-400/[0.035] p-5">
        <div className="text-sm font-semibold text-rose-200">Danger zone</div>
        <p className="mt-2 max-w-2xl text-xs leading-5 text-slate-500">
          Account deletion is support-assisted during beta so identity, workspace ownership, billing, and legally
          retained records can be reviewed before removal.
        </p>
        <a
          href={deletionRequestHref}
          className="mt-4 inline-flex h-9 items-center rounded-lg border border-rose-300/20 px-3 text-[10px] font-semibold text-rose-200 transition hover:border-rose-300/35 hover:bg-rose-300/[0.06]"
        >
          Request account deletion
        </a>
      </div>
    </div>
  );
}

function accountDeletionRequestHref(email: string) {
  const subject = encodeURIComponent("Trading Docks account deletion request");
  const body = encodeURIComponent(`Please help me delete my Trading Docks account.\n\nAccount email: ${email}`);
  return `mailto:tradingdocks@gmail.com?subject=${subject}&body=${body}`;
}

function AppearanceSettings({ settings, update }: SettingsProps) {
  return <FormGrid>
    <Field label="Theme"><Select value={settings.theme as string} onChange={(v) => update("theme", v)} options={["Dark", "Light", "System"]} /></Field>
    <Field label="Layout density"><Select value={settings.density as string} onChange={(v) => update("density", v)} options={["Comfortable", "Compact"]} /></Field>
    <Field label="Card grid size"><Select value={settings.cardSize as string} onChange={(v) => update("cardSize", v)} options={["Small", "Medium", "Large"]} /></Field>
    <Field label="Accessibility" wide><div className="space-y-3"><InlineToggle label="Larger interface text" checked={settings.largerText as boolean} onChange={(v) => update("largerText", v)} /><InlineToggle label="Reduce interface motion" checked={settings.reducedMotion as boolean} onChange={(v) => update("reducedMotion", v)} /></div></Field>
  </FormGrid>;
}

type SettingsProps = { settings: SettingsData; update: (key: string, value: string | boolean | number) => void };

function Panel({ title, description, children }: { title: string; description?: string; children: React.ReactNode }) {
  return <section className="rounded-2xl border border-white/[0.07] bg-white/[0.025] p-5"><div className="mb-5"><h3 className="text-sm font-semibold text-white">{title}</h3>{description ? <p className="mt-1 text-[11px] leading-5 text-slate-500">{description}</p> : null}</div>{children}</section>;
}
function FormGrid({ children }: { children: React.ReactNode }) { return <div className="grid gap-5 md:grid-cols-2">{children}</div>; }
function Field({ label, hint, wide, children }: { label: string; hint?: string; wide?: boolean; children: React.ReactNode }) { return <label className={wide ? "md:col-span-2" : ""}><span className="mb-2 flex items-center justify-between text-[11px] font-semibold text-slate-300"><span>{label}</span>{hint ? <span className="font-normal text-slate-600">{hint}</span> : null}</span>{children}</label>; }
function Input({ value, onChange, placeholder, disabled }: { value: string; onChange?: (value: string) => void; placeholder?: string; disabled?: boolean }) { return <input value={value} onChange={(e) => onChange?.(e.target.value)} placeholder={placeholder} disabled={disabled} className="h-11 w-full rounded-xl border border-white/[0.08] bg-black/15 px-3.5 text-sm text-white outline-none transition placeholder:text-slate-700 focus:border-cyan-300/30 disabled:cursor-not-allowed disabled:text-slate-600" />; }
function NumberInput({ value, onChange, step = 1 }: { value: number; onChange: (value: number) => void; step?: number }) { return <input type="number" min="0" step={step} value={value} onChange={(e) => onChange(Number(e.target.value))} className="h-11 w-full rounded-xl border border-white/[0.08] bg-black/15 px-3.5 text-sm text-white outline-none focus:border-cyan-300/30" />; }
function Select({ value, onChange, options }: { value: string; onChange: (value: string) => void; options: string[] }) { return <select value={value} onChange={(e) => onChange(e.target.value)} className="h-11 w-full rounded-xl border border-white/[0.08] bg-[#071821] px-3.5 text-sm text-white outline-none focus:border-cyan-300/30">{options.map((option) => <option key={option}>{option}</option>)}</select>; }
function InlineToggle({ label, checked, onChange }: { label: string; checked: boolean; onChange: (checked: boolean) => void }) { return <button type="button" onClick={() => onChange(!checked)} className="flex w-full items-center justify-between rounded-xl border border-white/[0.07] bg-black/10 px-4 py-3 text-left text-xs text-slate-300"><span>{label}</span><span className={`relative h-6 w-11 rounded-full transition ${checked ? "bg-cyan-300" : "bg-slate-800"}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-white transition ${checked ? "left-6" : "left-1"}`} /></span></button>; }
function ToggleList({ items, settings, update }: { items: string[][] } & SettingsProps) { return <div className="divide-y divide-white/[0.06]">{items.map(([title, detail, key]) => <div key={key} className="flex items-center gap-4 py-4 first:pt-0 last:pb-0"><span className="min-w-0 flex-1"><span className="block text-xs font-semibold text-slate-200">{title}</span><span className="mt-1 block text-[11px] leading-5 text-slate-600">{detail}</span></span><InlineToggle label="" checked={settings[key] as boolean} onChange={(v) => update(key, v)} /></div>)}</div>; }
function UploadPlaceholder() { return <button type="button" className="flex w-full items-center gap-3 rounded-xl border border-dashed border-white/[0.12] bg-black/10 p-4 text-left"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-white/[0.04] text-slate-500"><Store className="h-4 w-4" /></span><span><span className="block text-xs font-semibold text-slate-300">Upload your logo</span><span className="mt-1 block text-[10px] text-slate-600">PNG, JPG or WebP · Recommended 512 × 512</span></span></button>; }
function LockedFeature({ title, detail }: { title: string; detail: string }) { return <div className="flex min-h-80 flex-col items-center justify-center rounded-2xl border border-amber-300/[0.13] bg-amber-300/[0.025] p-8 text-center"><span className="flex h-14 w-14 items-center justify-center rounded-2xl bg-amber-300/[0.08] text-amber-300"><LockKeyhole className="h-6 w-6" /></span><h3 className="mt-5 text-lg font-semibold text-white">{title}</h3><p className="mt-2 max-w-md text-sm leading-6 text-slate-500">{detail}</p><a href="/dashboard/plans" className="mt-6 inline-flex h-10 items-center rounded-xl bg-amber-300 px-4 text-xs font-semibold text-[#171100]">View Store plan</a></div>; }
function ActionCard({
  icon: Icon,
  title,
  detail,
  status,
  href,
}: {
  icon: LucideIcon;
  title: string;
  detail: string;
  status?: string;
  href?: string;
}) {
  const content = (
    <>
      <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-cyan-300/[0.07] text-cyan-300">
        <Icon className="h-4 w-4" />
      </span>
      <span className="min-w-0 flex-1">
        <span className="block text-xs font-semibold text-slate-200">{title}</span>
        <span className="mt-1 block text-[10px] leading-4 text-slate-600">{detail}</span>
      </span>
      {status ? (
        <span className="rounded-full border border-white/[0.08] bg-white/[0.035] px-2 py-1 text-[9px] font-semibold text-slate-400">
          {status}
        </span>
      ) : null}
    </>
  );
  const className = "flex items-center gap-3 rounded-xl border border-white/[0.06] bg-black/10 p-4 text-left";

  return href ? (
    <a href={href} className={`${className} transition hover:border-cyan-300/20 hover:bg-cyan-300/[0.035]`}>
      {content}
    </a>
  ) : (
    <div className={className}>{content}</div>
  );
}

"use client";

import Image from "next/image";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useMemo, useState } from "react";
import {
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  ExternalLink,
  LogOut,
  MoreHorizontal,
  Settings2,
  ShieldCheck,
  X,
} from "lucide-react";

import { logout } from "@/app/actions/auth";

import {
  CRM_NAV,
  INSIGHTS_NAV,
  OPERATIONS_NAV,
  PRIMARY_NAV,
  PURCHASING_NAV,
  SECONDARY_NAV,
  SELLING_NAV,
  TOOLS_NAV,
  type NavigationSection,
} from "../navigation";

type SidebarProps = {
  accountType: string;
  inventoryModules: string[];
  userName: string;
  isOwner: boolean;
  collapsed: boolean;
  mobileOpen: boolean;
  onCloseMobile: () => void;
  onToggle: () => void;
};

type OpenSection = "purchasing" | "selling" | "insights" | "operations" | null;

const PRIORITY_LIMIT = 4;

export function Sidebar({
  accountType,
  inventoryModules,
  userName,
  isOwner,
  collapsed,
  mobileOpen,
  onCloseMobile,
  onToggle,
}: SidebarProps) {
  const pathname = usePathname();
  const isCollector = accountType === "collector";

  const coreItems = useMemo(
    () =>
      PRIMARY_NAV.filter(
        (item) =>
          item.href !== "/dashboard/inventory" ||
          inventoryModules.some((module) =>
            ["singles", "sealed", "graded", "binders", "bulk"].includes(module),
          ),
      ),
    [inventoryModules],
  );

  const detectedSection = useMemo<OpenSection>(() => {
    const sections = [PURCHASING_NAV, SELLING_NAV, INSIGHTS_NAV, OPERATIONS_NAV];
    return (
      sections.find(
        (section) =>
          pathname === section.href ||
          section.children.some(
            (child) => pathname === child.href || pathname.startsWith(`${child.href}/`),
          ),
      )?.id as OpenSection
    ) ?? null;
  }, [pathname]);

  const [openSection, setOpenSection] = useState<OpenSection>(detectedSection);

  useEffect(() => {
    if (detectedSection) setOpenSection(detectedSection);
  }, [detectedSection]);

  const initials = userName
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase() || "TD";

  return (
    <>
      {mobileOpen ? (
        <button
          type="button"
          aria-label="Close sidebar"
          onClick={onCloseMobile}
          className="fixed inset-0 z-40 bg-black/70 backdrop-blur-sm lg:hidden"
        />
      ) : null}

      <aside
        className={[
          "fixed inset-y-0 left-0 z-50 flex flex-col overflow-hidden border-r border-white/[0.055] bg-[#020a12]/98 shadow-[24px_0_80px_rgba(0,0,0,.24)] backdrop-blur-2xl transition-[width,transform] duration-300",
          collapsed ? "w-[76px]" : "w-[256px]",
          mobileOpen ? "translate-x-0" : "-translate-x-full lg:translate-x-0",
        ].join(" ")}
      >
        <div className="pointer-events-none absolute inset-0">
          <div className="absolute -left-24 -top-24 h-72 w-72 rounded-full bg-blue-400/[.05] blur-[120px]" />
          <div className="absolute inset-y-0 right-0 w-px bg-gradient-to-b from-transparent via-blue-300/[.12] to-transparent" />
        </div>

        <SidebarBrand collapsed={collapsed} onNavigate={onCloseMobile} />

        <nav className="relative flex-1 overflow-y-auto px-3 pb-5 pt-4 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
          <NavLabel label="Core" collapsed={collapsed} />
          <div className="space-y-1">
            {coreItems.map((item) => (
              <PrimaryLink
                key={item.href}
                item={item}
                pathname={pathname}
                collapsed={collapsed}
                onNavigate={onCloseMobile}
              />
            ))}
          </div>

          {!isCollector ? (
            <>
              <NavLabel label="Commerce" collapsed={collapsed} spaced />
              <div className="space-y-1">
                <SectionNav
                  section={PURCHASING_NAV}
                  pathname={pathname}
                  collapsed={collapsed}
                  open={openSection === "purchasing"}
                  onToggle={() => setOpenSection(openSection === "purchasing" ? null : "purchasing")}
                  onNavigate={onCloseMobile}
                  priorityHrefs={[
                    "/dashboard/purchasing-intelligence",
                    "/dashboard/collection-buying",
                    "/dashboard/buying-rules",
                    "/dashboard/buylist-intelligence",
                  ]}
                />
                <SectionNav
                  section={SELLING_NAV}
                  pathname={pathname}
                  collapsed={collapsed}
                  open={openSection === "selling"}
                  onToggle={() => setOpenSection(openSection === "selling" ? null : "selling")}
                  onNavigate={onCloseMobile}
                />
                {CRM_NAV.map((item) => (
                  <PrimaryLink
                    key={item.href}
                    item={item}
                    pathname={pathname}
                    collapsed={collapsed}
                    onNavigate={onCloseMobile}
                  />
                ))}
              </div>

              <NavLabel label="Intelligence" collapsed={collapsed} spaced />
              <SectionNav
                section={INSIGHTS_NAV}
                pathname={pathname}
                collapsed={collapsed}
                open={openSection === "insights"}
                onToggle={() => setOpenSection(openSection === "insights" ? null : "insights")}
                onNavigate={onCloseMobile}
              />

              <NavLabel label="Operations" collapsed={collapsed} spaced />
              <SectionNav
                section={OPERATIONS_NAV}
                pathname={pathname}
                collapsed={collapsed}
                open={openSection === "operations"}
                onToggle={() => setOpenSection(openSection === "operations" ? null : "operations")}
                onNavigate={onCloseMobile}
                priorityHrefs={[
                  "/dashboard/tasks",
                  "/dashboard/calendar",
                  "/dashboard/vendors",
                  "/dashboard/employees",
                ]}
              />
            </>
          ) : null}

          {isCollector && inventoryModules.includes("bulk") ? (
            <>
              <NavLabel label="Purchasing" collapsed={collapsed} spaced />
              <SectionNav
                section={{
                  ...PURCHASING_NAV,
                  children: PURCHASING_NAV.children.filter(
                    (item) => item.href === "/dashboard/bulk-buying",
                  ),
                }}
                pathname={pathname}
                collapsed={collapsed}
                open={openSection === "purchasing"}
                onToggle={() => setOpenSection(openSection === "purchasing" ? null : "purchasing")}
                onNavigate={onCloseMobile}
              />
            </>
          ) : null}

          <NavLabel label="Workspace" collapsed={collapsed} spaced />
          <div className="space-y-1">
            {TOOLS_NAV.map((item) => (
              <PrimaryLink
                key={item.href}
                item={item}
                pathname={pathname}
                collapsed={collapsed}
                onNavigate={onCloseMobile}
                quiet
              />
            ))}
            {SECONDARY_NAV.map((item) => (
              <PrimaryLink
                key={item.href}
                item={item}
                pathname={pathname}
                collapsed={collapsed}
                onNavigate={onCloseMobile}
                quiet
              />
            ))}
          </div>
        </nav>

        <AccountFooter
          accountType={accountType}
          userName={userName}
          initials={initials}
          isOwner={isOwner}
          collapsed={collapsed}
          pathname={pathname}
          onNavigate={onCloseMobile}
          onToggle={onToggle}
        />
      </aside>
    </>
  );
}

function SidebarBrand({
  collapsed,
  onNavigate,
}: {
  collapsed: boolean;
  onNavigate: () => void;
}) {
  return (
    <div className="relative flex h-[72px] items-center border-b border-white/[.055] px-3">
      <Link
        href="/dashboard"
        onClick={onNavigate}
        className={[
          "group flex min-w-0 flex-1 items-center rounded-2xl transition hover:bg-white/[.025]",
          collapsed ? "justify-center px-0 py-1" : "gap-3 px-1.5 py-1",
        ].join(" ")}
      >
        <span className="relative flex h-11 w-11 shrink-0 items-center justify-center">
          <span className="absolute inset-1 rounded-2xl bg-blue-400/[.1] blur-xl transition group-hover:bg-blue-300/[.18]" />
          <Image
            src="/trading-docks-mark.png"
            alt="Trading Docks"
            width={88}
            height={88}
            priority
            sizes="44px"
            className="relative h-11 w-11 object-contain transition duration-300 group-hover:-translate-y-0.5"
          />
        </span>
        {!collapsed ? (
          <span className="min-w-0">
            <span className="block truncate text-sm font-semibold tracking-[-.025em] text-white">
              Trading Docks
            </span>
            <span className="mt-0.5 block text-[10px] font-medium uppercase tracking-[.2em] text-slate-600">
              Collectibles OS
            </span>
          </span>
        ) : null}
      </Link>
      <button
        type="button"
        onClick={onNavigate}
        aria-label="Close sidebar"
        className="flex h-9 w-9 items-center justify-center rounded-xl border border-white/[.07] bg-white/[.025] text-slate-500 lg:hidden"
      >
        <X className="h-4 w-4" />
      </button>
    </div>
  );
}

function NavLabel({
  label,
  collapsed,
  spaced = false,
}: {
  label: string;
  collapsed: boolean;
  spaced?: boolean;
}) {
  if (collapsed) {
    return spaced ? <div className="my-3 h-px bg-white/[.055]" /> : null;
  }
  return (
    <p
      className={[
        "px-3 text-[11px] font-semibold uppercase tracking-[.17em] text-slate-700",
        spaced ? "mb-2 mt-5" : "mb-2",
      ].join(" ")}
    >
      {label}
    </p>
  );
}

function PrimaryLink({
  item,
  pathname,
  collapsed,
  onNavigate,
  quiet = false,
}: {
  item: {
    href: string;
    label: string;
    icon: React.ComponentType<{ className?: string }>;
  };
  pathname: string;
  collapsed: boolean;
  onNavigate: () => void;
  quiet?: boolean;
}) {
  const active =
    item.href === "/dashboard"
      ? pathname === item.href
      : pathname === item.href || pathname.startsWith(`${item.href}/`);
  const Icon = item.icon;

  return (
    <Link
      href={item.href}
      onClick={onNavigate}
      title={collapsed ? item.label : undefined}
      className={[
        "group relative flex h-10 items-center rounded-[10px] transition duration-200",
        collapsed ? "justify-center" : "gap-3 px-3",
        active
          ? "bg-gradient-to-r from-blue-400/[.13] to-blue-300/[.055] text-white shadow-[inset_0_0_0_1px_rgba(125,211,252,.13)]"
          : quiet
            ? "text-slate-500 hover:bg-white/[.025] hover:text-slate-200"
            : "text-slate-400 hover:bg-white/[.035] hover:text-white",
      ].join(" ")}
    >
      {active ? (
        <span className="absolute inset-y-2 left-0 w-[2px] rounded-r-full bg-cyan-300 shadow-[0_0_12px_rgba(103,232,249,.8)]" />
      ) : null}
      <Icon
        className={[
          "h-[18px] w-[18px] shrink-0 transition",
          active ? "text-cyan-300" : "text-blue-300/65 group-hover:text-blue-300",
        ].join(" ")}
      />
      {!collapsed ? (
        <span className={active ? "text-sm font-semibold" : "text-sm font-medium"}>
          {item.label}
        </span>
      ) : null}
    </Link>
  );
}

function SectionNav({
  section,
  pathname,
  collapsed,
  open,
  onToggle,
  onNavigate,
  priorityHrefs,
}: {
  section: NavigationSection;
  pathname: string;
  collapsed: boolean;
  open: boolean;
  onToggle: () => void;
  onNavigate: () => void;
  priorityHrefs?: string[];
}) {
  const active =
    pathname === section.href ||
    section.children.some(
      (child) => pathname === child.href || pathname.startsWith(`${child.href}/`),
    );
  const Icon = section.icon;

  if (collapsed) {
    return (
      <Link
        href={section.href ?? section.children[0]?.href ?? "/dashboard"}
        title={section.label}
        className={[
          "group relative flex h-10 items-center justify-center rounded-[10px] transition",
          active
            ? "bg-blue-400/[.11] text-white shadow-[inset_0_0_0_1px_rgba(125,211,252,.13)]"
            : "text-slate-500 hover:bg-white/[.035]",
        ].join(" ")}
      >
        {active ? (
          <span className="absolute inset-y-2 left-0 w-[2px] rounded-r-full bg-cyan-300" />
        ) : null}
        <Icon className={active ? "h-[18px] w-[18px] text-cyan-300" : "h-[18px] w-[18px] text-blue-300/65"} />
      </Link>
    );
  }

  const priorityChildren = priorityHrefs
    ? priorityHrefs
        .map((href) => section.children.find((child) => child.href === href))
        .filter((item): item is (typeof section.children)[number] => Boolean(item))
    : section.children.slice(0, PRIORITY_LIMIT);

  const activeChild = section.children.find(
    (child) => pathname === child.href || pathname.startsWith(`${child.href}/`),
  );
  const visibleChildren =
    activeChild && !priorityChildren.some((item) => item.href === activeChild.href)
      ? [...priorityChildren.slice(0, PRIORITY_LIMIT - 1), activeChild]
      : priorityChildren;
  const hasMore = section.children.length > visibleChildren.length;

  return (
    <div className="space-y-1">
      <div
        className={[
          "group flex h-10 items-center rounded-[10px] transition",
          active ? "bg-white/[.035]" : "hover:bg-white/[.025]",
        ].join(" ")}
      >
        <Link
          href={section.href ?? section.children[0]?.href ?? "/dashboard"}
          onClick={onNavigate}
          className="flex min-w-0 flex-1 items-center gap-3 px-3"
        >
          <Icon className={active ? "h-[18px] w-[18px] text-cyan-300" : "h-[18px] w-[18px] text-blue-300/65 group-hover:text-blue-300"} />
          <span className={active ? "text-sm font-semibold text-white" : "text-sm font-medium text-slate-400 group-hover:text-white"}>
            {section.label}
          </span>
        </Link>
        <button
          type="button"
          onClick={onToggle}
          aria-label={`${open ? "Collapse" : "Expand"} ${section.label}`}
          aria-expanded={open}
          className="mr-1 flex h-8 w-8 items-center justify-center rounded-lg text-slate-600 transition hover:bg-white/[.045] hover:text-blue-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-400/60"
        >
          <ChevronDown className={["h-4 w-4 transition-transform duration-200", open ? "rotate-180" : ""].join(" ")} />
        </button>
      </div>

      {open ? (
        <div className="ml-[21px] border-l border-blue-300/[.11] pl-3">
          <div className="space-y-0.5 py-1">
            {visibleChildren.map((item) => {
              const childActive =
                pathname === item.href || pathname.startsWith(`${item.href}/`);
              const ChildIcon = item.icon;
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  onClick={onNavigate}
                  className={[
                    "group relative flex min-h-9 items-center gap-2.5 rounded-lg px-2.5 py-2 transition",
                    childActive
                      ? "bg-blue-400/[.1] text-white"
                      : "text-slate-500 hover:bg-white/[.03] hover:text-slate-200",
                  ].join(" ")}
                >
                  <ChildIcon className={childActive ? "h-4 w-4 shrink-0 text-cyan-300" : "h-4 w-4 shrink-0 text-blue-300/55 group-hover:text-blue-300"} />
                  <span className={childActive ? "text-[13px] font-semibold" : "text-[13px] font-normal"}>
                    {item.label}
                  </span>
                </Link>
              );
            })}
            {hasMore ? (
              <Link
                href={section.href ?? section.children[0]?.href ?? "/dashboard"}
                onClick={onNavigate}
                className="group flex min-h-9 items-center gap-2.5 rounded-lg px-2.5 py-2 text-slate-600 transition hover:bg-white/[.03] hover:text-slate-300"
              >
                <MoreHorizontal className="h-4 w-4 text-blue-300/45 group-hover:text-blue-300" />
                <span className="text-[13px] font-medium">View all {section.label.toLowerCase()}</span>
                <ExternalLink className="ml-auto h-3.5 w-3.5 opacity-50" />
              </Link>
            ) : null}
          </div>
        </div>
      ) : null}
    </div>
  );
}

function AccountFooter({
  accountType,
  userName,
  initials,
  isOwner,
  collapsed,
  pathname,
  onNavigate,
  onToggle,
}: {
  accountType: string;
  userName: string;
  initials: string;
  isOwner: boolean;
  collapsed: boolean;
  pathname: string;
  onNavigate: () => void;
  onToggle: () => void;
}) {
  const workspaceLabel = `${accountType.replace("-", " ")} workspace`;
  const adminActive = pathname.startsWith("/dashboard/admin");

  if (collapsed) {
    return (
      <div className="relative border-t border-white/[.055] p-3">
        <div className="flex flex-col items-center gap-2">
          <Link
            href="/dashboard/settings"
            title={`${userName} · ${workspaceLabel}`}
            className="flex h-11 w-11 items-center justify-center rounded-[13px] border border-blue-300/[.17] bg-blue-400/[.07] text-xs font-semibold text-blue-200"
          >
            {initials}
          </Link>
          <button
            type="button"
            onClick={onToggle}
            title="Expand sidebar"
            className="flex h-9 w-9 items-center justify-center rounded-[10px] text-slate-600 transition hover:bg-white/[.035] hover:text-blue-300"
          >
            <ChevronRight className="h-4 w-4" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="relative border-t border-white/[.055] p-3">
      <div className="rounded-[16px] border border-white/[.075] bg-white/[.02] p-2.5 shadow-[0_14px_35px_rgba(0,0,0,.16)]">
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-blue-300/[.18] bg-blue-400/[.08] text-xs font-semibold text-blue-200">
            {initials}
          </div>
          <div className="min-w-0 flex-1">
            <p className="truncate text-[13px] font-semibold capitalize text-slate-100">{userName}</p>
            <p className="mt-0.5 truncate text-[11px] capitalize text-slate-600">{workspaceLabel}</p>
          </div>
          {isOwner ? (
            <span className="rounded-full border border-amber-300/[.13] bg-amber-300/[.055] px-2 py-1 text-[10px] font-bold uppercase tracking-[.1em] text-amber-200/80">
              Owner
            </span>
          ) : null}
        </div>

        <div className="mt-2.5 grid grid-cols-4 gap-1.5 border-t border-white/[.055] pt-2.5">
          {isOwner ? (
            <Link
              href="/dashboard/admin"
              onClick={onNavigate}
              title="Admin Control Center"
              className={[
                "flex h-9 items-center justify-center rounded-[9px] transition",
                adminActive
                  ? "bg-amber-300/[.08] text-amber-200"
                  : "text-slate-600 hover:bg-white/[.035] hover:text-amber-200",
              ].join(" ")}
            >
              <ShieldCheck className="h-4 w-4" />
            </Link>
          ) : (
            <span />
          )}
          <Link
            href="/dashboard/settings"
            onClick={onNavigate}
            title="Workspace settings"
            className="flex h-9 items-center justify-center rounded-[9px] text-slate-600 transition hover:bg-white/[.035] hover:text-blue-300"
          >
            <Settings2 className="h-4 w-4" />
          </Link>
          <form action={logout}>
            <button
              type="submit"
              title="Sign out"
              aria-label="Sign out"
              className="flex h-9 w-full items-center justify-center rounded-[9px] text-slate-600 transition hover:bg-red-300/[.045] hover:text-red-300"
            >
              <LogOut className="h-4 w-4" />
            </button>
          </form>
          <button
            type="button"
            onClick={onToggle}
            title="Collapse sidebar"
            className="flex h-9 items-center justify-center rounded-[9px] text-slate-600 transition hover:bg-white/[.035] hover:text-blue-300"
          >
            <ChevronLeft className="h-4 w-4" />
          </button>
        </div>
      </div>
    </div>
  );
}

