"use client";

import {
  createContext,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";

import { AmbientGlow } from "./AmbientGlow";

import type {
  StartSystemActivityInput,
  SystemActivity,
  SystemContextValue,
  SystemTone,
  UpdateSystemActivityInput,
} from "./types";

export const SystemContext =
  createContext<SystemContextValue | null>(null);

type SystemProviderProps = {
  children: ReactNode;
};

const DEFAULT_TONE: SystemTone = "default";

function createActivityId() {
  if (
    typeof crypto !== "undefined" &&
    typeof crypto.randomUUID === "function"
  ) {
    return crypto.randomUUID();
  }

  return `system-${Date.now()}-${Math.random()
    .toString(36)
    .slice(2)}`;
}

function clampProgress(progress?: number) {
  if (typeof progress !== "number") {
    return undefined;
  }

  return Math.min(Math.max(progress, 0), 100);
}

export function SystemProvider({
  children,
}: SystemProviderProps) {
  const [tone, setToneState] =
    useState<SystemTone>(DEFAULT_TONE);

  const [activity, setActivity] =
    useState<SystemActivity | null>(null);

  const [isOnline, setIsOnline] = useState(true);

  const resetTimerRef =
    useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearResetTimer = useCallback(() => {
    if (!resetTimerRef.current) {
      return;
    }

    clearTimeout(resetTimerRef.current);
    resetTimerRef.current = null;
  }, []);

  const setTone = useCallback(
    (nextTone: SystemTone) => {
      clearResetTimer();
      setToneState(nextTone);
    },
    [clearResetTimer],
  );

  const clearActivity = useCallback(() => {
    clearResetTimer();
    setActivity(null);

    setToneState(
      typeof navigator !== "undefined" &&
        navigator.onLine === false
        ? "offline"
        : DEFAULT_TONE,
    );
  }, [clearResetTimer]);

  const startActivity = useCallback(
    (input: StartSystemActivityInput) => {
      clearResetTimer();

      const activityId =
        input.id ?? createActivityId();

      const nextActivity: SystemActivity = {
        id: activityId,
        title: input.title,
        description: input.description,
        tone: input.tone ?? "processing",
        progress: clampProgress(input.progress),
        indeterminate: input.indeterminate,
      };

      setActivity(nextActivity);
      setToneState(nextActivity.tone);

      return activityId;
    },
    [clearResetTimer],
  );

  const updateActivity = useCallback(
    (
      activityId: string,
      updates: UpdateSystemActivityInput,
    ) => {
      clearResetTimer();

      setActivity((currentActivity) => {
        if (
          !currentActivity ||
          currentActivity.id !== activityId
        ) {
          return currentActivity;
        }

        const nextActivity: SystemActivity = {
          ...currentActivity,
          ...updates,
          progress:
            updates.progress === undefined
              ? currentActivity.progress
              : clampProgress(updates.progress),
        };

        setToneState(nextActivity.tone);

        return nextActivity;
      });
    },
    [clearResetTimer],
  );

  const completeActivity = useCallback(
    (
      activityId: string,
      options?: {
        title?: string;
        description?: string;
        resetDelay?: number;
      },
    ) => {
      clearResetTimer();

      setActivity((currentActivity) => {
        if (
          !currentActivity ||
          currentActivity.id !== activityId
        ) {
          return currentActivity;
        }

        return {
          ...currentActivity,
          title:
            options?.title ??
            currentActivity.title,
          description:
            options?.description ??
            currentActivity.description,
          tone: "success",
          progress: 100,
          indeterminate: false,
        };
      });

      setToneState("success");

      resetTimerRef.current = setTimeout(() => {
        setActivity(null);

        setToneState(
          typeof navigator !== "undefined" &&
            navigator.onLine === false
            ? "offline"
            : DEFAULT_TONE,
        );

        resetTimerRef.current = null;
      }, options?.resetDelay ?? 2400);
    },
    [clearResetTimer],
  );

  const failActivity = useCallback(
    (
      activityId: string,
      options?: {
        title?: string;
        description?: string;
        critical?: boolean;
      },
    ) => {
      clearResetTimer();

      const failureTone: SystemTone =
        options?.critical
          ? "critical"
          : "warning";

      setActivity((currentActivity) => {
        if (
          !currentActivity ||
          currentActivity.id !== activityId
        ) {
          return currentActivity;
        }

        return {
          ...currentActivity,
          title:
            options?.title ??
            currentActivity.title,
          description:
            options?.description ??
            currentActivity.description,
          tone: failureTone,
          indeterminate: false,
        };
      });

      setToneState(failureTone);
    },
    [clearResetTimer],
  );

  const setOffline = useCallback(
    (description?: string) => {
      clearResetTimer();
      setIsOnline(false);
      setToneState("offline");

      setActivity({
        id: "system-offline",
        title: "Connection interrupted",
        description:
          description ??
          "Trading Docks will reconnect automatically when your connection returns.",
        tone: "offline",
        indeterminate: true,
      });
    },
    [clearResetTimer],
  );

  const setOnline = useCallback(() => {
    clearResetTimer();
    setIsOnline(true);

    setActivity((currentActivity) => {
      if (currentActivity?.id !== "system-offline") {
        return currentActivity;
      }

      return {
        id: "system-restored",
        title: "Connection restored",
        description:
          "Trading Docks is back online.",
        tone: "success",
        progress: 100,
        indeterminate: false,
      };
    });

    setToneState("success");

    resetTimerRef.current = setTimeout(() => {
      setActivity((currentActivity) =>
        currentActivity?.id === "system-restored"
          ? null
          : currentActivity,
      );

      setToneState(DEFAULT_TONE);
      resetTimerRef.current = null;
    }, 2200);
  }, [clearResetTimer]);

  useEffect(() => {
    const currentlyOnline =
      typeof navigator === "undefined"
        ? true
        : navigator.onLine;

    setIsOnline(currentlyOnline);

    if (!currentlyOnline) {
      setOffline();
    }

    function handleOffline() {
      setOffline();
    }

    function handleOnline() {
      setOnline();
    }

    window.addEventListener(
      "offline",
      handleOffline,
    );

    window.addEventListener(
      "online",
      handleOnline,
    );

    return () => {
      window.removeEventListener(
        "offline",
        handleOffline,
      );

      window.removeEventListener(
        "online",
        handleOnline,
      );
    };
  }, [setOffline, setOnline]);

  useEffect(() => {
    return () => {
      clearResetTimer();
    };
  }, [clearResetTimer]);

  const value = useMemo<SystemContextValue>(
    () => ({
      tone,
      activity,
      isOnline,
      setTone,
      startActivity,
      updateActivity,
      completeActivity,
      failActivity,
      clearActivity,
      setOffline,
      setOnline,
    }),
    [
      tone,
      activity,
      isOnline,
      setTone,
      startActivity,
      updateActivity,
      completeActivity,
      failActivity,
      clearActivity,
      setOffline,
      setOnline,
    ],
  );

  return (
    <SystemContext.Provider value={value}>
      <AmbientGlow
        tone={tone}
        activity={activity}
      />

      {children}
    </SystemContext.Provider>
  );
}

"use client";

import {
  ChevronRight,
  LoaderCircle,
  Settings2,
  TrendingUp,
  X,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";

type GameId =
  | "magic"
  | "pokemon"
  | "lorcana"
  | "one-piece"
  | "yugioh"
  | "sports";

type ScryfallCard = {
  id: string;
  name: string;
  set_name: string;
  collector_number: string;
  scryfall_uri: string;
  image_uris?: {
    small?: string;
    normal?: string;
    art_crop?: string;
  };
  card_faces?: Array<{
    image_uris?: {
      small?: string;
      normal?: string;
      art_crop?: string;
    };
  }>;
  prices?: {
    usd?: string | null;
    usd_foil?: string | null;
    usd_etched?: string | null;
  };
};

type TickerCardDefinition = {
  set: string;
  collectorNumber: string;
  fallbackPrice: number;
  percentageChange: number;
};

type TickerCard = {
  id: string;
  name: string;
  setName: string;
  imageUrl: string;
  scryfallUrl: string;
  currentPrice: number;
  previousPrice: number;
  percentageChange: number;
};

type GameOption = {
  id: GameId;
  label: string;
  abbreviation: string;
  available: boolean;
};

const CARD_DEFINITIONS: TickerCardDefinition[] = [
  {
    set: "mps",
    collectorNumber: "16",
    fallbackPrice: 164.72,
    percentageChange: 8.42,
  },
  {
    set: "all",
    collectorNumber: "28",
    fallbackPrice: 98.31,
    percentageChange: 6.91,
  },
  {
    set: "ltr",
    collectorNumber: "451",
    fallbackPrice: 143.78,
    percentageChange: 5.78,
  },
  {
    set: "usg",
    collectorNumber: "321",
    fallbackPrice: 768.41,
    percentageChange: 4.63,
  },
  {
    set: "mir",
    collectorNumber: "307",
    fallbackPrice: 271.5,
    percentageChange: 4.21,
  },
  {
    set: "c19",
    collectorNumber: "24",
    fallbackPrice: 87.16,
    percentageChange: 3.85,
  },
];

const GAME_OPTIONS: GameOption[] = [
  {
    id: "magic",
    label: "Magic: The Gathering",
    abbreviation: "MTG",
    available: true,
  },
  {
    id: "pokemon",
    label: "Pokémon",
    abbreviation: "PKM",
    available: false,
  },
  {
    id: "lorcana",
    label: "Disney Lorcana",
    abbreviation: "LOR",
    available: false,
  },
  {
    id: "one-piece",
    label: "One Piece",
    abbreviation: "OP",
    available: false,
  },
  {
    id: "yugioh",
    label: "Yu-Gi-Oh!",
    abbreviation: "YGO",
    available: false,
  },
  {
    id: "sports",
    label: "Sports Cards",
    abbreviation: "SPT",
    available: false,
  },
];

const PRICE_FORMATTER = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

function getCardImage(card: ScryfallCard): string {
  return (
    card.image_uris?.small ??
    card.image_uris?.normal ??
    card.card_faces?.[0]?.image_uris?.small ??
    card.card_faces?.[0]?.image_uris?.normal ??
    ""
  );
}

function getCardPrice(
  card: ScryfallCard,
  fallbackPrice: number,
): number {
  const rawPrice =
    card.prices?.usd ??
    card.prices?.usd_foil ??
    card.prices?.usd_etched;

  const parsedPrice = rawPrice ? Number.parseFloat(rawPrice) : NaN;

  return Number.isFinite(parsedPrice)
    ? parsedPrice
    : fallbackPrice;
}

function calculatePreviousPrice(
  currentPrice: number,
  percentageChange: number,
): number {
  return currentPrice / (1 + percentageChange / 100);
}

async function fetchCard(
  definition: TickerCardDefinition,
  signal: AbortSignal,
): Promise<TickerCard> {
  const response = await fetch(
    `https://api.scryfall.com/cards/${definition.set}/${definition.collectorNumber}`,
    {
      signal,
      headers: {
        Accept: "application/json",
      },
    },
  );

  if (!response.ok) {
    throw new Error(
      `Scryfall request failed for ${definition.set}/${definition.collectorNumber}.`,
    );
  }

  const card = (await response.json()) as ScryfallCard;
  const currentPrice = getCardPrice(
    card,
    definition.fallbackPrice,
  );

  return {
    id: card.id,
    name: card.name,
    setName: card.set_name,
    imageUrl: getCardImage(card),
    scryfallUrl: card.scryfall_uri,
    currentPrice,
    previousPrice: calculatePreviousPrice(
      currentPrice,
      definition.percentageChange,
    ),
    percentageChange: definition.percentageChange,
  };
}

export default function CardPriceTicker() {
  const [cards, setCards] = useState<TickerCard[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] =
    useState(false);
  const [selectedGames, setSelectedGames] = useState<GameId[]>([
    "magic",
  ]);
  const [tickerSpeed, setTickerSpeed] = useState(42);

  useEffect(() => {
    const controller = new AbortController();

    async function loadCards() {
      try {
        setIsLoading(true);
        setHasError(false);

        const loadedCards = await Promise.all(
          CARD_DEFINITIONS.map((definition) =>
            fetchCard(definition, controller.signal),
          ),
        );

        setCards(loadedCards);
      } catch (error) {
        if (
          error instanceof DOMException &&
          error.name === "AbortError"
        ) {
          return;
        }

        console.error("Unable to load ticker cards:", error);
        setHasError(true);
      } finally {
        if (!controller.signal.aborted) {
          setIsLoading(false);
        }
      }
    }

    void loadCards();

    return () => {
      controller.abort();
    };
  }, []);

  const tickerCards = useMemo(() => {
    if (!selectedGames.includes("magic")) {
      return [];
    }

    return [...cards, ...cards];
  }, [cards, selectedGames]);

  function toggleGame(game: GameOption) {
    if (!game.available) {
      return;
    }

    setSelectedGames((currentGames) => {
      if (currentGames.includes(game.id)) {
        return currentGames.filter(
          (gameId) => gameId !== game.id,
        );
      }

      return [...currentGames, game.id];
    });
  }

  return (
    <>
      <section className="ticker-shell">
        <div className="ticker-heading">
          <div>
            <p className="ticker-eyebrow">Price movers</p>
            <p className="ticker-subtitle">
              Live market updates
            </p>
          </div>

          <div className="ticker-game-label">MTG</div>
        </div>

        <div className="ticker-viewport">
          {isLoading ? (
            <div className="ticker-state">
              <LoaderCircle className="ticker-spinner" />
              Loading real card data…
            </div>
          ) : null}

          {!isLoading && hasError ? (
            <div className="ticker-state ticker-error">
              Scryfall data could not be loaded. Check your
              internet connection and refresh the page.
            </div>
          ) : null}

          {!isLoading &&
          !hasError &&
          tickerCards.length === 0 ? (
            <div className="ticker-state">
              Select Magic: The Gathering in ticker settings to
              display these cards.
            </div>
          ) : null}

          {!isLoading &&
          !hasError &&
          tickerCards.length > 0 ? (
            <div
              className="ticker-track"
              style={{
                animationDuration: `${tickerSpeed}s`,
              }}
            >
              {tickerCards.map((card, index) => (
                <TickerItem
                  key={`${card.id}-${index}`}
                  card={card}
                />
              ))}
            </div>
          ) : null}
        </div>

        <button
          type="button"
          className="ticker-settings-button"
          aria-label="Open ticker settings"
          onClick={() => setIsSettingsOpen(true)}
        >
          <Settings2 />
        </button>

        <div className="ticker-fade ticker-fade-left" />
        <div className="ticker-fade ticker-fade-right" />
      </section>

      {isSettingsOpen ? (
        <TickerSettings
          selectedGames={selectedGames}
          tickerSpeed={tickerSpeed}
          onClose={() => setIsSettingsOpen(false)}
          onToggleGame={toggleGame}
          onTickerSpeedChange={setTickerSpeed}
        />
      ) : null}

      <style jsx global>{`
        @keyframes trading-docks-ticker-scroll {
          from {
            transform: translate3d(0, 0, 0);
          }

          to {
            transform: translate3d(-50%, 0, 0);
          }
        }

        @keyframes trading-docks-ticker-spin {
          to {
            transform: rotate(360deg);
          }
        }

        @keyframes trading-docks-ticker-enter {
          from {
            opacity: 0;
            transform: translateY(-8px) scale(0.98);
          }

          to {
            opacity: 1;
            transform: translateY(0) scale(1);
          }
        }

        .ticker-shell {
          position: relative;
          display: grid;
          grid-template-columns: 154px minmax(0, 1fr) 54px;
          min-height: 84px;
          overflow: hidden;
          border: 1px solid rgba(34, 211, 238, 0.18);
          border-radius: 22px;
          background:
            radial-gradient(
              circle at 15% 0%,
              rgba(34, 211, 238, 0.055),
              transparent 31%
            ),
            linear-gradient(
