        }

        .ticker-speed-section {
          padding-top: 20px;
        }

        .ticker-speed-section label {
          display: block;
          margin-bottom: 11px;
          color: rgb(203, 213, 225);
          font-size: 11px;
          font-weight: 650;
        }

        .ticker-speed-section input {
          width: 100%;
          accent-color: rgb(34, 211, 238);
        }

        .ticker-speed-labels {
          display: flex;
          justify-content: space-between;
          margin-top: 7px;
          color: rgb(71, 85, 105);
          font-size: 8px;
        }

        .ticker-save-button {
          display: flex;
          width: 100%;
          height: 42px;
          align-items: center;
          justify-content: center;
          gap: 8px;
          margin-top: 20px;
          border: 1px solid rgba(103, 232, 249, 0.25);
          border-radius: 12px;
          background: rgba(34, 211, 238, 0.08);
          color: rgb(207, 250, 254);
          cursor: pointer;
          font-size: 11px;
          font-weight: 650;
          transition: 250ms ease;
        }

        .ticker-save-button:hover {
          transform: translateY(-1px);
          border-color: rgba(103, 232, 249, 0.43);
          background: rgba(34, 211, 238, 0.14);
          box-shadow: 0 0 24px rgba(34, 211, 238, 0.08);
        }

        .ticker-save-button svg {
          width: 14px;
          height: 14px;
        }

        @media (max-width: 900px) {
          .ticker-shell {
            grid-template-columns: 115px minmax(0, 1fr) 48px;
          }

          .ticker-heading {
            padding-left: 14px;
          }

          .ticker-fade-left {
            left: 115px;
          }

          .ticker-fade-right {
            right: 47px;
          }
        }

        @media (max-width: 640px) {
          .ticker-shell {
            grid-template-columns: minmax(0, 1fr) 48px;
          }

          .ticker-heading {
            display: none;
          }

          .ticker-fade-left {
            left: 0;
          }

          .ticker-item {
            width: 225px;
            min-width: 225px;
          }

          .ticker-settings-panel {
            top: auto;
            right: 16px;
            bottom: 16px;
            left: 16px;
            width: auto;
          }
        }

        @media (prefers-reduced-motion: reduce) {
          .ticker-track {
            animation-play-state: paused;
          }

          .ticker-spinner {
            animation-duration: 1.5s;
          }
        }
      `}</style>
    </>
  );
}

function TickerItem({ card }: { card: TickerCard }) {
  return (
    <a
      className="ticker-item"
      href={card.scryfallUrl}
      target="_blank"
      rel="noreferrer"
      aria-label={`View ${card.name} on Scryfall`}
    >
      <div className="ticker-card-image-frame">
        {card.imageUrl ? (
          <img
            className="ticker-card-image"
            src={card.imageUrl}
            alt={card.name}
            loading="lazy"
          />
        ) : null}
      </div>

      <div className="ticker-card-copy">
        <p className="ticker-card-name">{card.name}</p>
        <p className="ticker-card-set">{card.setName}</p>
        <p className="ticker-card-price">
          {PRICE_FORMATTER.format(card.currentPrice)}
        </p>
      </div>

      <div className="ticker-card-change">
        <TrendingUp />
        {card.percentageChange.toFixed(2)}%
      </div>

      <div className="ticker-hover-details">
        <p className="ticker-hover-title">
          Price movement
        </p>

        <div className="ticker-hover-row">
          <span>Previous price</span>
          <strong>
            {PRICE_FORMATTER.format(card.previousPrice)}
          </strong>
        </div>

        <div className="ticker-hover-row ticker-hover-row-current">
          <span>Current price</span>
          <strong>
            {PRICE_FORMATTER.format(card.currentPrice)}
          </strong>
        </div>

        <div className="ticker-hover-row ticker-hover-row-current">
          <span>Increase</span>
          <strong>
            +{card.percentageChange.toFixed(2)}%
          </strong>
        </div>
      </div>
    </a>
  );
}

type TickerSettingsProps = {
  selectedGames: GameId[];
  tickerSpeed: number;
  onClose: () => void;
  onToggleGame: (game: GameOption) => void;
  onTickerSpeedChange: (speed: number) => void;
};

function TickerSettings({
  selectedGames,
  tickerSpeed,
  onClose,
  onToggleGame,
  onTickerSpeedChange,
}: TickerSettingsProps) {
  return (
    <>
      <button
        type="button"
        className="ticker-settings-backdrop"
        aria-label="Close ticker settings"
        onClick={onClose}
      />

      <aside
        className="ticker-settings-panel"
        aria-label="Ticker settings"
      >
        <div className="ticker-settings-header">
          <div>
            <h2>Ticker settings</h2>
            <p>
              Select the games represented in your market
              ticker.
            </p>
          </div>

          <button
            type="button"
            className="ticker-close-button"
            aria-label="Close settings"
            onClick={onClose}
          >
            <X />
          </button>
        </div>

        <div className="ticker-settings-content">
          {GAME_OPTIONS.map((game) => {
            const isSelected = selectedGames.includes(game.id);

            return (
              <button
                key={game.id}
                type="button"
                className={[
                  "ticker-game-option",
                  !game.available
                    ? "ticker-game-option-disabled"
                    : "",
                ].join(" ")}
                disabled={!game.available}
                onClick={() => onToggleGame(game)}
              >
                <span className="ticker-game-icon">
                  {game.abbreviation}
                </span>

                <span className="ticker-game-name">
                  {game.label}
                </span>

                {!game.available ? (
                  <span className="ticker-game-status">
                    API needed
                  </span>
                ) : (
                  <span
                    className={[
                      "ticker-game-checkbox",
                      isSelected
                        ? "ticker-game-checkbox-active"
                        : "",
                    ].join(" ")}
                  >
                    <ChevronRight />
                  </span>
                )}
              </button>
            );
          })}

          <div className="ticker-speed-section">
            <label htmlFor="ticker-speed">
              Ticker speed
            </label>

            <input
              id="ticker-speed"
              type="range"
              min="24"
              max="70"
              step="1"
              value={tickerSpeed}
              onChange={(event) =>
                onTickerSpeedChange(
                  Number.parseInt(event.target.value, 10),
                )
              }
            />

            <div className="ticker-speed-labels">
              <span>Fast</span>
              <span>Normal</span>
              <span>Slow</span>
            </div>
          </div>

          <button
            type="button"
            className="ticker-save-button"
            onClick={onClose}
          >
            Save preferences
            <ChevronRight />
          </button>
        </div>
      </aside>
    </>
  );
}

"use client";

import {
  Check,
  ChevronRight,
  LockKeyhole,
  RotateCcw,
  X,
} from "lucide-react";

import {
