  ["automation", "Automation"],
];

const ACCOUNT_PLAN: Record<string, Plan> = {
  free: "starter",
  collector: "starter",
  seller: "pro",
  business: "business",
  store: "business",
  "large-seller": "business",
};

const ACCOUNT_LABEL: Record<string, string> = {
  free: "Free",
  collector: "Collector",
  seller: "Online Seller",
  store: "Local Game Store",
  "large-seller": "Large-volume Seller",
};

function normalizeDashboardAccountTier(accountType: string): AccountTier {
  return accountType === "collector" ||
    accountType === "seller" ||
    accountType === "store"
    ? accountType
    : "free";
}

function dashboardAccessDisplay(
  accountType: string,
  access?: ClientSafePlatformAccess,
) {
  if (access && hasTrustedFullPlatformAccess(access)) {
    const title = access.platformRole === "owner" ? "Platform Owner" : "Platform Admin";
    return {
      badge: title,
      summary: "Full platform access",
      metricLabel: title,
    };
  }

  const label =
    accountType === "store" || accountType === "business"
      ? "Store"
      : ACCOUNT_LABEL[accountType] ?? "Free";

  return {
    badge: `${label} plan`,
    summary: `${label} plan`,
    metricLabel: `${label} workspace`,
  };
}

export function ModularWorkspace({
  accountType,
  access,
  inventoryModules,
  initialLayouts,
}: {
  accountType: string;
  access?: ClientSafePlatformAccess;
  inventoryModules: string[];
  initialLayouts?: unknown;
}) {
  const plan = ACCOUNT_PLAN[accountType] ?? "starter";
  const accountTier = normalizeDashboardAccountTier(accountType);
  const hasFullPlatformAccess = Boolean(access && hasTrustedFullPlatformAccess(access));
  const display = dashboardAccessDisplay(accountType, access);
  const isPersonal = !hasFullPlatformAccess && (accountType === "free" || accountType === "collector");
  const baseLayouts = isPersonal ? COLLECTOR_LAYOUTS : DEFAULT_LAYOUTS;
  const availableLayouts = availableDashboardLayouts(accountTier, access);
  const [layoutId, setLayoutId] = useState<LayoutId>("home");
  const [layouts, setLayouts] = useState<Record<LayoutId, Widget[]>>(() => {
    if (isPersonal) return COLLECTOR_LAYOUTS;
    if (!initialLayouts || typeof initialLayouts !== "object") return baseLayouts;
    return { ...baseLayouts, ...(initialLayouts as Partial<Record<LayoutId, Widget[]>>) };
  });
  const [editing, setEditing] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);

  const widgets = layouts[layoutId];

  function updateWidgets(next: Widget[]) {
    setLayouts((current) => ({ ...current, [layoutId]: next }));
  }

  async function save() {
    try {
      await saveDashboardLayouts(layouts);
      setSaved(true);
      window.setTimeout(() => setSaved(false), 1600);
    } catch {
      setSaved(false);
    }
  }

  function reorder(targetId: string) {
    if (!draggedId || targetId === draggedId) return;
    const next = [...widgets];
    const from = next.findIndex((widget) => widget.id === draggedId);
    const to = next.findIndex((widget) => widget.id === targetId);
    if (from < 0 || to < 0) return;
    const [item] = next.splice(from, 1);
    next.splice(to, 0, item);
    updateWidgets(next);
    setDraggedId(null);
  }

  return (
    <WorkspaceFrame>
      <header className="relative overflow-hidden rounded-[24px] border border-white/[0.075] bg-[linear-gradient(145deg,rgba(7,20,31,.94),rgba(3,10,17,.98))] p-4 shadow-[0_24px_90px_rgba(0,0,0,.28)] sm:rounded-[30px] sm:p-5">
        <div className="pointer-events-none absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-cyan-200/40 to-transparent" />
        <div className="relative flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              <span className="inline-flex items-center gap-2 rounded-full border border-cyan-300/[0.14] bg-cyan-400/[0.045] px-3 py-1.5 text-[9px] font-bold uppercase tracking-[0.18em] text-cyan-200">
                <Sparkles className="h-3.5 w-3.5 text-cyan-300" />
                Command center
              </span>
              <span className="rounded-full border border-white/[0.075] bg-white/[0.025] px-3 py-1.5 text-[10px] font-semibold capitalize text-slate-400">
                {display.badge}
              </span>
            </div>

            <div className="mt-3 flex flex-col gap-1.5 sm:flex-row sm:items-end sm:gap-3">
              <h1 className="text-[1.65rem] font-semibold leading-[1.03] tracking-[-0.05em] text-white sm:text-[2.1rem]">
                Trading Docks HQ
              </h1>
              <p className="pb-1 text-xs font-medium text-slate-500 sm:text-sm">
                {inventoryModules.length > 0
                  ? `${inventoryModules.length} inventory modules enabled`
                  : "Ready for your first inventory signal"}
              </p>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-2 sm:flex sm:flex-wrap sm:items-center">
            <button
              type="button"
              onClick={() => setEditing((value) => !value)}
              className={[
                "inline-flex h-10 items-center justify-center gap-1.5 rounded-xl border px-2 text-[11px] font-semibold transition sm:gap-2 sm:px-4 sm:text-xs",
                editing
                  ? "border-cyan-300/[0.18] bg-cyan-400/[0.08] text-cyan-100"
                  : "border-white/[0.075] bg-white/[0.025] text-slate-400 hover:border-cyan-300/[0.14] hover:text-white",
              ].join(" ")}
            >
              <PanelsTopLeft className="h-4 w-4" />
              {editing ? "Done editing" : "Edit layout"}
            </button>

            <button
              type="button"
              onClick={() => setDrawerOpen(true)}
              className="inline-flex h-10 items-center justify-center gap-1.5 rounded-xl border border-white/[0.075] bg-white/[0.025] px-2 text-[11px] font-semibold text-slate-400 transition hover:border-cyan-300/[0.14] hover:text-white sm:gap-2 sm:px-4 sm:text-xs"
            >
              <Settings2 className="h-4 w-4" />
              Customize
            </button>

            <button
              type="button"
              onClick={save}
              className="inline-flex h-10 items-center justify-center gap-1.5 rounded-xl bg-gradient-to-b from-cyan-300 via-cyan-400 to-sky-500 px-2 text-[11px] font-bold text-[#001018] shadow-[0_14px_34px_rgba(8,145,178,.18)] transition hover:from-cyan-200 hover:to-sky-400 sm:gap-2 sm:px-4 sm:text-xs"
            >
              {saved ? <Check className="h-4 w-4" /> : <Save className="h-4 w-4" />}
              {saved ? "Saved" : "Save layout"}
            </button>
          </div>
        </div>

        <div className="relative mt-4 flex flex-col gap-3 border-t border-white/[0.06] pt-4 lg:flex-row lg:items-center lg:justify-between">
          <select
            value={layoutId}
            onChange={(event) => setLayoutId(event.target.value as LayoutId)}
            aria-label="Choose dashboard layout"
            className="h-11 w-full rounded-xl border border-white/[0.09] bg-[#071722] px-3 text-sm font-semibold text-white outline-none sm:hidden"
          >
            {LAYOUTS.filter(
              ([id]) => availableLayouts.has(id),
            ).map(([id, label]) => (
              <option key={id} value={id}>{label} dashboard</option>
            ))}
          </select>
          <div className="hidden flex-wrap gap-2 sm:flex">
            {LAYOUTS.filter(
              ([id]) => availableLayouts.has(id),
            ).map(([id, label]) => (
              <button
                key={id}
                type="button"
                onClick={() => setLayoutId(id)}
                className={[
                  "inline-flex h-9 items-center gap-2 rounded-xl border px-3.5 text-xs font-semibold transition",
                  layoutId === id
                    ? "border-cyan-300/[0.17] bg-cyan-400/[0.07] text-white"
                    : "border-transparent text-slate-500 hover:bg-white/[0.025] hover:text-slate-300",
                ].join(" ")}
              >
                {id === "home" ? <LayoutDashboard className="h-3.5 w-3.5" /> : null}
                {label}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-3 px-0.5 text-[10px] font-medium text-slate-500">
            <span>{widgets.length} visible modules</span>
            <span className="capitalize">
              {display.summary}
            </span>
          </div>
        </div>
      </header>

      <CommandCenterOverview isPersonal={isPersonal} accessLabel={display.metricLabel} />

      {editing ? (
        <div className="mt-4 rounded-[20px] border border-cyan-300/[0.13] bg-cyan-400/[0.035] px-4 py-3 text-xs leading-5 text-cyan-100/75 shadow-[0_18px_60px_rgba(8,145,178,.08)]">
          <span className="font-semibold text-cyan-100">Layout builder active.</span>{" "}
          Drag modules by the handle, resize them, or remove modules from this view. Save when the command center feels right.
        </div>
      ) : null}

      <div className="mt-4 grid grid-cols-2 gap-3 sm:mt-5 sm:grid-cols-1 sm:gap-4 md:grid-cols-12 xl:gap-5">
        {widgets.map((widget) => {
          const definition = DEFINITIONS[widget.id as keyof typeof DEFINITIONS];
          if (!definition) return null;
          const locked = !canUseDashboardWidget(accountTier, widget.id, access);

          return (
            <div
              key={widget.id}
              className={widget.size === "small" ? "contents" : "col-span-2 contents sm:col-span-1"}
              onDragOver={(event) => event.preventDefault()}
              onDrop={() => reorder(widget.id)}
            >
              <DashboardWidget
                widget={widget}
                definition={definition}
                locked={locked}
                editing={editing}
                onDragStart={() => setDraggedId(widget.id)}
                onRemove={() =>
                  updateWidgets(widgets.filter((item) => item.id !== widget.id))
                }
                onResize={(size) =>
                  updateWidgets(
                    widgets.map((item) =>
                      item.id === widget.id ? { ...item, size } : item,
                    ),
                  )
                }
              />
            </div>
          );
        })}
      </div>

      <CustomizeDrawer
        open={drawerOpen}
        plan={plan}
        widgets={widgets}
        onClose={() => setDrawerOpen(false)}
        onToggle={(id) => {
          const exists = widgets.some((widget) => widget.id === id);
          if (exists) {
            updateWidgets(widgets.filter((widget) => widget.id !== id));
          } else {
            updateWidgets([...widgets, { id, size: "medium" }]);
          }
        }}
      />
    </WorkspaceFrame>
  );
}

