function Sparkline({
  values,
  positive,
}: {
  values: number[];
  positive: boolean;
}) {
  const points = useMemo(() => {
    const width = 286;
    const height = 54;
    const minimum = Math.min(...values);
    const maximum = Math.max(...values);
    const spread = Math.max(1, maximum - minimum);

    return values
      .map((value, index) => {
        const x =
          values.length === 1
            ? width / 2
            : (index / (values.length - 1)) * width;
        const y =
          height -
          ((value - minimum) / spread) * (height - 8) -
          4;

        return `${x.toFixed(2)},${y.toFixed(2)}`;
      })
      .join(" ");
  }, [values]);

  return (
    <svg
      viewBox="0 0 286 54"
      aria-hidden="true"
      className="mt-7 h-[54px] w-full overflow-visible"
    >
      <polyline
        points={points}
        fill="none"
        stroke={positive ? "#55e8ff" : "#fb7185"}
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

