export async function advanceTcgTrackingMagicSync(
  database: TcgTrackingSyncClient,
  input: AdvanceTcgTrackingSyncInput,
): Promise<AdvanceTcgTrackingSyncResult> {
  const provider = input.client ?? createTcgTrackingClient({
    timeoutMs: 20_000,
    retries: 0,
  });
  const category = input.category ?? "magic";
  const run = await getOrCreateRun(database, input.syncType);
  if (run.status === "schema_required") return run;

  try {
    const sets = await provider.sets(category);
    const checkpoint = run.run?.checkpoint ?? {};
    const startIndex = numberValue(checkpoint.setIndex) ?? 0;
    const setLimit = input.setLimit ?? TCGTRACKING_SYNC_SET_LIMIT;
    const productLimit = input.productLimit ?? TCGTRACKING_SYNC_PRODUCT_LIMIT;
    const selectedSets = sets.slice(startIndex, startIndex + setLimit);

    let processed = 0;
    let failed = 0;
    for (const set of selectedSets) {
      if (input.syncType === "product_mappings") {
        const cards = await provider.cards(category, set.id);
        const rows = cards
          .slice(0, productLimit)
          .map((product) => mappingRowFromTcgTrackingProduct({
            ...product,
            categoryId: SYNC_MAGIC_CATEGORY_ID,
            setId: product.setId ?? set.id,
            setCode: product.setCode ?? set.abbreviation,
          }))
          .filter((row): row is TcgTrackingMappingRow => Boolean(row));
        processed += rows.length;
        await upsertRows(database, "tcgtracking_product_mappings", rows, "category_id,tcgplayer_product_id");
      } else if (input.syncType === "price_snapshots") {
        const snapshots = await provider.pricing(category, set.id);
        const rows = snapshots
          .map((snapshot) =>
            priceSnapshotRowFromTcgTracking(snapshot, SYNC_MAGIC_CATEGORY_ID),
          )
          .filter((row): row is TcgTrackingPriceSnapshotRow => Boolean(row))
          .slice(0, productLimit);
        processed += rows.length;
        await insertRows(database, "tcgtracking_price_snapshots", rows);
      }
    }

    const nextSetIndex = startIndex + selectedSets.length;
    const completed = nextSetIndex >= sets.length || selectedSets.length === 0;
    const updatedRun = await updateRun(database, run.run?.id, {
      status: completed ? "completed" : "processing",
      checkpoint: {
        setIndex: nextSetIndex,
        setCount: sets.length,
        lastSetId: selectedSets.at(-1)?.id ?? checkpoint.lastSetId ?? null,
      },
      processed: (run.run?.processed ?? 0) + processed,
      updated: run.run?.updated ?? 0,
      inserted: (run.run?.inserted ?? 0) + processed,
      failed: (run.run?.failed ?? 0) + failed,
      completed_at: completed ? new Date().toISOString() : null,
      error_summary: null,
    });

    return {
      status: completed ? "completed" : "advanced",
      run: updatedRun,
      processed,
      inserted: processed,
      updated: 0,
      failed,
      currentSet: selectedSets.at(-1)?.name ?? null,
    };
  } catch (error) {
    const message = error instanceof Error
      ? error.message
      : "TCGTracking sync failed.";
    if (run.run?.id) {
      await updateRun(database, run.run.id, {
        status: "failed",
        error_summary: message,
        failed: (run.run.failed ?? 0) + 1,
      }).catch(() => null);
    }
    return {
      status: "provider_failed",
      run: run.run,
      processed: 0,
      inserted: 0,
      updated: 0,
      failed: 1,
      message,
    };
  }
}

export function latestSyncByType(runs: TcgTrackingSyncRunRow[]) {
  return {
    mapping: runs.find((run) => run.sync_type === "product_mappings") ?? null,
    pricing: runs.find((run) => run.sync_type === "price_snapshots") ?? null,
    reconciliation: runs.find((run) => run.sync_type === "sample_reconciliation") ?? null,
  };
}

async function getOrCreateRun(
  database: TcgTrackingSyncClient,
  syncType: TcgTrackingSyncType,
): Promise<
  | { status: "ready"; run: TcgTrackingSyncRunRow }
  | { status: "schema_required"; processed: 0; inserted: 0; updated: 0; failed: 0; message: string }
> {
  const existing = await database
    .from("tcgtracking_sync_runs")
    .select("id,category_id,sync_type,status,checkpoint,processed,inserted,updated,failed,error_summary,started_at,completed_at,updated_at")
    .eq("category_id", SYNC_MAGIC_CATEGORY_ID)
    .eq("sync_type", syncType)
    .in("status", ["queued", "processing", "failed", "paused"])
    .order("started_at", { ascending: false })
    .limit(1);

  if (existing.error) return schemaRequired(existing.error.message);
  const current = Array.isArray(existing.data)
    ? existing.data[0] as TcgTrackingSyncRunRow | undefined
    : undefined;
  if (current) {
    if (current.status === "failed" || current.status === "paused") {
      const resumed = await updateRun(database, current.id, {
        status: "processing",
        error_summary: null,
      });
      return { status: "ready", run: resumed ?? current };
    }
    return { status: "ready", run: current };
  }

  const created = await database
    .from("tcgtracking_sync_runs")
    .insert({
      category_id: SYNC_MAGIC_CATEGORY_ID,
      sync_type: syncType,
      status: "processing",
      checkpoint: {},
    })
    .select("id,category_id,sync_type,status,checkpoint,processed,inserted,updated,failed,error_summary,started_at,completed_at,updated_at")
    .single();
  if (created.error) return schemaRequired(created.error.message);
  return { status: "ready", run: created.data as TcgTrackingSyncRunRow };
}

async function upsertRows(
  database: TcgTrackingSyncClient,
  table: string,
  rows: unknown[],
  onConflict: string,
) {
  if (!rows.length) return;
  const result = await database.from(table).upsert(rows, { onConflict });
  if (result.error) {
    throw new Error(result.error.message ?? `Could not upsert ${table}.`);
  }
}

async function insertRows(
  database: TcgTrackingSyncClient,
  table: string,
  rows: unknown[],
) {
  if (!rows.length) return;
  const result = await database.from(table).insert(rows);
  if (result.error) {
    throw new Error(result.error.message ?? `Could not insert ${table}.`);
  }
}

async function updateRun(
  database: TcgTrackingSyncClient,
  id: string | undefined,
  values: Partial<TcgTrackingSyncRunRow>,
) {
  if (!id) return null;
  const updated = await database
    .from("tcgtracking_sync_runs")
    .update(values)
    .eq("id", id)
    .select("id,category_id,sync_type,status,checkpoint,processed,inserted,updated,failed,error_summary,started_at,completed_at,updated_at")
    .single();
  if (updated.error) {
    throw new Error(updated.error.message ?? "Could not update TCGTracking sync run.");
  }
  return updated.data as TcgTrackingSyncRunRow;
}

function schemaRequired(message?: string) {
  return {
    status: "schema_required" as const,
    processed: 0 as const,
    inserted: 0 as const,
    updated: 0 as const,
    failed: 0 as const,
    message:
      message ??
      "TCGTracking enrichment cache tables are not installed. Review and apply the proposal migration before running sync.",
  };
}

function uuidOrNull(value: string | undefined) {
  if (!value) return null;
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)
    ? value
    : null;
}

function numberValue(value: unknown) {
  return typeof value === "number" && Number.isSafeInteger(value)
    ? value
    : undefined;
}

import type { PlatformAccessContext } from "@/lib/platform/client-access";
import {
  normalizeCount,
  normalizeMoney,
  normalizePaymentMethod,
  normalizePurchaseSource,
  normalizePurchaseStatus,
  type NewPurchaseInput,
  type PurchaseHistoryFilters,
  type PurchaseLedgerLine,
  type PurchaseLedgerRecord,
} from "./ledger.ts";

type SupabaseResult<T> = {
  data: T | null;
  error: { code?: string; message?: string; details?: string; hint?: string } | null;
};

type SupabaseClientLike = {
  from: (table: string) => {
    select: (columns: string) => QueryBuilderLike;
    insert: (values: unknown) => QueryBuilderLike;
  };
};

type QueryBuilderLike = PromiseLike<SupabaseResult<unknown>> & {
  eq: (column: string, value: string) => QueryBuilderLike;
  order: (column: string, options?: { ascending?: boolean }) => QueryBuilderLike;
  limit: (count: number) => QueryBuilderLike;
  select: (columns: string) => QueryBuilderLike;
  single: () => PromiseLike<SupabaseResult<unknown>>;
};

export type PurchaseHistoryLoadResult = {
  records: PurchaseLedgerRecord[];
  schemaAvailable: boolean;
  warning: string | null;
};

function isMissingSchemaError(error: { code?: string; message?: string } | null) {
  if (!error) return false;
  return error.code === "42P01" ||
    error.code === "PGRST205" ||
    /purchase_ledger/i.test(error.message ?? "") && /not exist|schema cache/i.test(error.message ?? "");
}

function objectRecord(value: unknown) {
  return value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
}

function stringValue(value: unknown) {
  return typeof value === "string" ? value : "";
}

function nullableString(value: unknown) {
  return typeof value === "string" && value.trim() ? value : null;
}

function normalizeProductType(value: unknown) {
  const raw = String(value ?? "").trim().toLowerCase();
  if (raw === "sealed" || raw === "sealed_product" || raw === "unopened") return "sealed";
  if (raw === "card" || raw === "single" || raw === "singles") return "card";
  return null;
}

function timestampValue(value: unknown) {
  return typeof value === "string" && value.trim()
    ? value
    : new Date().toISOString();
}

function lineFromRow(row: Record<string, unknown>): PurchaseLedgerLine {
  const details = objectRecord(row.details);
  return {
    id: stringValue(row.id),
    purchaseId: stringValue(row.purchase_id),
    lineType: stringValue(row.line_type) || "line",
    description: stringValue(row.description),
    quantity: normalizeCount(row.quantity),
    unitCount: normalizeCount(row.unit_count),
    unitCost: normalizeMoney(row.unit_cost),
    totalCost: normalizeMoney(row.total_cost),
    inventoryItemId: nullableString(row.inventory_item_id),
    gameId: nullableString(details.gameId ?? details.game_id),
    productType: normalizeProductType(details.productType ?? details.product_type),
    variant: nullableString(details.variant),
    language: nullableString(details.language),
    details,
  };
}

export function purchaseRecordFromRow(row: Record<string, unknown>): PurchaseLedgerRecord {
  const rawLines = Array.isArray(row.purchase_ledger_lines)
    ? row.purchase_ledger_lines
    : [];
  return {
    id: stringValue(row.id),
    userId: stringValue(row.user_id),
    workspaceId: nullableString(row.workspace_id),
    sourceType: normalizePurchaseSource(row.source_type),
    sellerName: stringValue(row.seller_name),
    sellerCustomerId: nullableString(row.seller_customer_id),
    vendorId: nullableString(row.vendor_id),
    status: normalizePurchaseStatus(row.status),
    paymentMethod: normalizePaymentMethod(row.payment_method),
    subtotal: normalizeMoney(row.subtotal),
    adjustment: normalizeMoney(row.adjustment),
    totalCost: normalizeMoney(row.total_cost),
    itemCount: normalizeCount(row.item_count),
    unitCount: normalizeCount(row.unit_count),
    createdBy: stringValue(row.created_by),
    purchasedAt: timestampValue(row.purchased_at),
    receivedAt: nullableString(row.received_at),
    notes: stringValue(row.notes),
    details: objectRecord(row.details),
    lines: rawLines.map((line) => lineFromRow(objectRecord(line))),
  };
}

export async function loadPurchaseHistory(
  supabase: unknown,
  access: PlatformAccessContext,
  _filters: PurchaseHistoryFilters = {},
): Promise<PurchaseHistoryLoadResult> {
  const client = supabase as SupabaseClientLike;
  let query = client
    .from("purchase_ledger")
    .select(`
      id,user_id,workspace_id,source_type,seller_name,seller_customer_id,vendor_id,
      status,payment_method,subtotal,adjustment,total_cost,item_count,unit_count,
      created_by,purchased_at,received_at,notes,details,
      purchase_ledger_lines(
        id,purchase_id,line_type,description,quantity,unit_count,unit_cost,total_cost,
        inventory_item_id,details
      )
    `)
    .order("purchased_at", { ascending: false })
    .limit(250);

  if (access.workspaceId) {
    query = query.eq("workspace_id", access.workspaceId);
  } else if (access.userId) {
    query = query.eq("user_id", access.userId);
  }

  const { data, error } = await query as SupabaseResult<unknown>;
  if (isMissingSchemaError(error)) {
    return {
      records: [],
      schemaAvailable: false,
      warning: "The canonical Purchase History schema has not been applied to this Supabase project yet.",
    };
  }
  if (error) {
    return {
      records: [],
      schemaAvailable: true,
      warning: error.message ?? "Purchase History could not be loaded.",
    };
  }

  return {
    records: Array.isArray(data)
      ? data.map((row) => purchaseRecordFromRow(objectRecord(row)))
      : [],
    schemaAvailable: true,
    warning: null,
  };
}

export async function createPurchaseLedgerRecord({
  supabase,
  access,
  userId,
  purchase,
}: {
  supabase: unknown;
  access: PlatformAccessContext;
  userId: string;
  purchase: NewPurchaseInput;
}) {
  const client = supabase as SupabaseClientLike;
  const now = new Date().toISOString();
  const { data, error } = await client
    .from("purchase_ledger")
    .insert({
      user_id: userId,
      workspace_id: access.workspaceId,
      source_type: purchase.sourceType,
      seller_name: purchase.sellerName ?? "",
      seller_customer_id: purchase.sellerCustomerId ?? null,
      vendor_id: purchase.vendorId ?? null,
      status: purchase.status ?? "pending",
      payment_method: purchase.paymentMethod ?? "unknown",
      subtotal: normalizeMoney(purchase.subtotal),
      adjustment: normalizeMoney(purchase.adjustment),
      total_cost: normalizeMoney(purchase.totalCost),
      item_count: normalizeCount(purchase.itemCount),
      unit_count: normalizeCount(purchase.unitCount),
      created_by: userId,
      purchased_at: purchase.purchasedAt ?? now,
      received_at: purchase.receivedAt ?? null,
      notes: purchase.notes ?? "",
      details: purchase.details ?? {},
    })
    .select("id")
    .single() as SupabaseResult<unknown>;

  if (error) return { data: null, error };
  const purchaseId = stringValue(objectRecord(data).id);
  if (!purchaseId) {
    return { data: null, error: { message: "Purchase record was created without a returned id." } };
  }

  const lines = purchase.lines.map((line) => {
    const details = {
      ...(line.details ?? {}),
      ...(line.gameId ? { gameId: line.gameId, game_id: line.gameId } : {}),
      ...(line.productType ? { productType: line.productType, product_type: line.productType } : {}),
      ...(line.variant ? { variant: line.variant } : {}),
      ...(line.language ? { language: line.language } : {}),
    };
    return {
      purchase_id: purchaseId,
      line_type: line.lineType,
      description: line.description,
      quantity: normalizeCount(line.quantity),
      unit_count: normalizeCount(line.unitCount),
      unit_cost: normalizeMoney(line.unitCost),
      total_cost: normalizeMoney(line.totalCost),
      inventory_item_id: line.inventoryItemId ?? null,
      details,
    };
  });

  const lineResult = await client
    .from("purchase_ledger_lines")
    .insert(lines)
    .select("id") as SupabaseResult<unknown>;

  if (lineResult.error) return { data: null, error: lineResult.error };
  return { data: { id: purchaseId }, error: null };
}

