function commanderCandidate(
  inventoryId: string,
  name: string,
  colorIdentity: CollectionGraphCard["colorIdentity"] = ["G"],
): CollectionGraphCard {
  return {
    inventoryId,
    name,
    quantityOwned: 0,
    typeLine: "Legendary Creature - Human Wizard",
    oracleText: "Whenever you cast a spell, draw a card.",
    colorIdentity,
    marketPrice: null,
    legalities: { commander: "legal" },
  };
